--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: add_payment_to_invoice(uuid, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_payment_to_invoice(p_invoice_id uuid, p_amount numeric, p_method text, p_notes text, p_center_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_student_id UUID;
  v_month INT;
  v_year INT;
  v_total_amount NUMERIC;
  v_new_paid NUMERIC;
  v_new_status TEXT;
BEGIN
  -- 1. Get Invoice Details
  SELECT student_id, month, year, total_amount
  INTO v_student_id, v_month, v_year, v_total_amount
  FROM student_invoices
  WHERE id = p_invoice_id AND center_id = p_center_id;

  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  -- 2. Insert into invoice_payments (the CORRECT table)
  INSERT INTO invoice_payments (
    invoice_id,
    amount,
    payment_method,
    notes,
    paid_at,
    created_at
  ) VALUES (
    p_invoice_id,
    p_amount,
    COALESCE(p_method, 'cash'),
    COALESCE(p_notes, 'سداد فاتورة ' || v_month || '/' || v_year),
    NOW(),
    NOW()
  );

  -- 3. Calculate new paid_amount from invoice_payments (single source of truth)
  SELECT COALESCE(SUM(amount), 0) INTO v_new_paid
  FROM invoice_payments
  WHERE invoice_id = p_invoice_id;

  -- 4. Determine new status
  IF v_new_paid >= v_total_amount - 0.5 THEN
    v_new_status := 'paid';
  ELSE
    v_new_status := 'partial';
  END IF;

  -- 5. Update Invoice
  UPDATE student_invoices
  SET
    paid_amount = v_new_paid,
    status = v_new_status,
    paid_date = CASE WHEN v_new_status = 'paid' THEN NOW() ELSE paid_date END,
    updated_at = NOW()
  WHERE id = p_invoice_id;

END;
$$;


