--
-- Name: admin_upsert_user(uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_upsert_user(p_user_id uuid, p_full_name text, p_phone text, p_role text, p_center_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Verify caller is admin of the center
    IF NOT EXISTS (SELECT 1 FROM public.centers WHERE id = p_center_id AND admin_user_id = auth.uid()) THEN
        RAISE EXCEPTION 'Unauthorized: You are not admin of this center';
    END IF;
    
    -- Upsert the user
    INSERT INTO public.users (id, full_name, phone, role, default_center_id, is_active)
    VALUES (p_user_id, p_full_name, p_phone, p_role, p_center_id, true)
    ON CONFLICT (id) DO UPDATE SET
        full_name = EXCLUDED.full_name,
        phone = EXCLUDED.phone,
        role = EXCLUDED.role,
        default_center_id = EXCLUDED.default_center_id,
        is_active = EXCLUDED.is_active;
END;
$$;


ALTER FUNCTION public.admin_upsert_user(p_user_id uuid, p_full_name text, p_phone text, p_role text, p_center_id uuid) OWNER TO postgres;

--
-- Name: analyze_tables(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.analyze_tables(p_table_names text[] DEFAULT NULL::text[]) RETURNS TABLE(table_name text, status text, message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    tbl TEXT;
    tables_to_analyze TEXT[];
BEGIN
    IF p_table_names IS NULL THEN
        tables_to_analyze := ARRAY[
            'payments', 'invoices', 'student_enrollments', 'teacher_enrollments',
            'attendance', 'grades', 'courses', 'schedules', 'notifications',
            'analytics_events', 'audit_log_enhanced'
        ];
    ELSE
        tables_to_analyze := p_table_names;
    END IF;
    
    FOREACH tbl IN ARRAY tables_to_analyze
    LOOP
        BEGIN
            EXECUTE format('ANALYZE public.%I', tbl);
            RETURN QUERY SELECT tbl, 'success'::TEXT, 'تم تحليل الجدول بنجاح'::TEXT;
        EXCEPTION WHEN OTHERS THEN
            RETURN QUERY SELECT tbl, 'error'::TEXT, SQLERRM;
        END;
    END LOOP;
END;
$$;


ALTER FUNCTION public.analyze_tables(p_table_names text[]) OWNER TO postgres;

