-- Name: FUNCTION analyze_tables(p_table_names text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.analyze_tables(p_table_names text[]) IS 'تحليل الجداول وتحديث إحصائيات المحلل - يُنصح بتشغيله يومياً';


--
-- Name: audit_financial_changes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.audit_financial_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_center_id UUID;
  v_user_id UUID;
  v_old_data JSONB;
  v_new_data JSONB;
BEGIN
  -- تحديد المستخدم (إن وجد)
  v_user_id := auth.uid();
  
  -- تحديد الـ center_id والبيانات
  IF (TG_OP = 'DELETE') THEN
    v_center_id := OLD.center_id;
    v_old_data := to_jsonb(OLD);
    v_new_data := null;
  ELSIF (TG_OP = 'UPDATE') THEN
    v_center_id := NEW.center_id;
    v_old_data := to_jsonb(OLD);
    v_new_data := to_jsonb(NEW);
  ELSIF (TG_OP = 'INSERT') THEN
    v_center_id := NEW.center_id;
    v_old_data := null;
    v_new_data := to_jsonb(NEW);
  END IF;

  -- تسجيل العملية
  INSERT INTO financial_audit_logs (
    center_id,
    table_name,
    record_id,
    action_type,
    changed_by,
    old_data,
    new_data
  ) VALUES (
    v_center_id,
    TG_TABLE_NAME::TEXT,
    COALESCE(NEW.id, OLD.id),
    TG_OP,
    v_user_id,
    v_old_data,
    v_new_data
  );

  RETURN NULL; -- Trigger is AFTER, return value ignored
END;
$$;


ALTER FUNCTION public.audit_financial_changes() OWNER TO postgres;

--
-- Name: audit_trigger_func(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.audit_trigger_func() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    old_data JSONB;
    new_data JSONB;
    changed_fields JSONB;
    current_user_id UUID;
BEGIN
    -- محاولة الحصول على user_id
    BEGIN
        current_user_id := auth.uid();
    EXCEPTION WHEN OTHERS THEN
        current_user_id := NULL;
    END;

    IF (TG_OP = 'DELETE') THEN
        old_data = to_jsonb(OLD);
        new_data = NULL;
        changed_fields = NULL;
    ELSIF (TG_OP = 'UPDATE') THEN
        old_data = to_jsonb(OLD);
        new_data = to_jsonb(NEW);
        
        -- حساب الحقول المتغيرة فقط
        SELECT jsonb_object_agg(key, value)
        INTO changed_fields
        FROM jsonb_each(new_data)
        WHERE value IS DISTINCT FROM old_data->key;
        
    ELSIF (TG_OP = 'INSERT') THEN
        old_data = NULL;
        new_data = to_jsonb(NEW);
        changed_fields = NULL;
    END IF;

    -- تسجيل في جدول Audit
    BEGIN
        INSERT INTO public.audit_log_enhanced (
            table_name,
            record_id,
            action,
            user_id,
            old_data,
            new_data,
            changed_fields,
            ip_address,
            created_at
        ) VALUES (
            TG_TABLE_NAME,
            COALESCE(NEW.id, OLD.id),
            TG_OP,
            current_user_id,
            old_data,
            new_data,
            changed_fields,
            inet_client_addr(),
            NOW()
        );
    EXCEPTION WHEN OTHERS THEN
        -- تجاهل الأخطاء في Audit لعدم تعطيل العمليات الأساسية
        RAISE WARNING 'Audit log failed: %', SQLERRM;
    END;

    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.audit_trigger_func() OWNER TO postgres;

--
-- Name: FUNCTION audit_trigger_func(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.audit_trigger_func() IS 'دالة التدقيق التلقائي للجداول الحساسة';


--
-- Name: auto_generate_parent_code_fn(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_generate_parent_code_fn() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- توليد كود ولي الأمر إذا لم يكن موجوداً
    IF NEW.parent_invitation_code IS NULL THEN
        NEW.parent_invitation_code := 'P' || UPPER(SUBSTRING(MD5(RANDOM()::TEXT || CLOCK_TIMESTAMP()::TEXT) FROM 1 FOR 7));
    END IF;
    RETURN NEW;
END;
$$;


