-- Name: auto_set_active_center(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_set_active_center() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'accepted' AND (OLD.status IS NULL OR OLD.status != 'accepted') THEN
    UPDATE profiles
    SET active_center_id = NEW.center_id
    WHERE user_id = NEW.student_user_id
      AND active_center_id IS NULL;
  END IF;
  RETURN NEW;
END;
$$;


