-- Name: award_xp(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.award_xp(p_student_id uuid, p_amount integer, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Update Student Profile
    INSERT INTO public.student_gamification_profiles (student_id, total_xp, current_level, last_activity_date)
    VALUES (p_student_id, p_amount, 1, CURRENT_DATE)
    ON CONFLICT (student_id) DO UPDATE
    SET 
        total_xp = student_gamification_profiles.total_xp + p_amount,
        last_activity_date = CURRENT_DATE;
        
    -- Update Squad XP
    UPDATE public.squads
    SET total_xp = total_xp + p_amount
    WHERE id = (
        SELECT squad_id FROM public.squad_members WHERE student_id = p_student_id LIMIT 1
    );
END;
$$;


