--
-- Name: calculate_attendance_rate(uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_attendance_rate(p_student_user_id uuid, p_center_id uuid, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  total_records INTEGER;
  present_records INTEGER;
  rate NUMERIC;
BEGIN
  -- Get student_id from enrollment
  SELECT COUNT(*), COUNT(*) FILTER (WHERE a.status IN ('present', 'late'))
  INTO total_records, present_records
  FROM attendance a
  JOIN student_enrollments se ON se.student_id = a.student_id
  WHERE se.student_user_id = p_student_user_id
    AND se.center_id = p_center_id
    AND (p_from_date IS NULL OR a.date >= p_from_date)
    AND (p_to_date IS NULL OR a.date <= p_to_date);
  
  IF total_records = 0 THEN
    RETURN 100; -- No records = 100% (no absences)
  END IF;
  
  rate := (present_records::NUMERIC / total_records::NUMERIC) * 100;
  RETURN ROUND(rate, 1);
END;
$$;


ALTER FUNCTION public.calculate_attendance_rate(p_student_user_id uuid, p_center_id uuid, p_from_date date, p_to_date date) OWNER TO postgres;

--
-- Name: calculate_detailed_attendance_rate(uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_detailed_attendance_rate(p_user_id uuid DEFAULT NULL::uuid, p_center_id uuid DEFAULT NULL::uuid, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_student_id UUID;
  v_total INTEGER;
  v_present INTEGER;
  v_absent INTEGER;
  v_late INTEGER;
  v_excused INTEGER;
  v_rate NUMERIC;
BEGIN
  SELECT s.id INTO v_student_id FROM students s WHERE s.user_id = auth.uid() LIMIT 1;
  IF v_student_id IS NULL THEN v_student_id := auth.uid(); END IF;

  SELECT 
    COUNT(*), 
    COUNT(*) FILTER (WHERE status = 'present'),
    COUNT(*) FILTER (WHERE status = 'absent'),
    COUNT(*) FILTER (WHERE status = 'late'),
    COUNT(*) FILTER (WHERE status = 'excused')
  INTO v_total, v_present, v_absent, v_late, v_excused
  FROM attendance
  WHERE student_id = v_student_id
  AND (p_center_id IS NULL OR center_id = p_center_id)
  AND (p_start_date IS NULL OR attendance_date >= p_start_date)
  AND (p_end_date IS NULL OR attendance_date <= p_end_date);

  IF v_total > 0 THEN
    v_rate := ROUND(((v_present + v_late)::NUMERIC / v_total::NUMERIC) * 100, 1);
  ELSE
    v_rate := 0;
  END IF;

  RETURN jsonb_build_object(
    'total_sessions', v_total,
    'present', v_present,
    'absent', v_absent,
    'late', v_late,
    'excused', v_excused,
    'attendance_rate', v_rate
  );
END;
$$;


ALTER FUNCTION public.calculate_detailed_attendance_rate(p_user_id uuid, p_center_id uuid, p_start_date date, p_end_date date) OWNER TO postgres;

