--
-- Name: calculate_prorated_invoice(uuid, numeric, date, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_prorated_invoice(p_group_id uuid, p_monthly_price numeric, p_join_date date, p_month integer, p_year integer) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_month_start DATE;
  v_month_end DATE;
  v_total_sessions INT := 0;
  v_remaining_sessions INT := 0;
  v_schedule_days TEXT[];
  v_calculation_log TEXT;
BEGIN
  v_month_start := make_date(p_year, p_month, 1);
  v_month_end := (v_month_start + INTERVAL '1 month' - INTERVAL '1 day')::date;

  -- 1. Get Group Schedule Days (e.g. ['0', '2'] for Sun, Tue)
  -- Assumes schedules.day_of_week uses Postgres DOW (0=Sun, 6=Sat) format as stored in DB
  SELECT ARRAY_AGG(day_of_week) INTO v_schedule_days
  FROM schedules
  WHERE group_id = p_group_id;

  IF v_schedule_days IS NULL THEN
    -- No schedule, assume full price (safest fallback)
    RETURN p_monthly_price;
  END IF;

  -- 2. Count TOTAL sessions in month
  SELECT COUNT(*) INTO v_total_sessions
  FROM generate_series(v_month_start, v_month_end, '1 day'::interval) AS day_date
  WHERE EXTRACT(DOW FROM day_date)::text = ANY(v_schedule_days);

  -- 3. Count REMAINING sessions (from join_date)
  -- If join date is before month start, use month start.
  -- If join date is after month end, 0 sessions.
  IF p_join_date > v_month_end THEN
    v_remaining_sessions := 0;
  ELSE
    SELECT COUNT(*) INTO v_remaining_sessions
    FROM generate_series(
      GREATEST(p_join_date, v_month_start), 
      v_month_end, 
      '1 day'::interval
    ) AS day_date
    WHERE EXTRACT(DOW FROM day_date)::text = ANY(v_schedule_days);
  END IF;

  -- 4. Calculate Ratio
  IF v_total_sessions = 0 THEN
    RETURN 0;
  END IF;

  -- Return rounded calculated price
  RETURN ROUND((p_monthly_price / v_total_sessions) * v_remaining_sessions, 2);
    
END;
$$;


ALTER FUNCTION public.calculate_prorated_invoice(p_group_id uuid, p_monthly_price numeric, p_join_date date, p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: calculate_teacher_monthly_sessions(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_teacher_monthly_sessions(p_teacher_id uuid, p_month integer, p_year integer) RETURNS TABLE(group_id uuid, group_name text, session_count bigint, session_rate numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_center_id UUID;
  v_subscription_type TEXT;
BEGIN
  -- Get center_id and subscription_type for this teacher
  SELECT 
    c.id, c.subscription_type 
  INTO 
    v_center_id, v_subscription_type
  FROM centers c
  JOIN teacher_enrollments te ON c.id = te.center_id
  WHERE te.teacher_id = p_teacher_id
  LIMIT 1;

  RETURN QUERY
  SELECT 
    g.id as group_id,
    g.group_name,
    COUNT(a.id) as session_count,
    CASE 
      WHEN v_subscription_type = 'basic' THEN
         -- Basic: Monthly Fee is the Per-Session Price
         COALESCE(g.monthly_fee, 0)
      ELSE
         -- Premium: Monthly Fee is per month, so Per-Session is / 4.0
         COALESCE(g.monthly_fee / 4.0, 0)
    END as session_rate
  FROM groups g
  LEFT JOIN attendance a ON g.id = a.group_id
    AND EXTRACT(MONTH FROM a.date) = p_month
    AND EXTRACT(YEAR FROM a.date) = p_year
  WHERE g.teacher_id = p_teacher_id
    AND g.is_active = true
  GROUP BY g.id, g.group_name, g.monthly_fee;
END;
$$;


ALTER FUNCTION public.calculate_teacher_monthly_sessions(p_teacher_id uuid, p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: calculate_teacher_percentage_salary(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_teacher_percentage_salary(p_teacher_id uuid, p_center_id uuid, p_month integer, p_year integer) RETURNS TABLE(group_id uuid, group_name text, student_count bigint, monthly_fee numeric, fees_collected numeric, teacher_percentage numeric, teacher_earnings numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  WITH teacher_groups AS (
    SELECT 
      g.id as gid,
      g.group_name as gname,
      g.monthly_fee as gfee
    FROM groups g
    WHERE g.teacher_id = p_teacher_id
      AND g.center_id = p_center_id
      AND g.is_active = true
  ),
  group_students AS (
    -- ✅ FIX: Read from invoice_payments via student_invoices
    SELECT 
      tg.gid,
      tg.gname,
      tg.gfee,
      COUNT(DISTINCT sge.student_id) as paid_students,
      COALESCE(SUM(ip.amount), 0) as total_paid
    FROM teacher_groups tg
    LEFT JOIN student_group_enrollments sge ON sge.group_id = tg.gid AND sge.status = 'active'
    LEFT JOIN student_invoices si ON si.student_id = sge.student_id 
      AND si.center_id = p_center_id
      AND si.month = p_month 
      AND si.year = p_year
    LEFT JOIN invoice_payments ip ON ip.invoice_id = si.id
    GROUP BY tg.gid, tg.gname, tg.gfee
  ),
  teacher_salary_info AS (
    SELECT 
      te.salary_amount as percentage
    FROM teacher_enrollments te
    WHERE te.teacher_id = p_teacher_id
      AND te.center_id = p_center_id
      AND te.employment_status = 'active'
    LIMIT 1
  )
  SELECT 
    gs.gid as group_id,
    gs.gname as group_name,
    gs.paid_students as student_count,
    gs.gfee as monthly_fee,
    gs.total_paid as fees_collected,
    COALESCE(tsi.percentage, 0) as teacher_percentage,
    (gs.total_paid * COALESCE(tsi.percentage, 0) / 100) as teacher_earnings
  FROM group_students gs
  CROSS JOIN teacher_salary_info tsi;
END;
$$;


ALTER FUNCTION public.calculate_teacher_percentage_salary(p_teacher_id uuid, p_center_id uuid, p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: FUNCTION calculate_teacher_percentage_salary(p_teacher_id uuid, p_center_id uuid, p_month integer, p_year integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.calculate_teacher_percentage_salary(p_teacher_id uuid, p_center_id uuid, p_month integer, p_year integer) IS 'Calculates teacher earnings based on percentage of fees collected from their groups';


--
-- Name: calculate_teacher_salary_v2(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_teacher_salary_v2(p_center_id uuid, p_teacher_id uuid, p_month integer, p_year integer) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_start_date TIMESTAMP;
  v_end_date TIMESTAMP;
  
  v_total_collected DECIMAL(10, 2) := 0;
  v_applied_percentage DECIMAL(5, 2) := 0;
  v_base_salary DECIMAL(10, 2) := 0;
  
  v_bonuses DECIMAL(10, 2) := 0;
  v_deductions DECIMAL(10, 2) := 0;
  v_net_salary DECIMAL(10, 2) := 0;
  
  v_tier_info JSON;
BEGIN
  v_start_date := make_timestamp(p_year, p_month, 1, 0, 0, 0);
  v_end_date := (v_start_date + INTERVAL '1 month' - INTERVAL '1 second');

  -- 1. Calculate Total Collected Revenue (Scoped to Center)
  WITH payment_shares AS (
    SELECT 
      ip.amount as payment_amount,
      si.total_amount as invoice_total,
      (
        SELECT COALESCE(SUM(amount), 0)
        FROM invoice_items ii 
        WHERE ii.invoice_id = si.id 
          AND ii.teacher_id = p_teacher_id
      ) as teacher_invoice_total
    FROM invoice_payments ip
    JOIN student_invoices si ON ip.invoice_id = si.id
    WHERE ip.paid_at BETWEEN v_start_date AND v_end_date
      AND si.center_id = p_center_id -- Scope to Center
      AND si.status != 'void'
      AND EXISTS (SELECT 1 FROM invoice_items ii WHERE ii.invoice_id = si.id AND ii.teacher_id = p_teacher_id)
  )
  SELECT 
    COALESCE(SUM(
      CASE 
        WHEN invoice_total > 0 THEN (payment_amount * (teacher_invoice_total / invoice_total))
        ELSE 0 
      END
    ), 0)
  INTO v_total_collected
  FROM payment_shares;

  -- 2. Determine Tier Percentage (Scoped to Center)
  SELECT percentage 
  INTO v_applied_percentage
  FROM teacher_salary_tiers
  WHERE center_id = p_center_id
    AND teacher_id = p_teacher_id
    AND v_total_collected >= min_revenue
    AND v_total_collected <= max_revenue
  ORDER BY min_revenue DESC
  LIMIT 1;

  IF v_applied_percentage IS NULL THEN
     v_applied_percentage := 0;
  END IF;

  -- 3. Calculate Base Salary
  v_base_salary := v_total_collected * (v_applied_percentage / 100);

  -- 4. Calculate Bonuses & Deductions (Scoped to Center)
  SELECT 
    COALESCE(SUM(CASE WHEN amount > 0 THEN amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN amount < 0 THEN ABS(amount) ELSE 0 END), 0)
  INTO v_bonuses, v_deductions
  FROM teacher_bonuses
  WHERE center_id = p_center_id
    AND teacher_id = p_teacher_id
    AND month = p_month
    AND year = p_year;

  -- 5. Net Salary
  v_net_salary := v_base_salary + v_bonuses - v_deductions;

  RETURN json_build_object(
    'total_collected', v_total_collected,
    'applied_percentage', v_applied_percentage,
    'base_salary', v_base_salary,
    'bonuses', v_bonuses,
    'deductions', v_deductions,
    'net_salary', v_net_salary,
    'period_start', v_start_date,
    'period_end', v_end_date
  );
END;
$$;


ALTER FUNCTION public.calculate_teacher_salary_v2(p_center_id uuid, p_teacher_id uuid, p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: check_attendance_risk(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_attendance_risk() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_consecutive_absences INTEGER;
  v_student_name TEXT;
  v_group_name TEXT;
  v_user_id UUID;
BEGIN
  -- Only care if status is 'absent'
  IF NEW.status = 'absent' THEN
    
    -- Count consecutive absences (limit 3)
    -- We look at the last 3 records for this student/group ordered by date desc
    SELECT COUNT(*) INTO v_consecutive_absences
    FROM (
      SELECT status FROM attendance
      WHERE student_id = NEW.student_id 
        AND group_id = NEW.group_id
      ORDER BY date DESC
      LIMIT 3
    ) last_records
    WHERE status = 'absent';

    -- If 3 or more (including this one), TRIGGER ALERT
    IF v_consecutive_absences >= 3 THEN
      -- Get student details
      -- Note: You might need to adjust table/column names based on your exact schema
      SELECT full_name, user_id INTO v_student_name, v_user_id 
      FROM students 
      WHERE id = NEW.student_id;
      
      -- Fallback if user_id in students is null, try enrollment
      IF v_user_id IS NULL THEN
         SELECT student_user_id INTO v_user_id 
         FROM student_enrollments 
         WHERE student_id = NEW.student_id LIMIT 1;
      END IF;

      -- Get group name
      SELECT name INTO v_group_name FROM groups WHERE id = NEW.group_id;

      -- Insert Notification for Center Admin
      -- Note: We need to find the admin. For now, we'll assign to the student themselves (test) OR better, to the system/admin user
      -- For this specific request, we will skip finding the exact admin ID dynamically effectively without more context.
      -- BUT, to make it work, let's insert a notification where user_id is the Center Owner.
      
      -- Find Center Admin
      DECLARE
        v_admin_id UUID;
      BEGIN
        SELECT admin_user_id INTO v_admin_id FROM centers WHERE id = (SELECT center_id FROM groups WHERE id = NEW.group_id);
        
        IF v_admin_id IS NOT NULL THEN
          INSERT INTO notifications (user_id, title, body, type, priority, data)
          VALUES (
            v_admin_id, 
            '⚠️ تنبيه خطر انسحاب', 
            'الطالب ' || COALESCE(v_student_name, 'Unknown') || ' غاب 3 حصص متتالية في مجموعة ' || COALESCE(v_group_name, 'Unknown'), 
            'risk_alert', 
            'high',
            jsonb_build_object('student_id', NEW.student_id, 'action', 'call')
          );
        END IF;
      END;
      
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.check_attendance_risk() OWNER TO postgres;

--
-- Name: check_consecutive_absences(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_consecutive_absences() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  r RECORD;
BEGIN
  -- البحث عن الطلاب الغائبين حصتين متتاليتين
  FOR r IN
    WITH recent_attendance AS (
      SELECT 
        a.student_id,
        a.center_id,
        a.date as session_date,  -- ✅ FIXED: Use 'date' column instead of 'session_date'
        a.status,
        ROW_NUMBER() OVER (PARTITION BY a.student_id ORDER BY a.date DESC) as rn
      FROM attendance a
      WHERE a.date >= NOW() - INTERVAL '14 days'  -- ✅ FIXED: Use 'date' column
    ),
    consecutive_absences AS (
      SELECT 
        student_id,
        center_id,
        COUNT(*) as absent_streak
      FROM recent_attendance
      WHERE rn <= 2  -- آخر حصتين فقط
        AND status = 'absent'
      GROUP BY student_id, center_id
      HAVING COUNT(*) >= 2
    )
    SELECT 
      ca.student_id,
      ca.center_id,
      u.full_name as student_name,
      ca.absent_streak
    FROM consecutive_absences ca
    JOIN students s ON ca.student_id = s.id
    JOIN users u ON s.user_id = u.id
    -- لا نكرر الإشعار إذا أرسلناه خلال 7 أيام
    WHERE NOT EXISTS (
      SELECT 1 FROM notifications n
      WHERE n.center_id = ca.center_id
        AND n.type = 'absence_streak'
        AND (n.data->>'student_id')::uuid = ca.student_id
        AND n.created_at > NOW() - INTERVAL '7 days'
    )
  LOOP
    PERFORM create_notification(
      r.center_id,
      'absence_streak',
      'high',
      '🚨 غياب متتالي',
      format('الطالب %s غائب %s حصص متتالية', r.student_name, r.absent_streak::text),
      jsonb_build_object(
        'student_id', r.student_id,
        'absent_count', r.absent_streak,
        'route', '/students/' || r.student_id::text
      )
    );
  END LOOP;
END;
$$;


ALTER FUNCTION public.check_consecutive_absences() OWNER TO postgres;

--
-- Name: check_daily_reminders(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_daily_reminders() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_user_id UUID;
    v_center_id UUID;
    v_count INTEGER := 0;
    v_notifications_sent INTEGER := 0;
BEGIN
    v_user_id := auth.uid();
    
    -- Get Center ID
    SELECT center_id INTO v_center_id FROM center_users WHERE user_id = v_user_id LIMIT 1;
    IF v_center_id IS NULL THEN RETURN json_build_object('status', 'no_center'); END IF;

    -- 1. Check Upcoming Sessions Today (that haven't been notified yet logic is complex without state, 
    -- so we will just check if attendance is NOT taken for sessions starting soon).
    
    -- (Simplified: Just count sessions today for the user)
    SELECT COUNT(*) INTO v_count
    FROM group_schedules gs
    WHERE gs.center_id = v_center_id
    AND gs.day_of_week = (EXTRACT(DOW FROM CURRENT_DATE)::INTEGER)
    AND gs.deleted_at IS NULL;

    IF v_count > 0 THEN
        -- Check if we already sent a reminder today (Logic depends on notification history)
        -- For now, we assume this function updates a "last_checked" state in app, 
        -- or strictly returns data for the app to decide.
        
        -- Let's return the data to the App, and let the App show a UI Alert/Snack bar
        -- instead of creating a DB notification to avoid duplicates on every refresh.
        RETURN json_build_object(
            'status', 'success',
            'sessions_today', v_count,
            'message', 'لديك ' || v_count || ' حصص مجدولة اليوم. لا تنس تحضير الطلاب!'
        );
    END IF;

    RETURN json_build_object('status', 'none');
END;
$$;


