--
-- Name: check_group_capacity_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_group_capacity_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_capacity INTEGER;
  v_current_count INTEGER;
  v_group_name TEXT;
  v_center_id UUID;
  v_admin_id UUID;
BEGIN
  -- Get Group Info
  SELECT name, capacity, center_id INTO v_group_name, v_capacity, v_center_id
  FROM groups WHERE id = NEW.group_id;
  
  -- Get Current Count
  SELECT count(*) INTO v_current_count 
  FROM student_group_enrollment 
  WHERE group_id = NEW.group_id AND is_active = true;
  
  -- Check Threshold (90%)
  IF v_capacity > 0 AND v_current_count >= (v_capacity * 0.9) THEN
    -- Find Admin
    SELECT admin_user_id INTO v_admin_id FROM centers WHERE id = v_center_id;
    
    IF v_admin_id IS NOT NULL THEN
       -- Check if we already sent a notification recently to avoid spam? (Optional, skipping for MVP)
       
       INSERT INTO notifications (user_id, title, body, type, priority, data)
       VALUES (
         v_admin_id,
         '🔥 تنبيه سعة المجموعة',
         'المجموعة ' || v_group_name || ' أوشكت على الامتلاء (' || v_current_count || '/' || v_capacity || ')',
         'warning',
         'high',
         jsonb_build_object('group_id', NEW.group_id, 'route', '/groups')
       );
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


