--
-- Name: check_schedule_conflict(uuid, uuid, uuid, time without time zone, time without time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_schedule_conflict(p_center_id uuid, p_classroom_id uuid, p_teacher_user_id uuid, p_start_time time without time zone, p_end_time time without time zone, p_day_of_week text, p_exclude_schedule_id uuid DEFAULT NULL::uuid) RETURNS TABLE(conflict_type text, conflict_message text, conflicting_schedule_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
    -- تضارب الفصل
    IF p_classroom_id IS NOT NULL THEN
        RETURN QUERY
        SELECT 
            'classroom'::TEXT,
            'الفصل محجوز في هذا الوقت'::TEXT,
            s.id
        FROM schedules s
        WHERE s.center_id = p_center_id
        AND s.classroom_id = p_classroom_id
        AND s.day_of_week = p_day_of_week
        AND (p_exclude_schedule_id IS NULL OR s.id != p_exclude_schedule_id)
        AND (s.deleted_at IS NULL OR s.deleted_at > NOW())
        AND (s.start_time, s.end_time) OVERLAPS (p_start_time, p_end_time)
        LIMIT 1;
    END IF;
    
    -- تضارب المعلم
    IF p_teacher_user_id IS NOT NULL THEN
        RETURN QUERY
        SELECT 
            'teacher'::TEXT,
            'المعلم لديه حصة أخرى في هذا الوقت'::TEXT,
            s.id
        FROM schedules s
        WHERE s.center_id = p_center_id
        AND s.teacher_user_id = p_teacher_user_id
        AND s.day_of_week = p_day_of_week
        AND (p_exclude_schedule_id IS NULL OR s.id != p_exclude_schedule_id)
        AND (s.deleted_at IS NULL OR s.deleted_at > NOW())
        AND (s.start_time, s.end_time) OVERLAPS (p_start_time, p_end_time)
        LIMIT 1;
    END IF;
END;
$$;


ALTER FUNCTION public.check_schedule_conflict(p_center_id uuid, p_classroom_id uuid, p_teacher_user_id uuid, p_start_time time without time zone, p_end_time time without time zone, p_day_of_week text, p_exclude_schedule_id uuid) OWNER TO postgres;

