--
-- Name: check_schedule_time_conflict(uuid, time without time zone, time without time zone, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_schedule_time_conflict(p_center_id uuid, p_start_time time without time zone, p_end_time time without time zone, p_day_of_week text, p_classroom_id uuid DEFAULT NULL::uuid, p_exclude_schedule_id uuid DEFAULT NULL::uuid) RETURNS TABLE(conflict_exists boolean, conflicting_schedule_id uuid, conflict_message text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        TRUE as conflict_exists,
        s.id as conflicting_schedule_id,
        'تضارب في المواعيد - الوقت محجوز بالفعل'::TEXT as conflict_message
    FROM public.schedules s
    WHERE s.center_id = p_center_id
    AND s.day_of_week = p_day_of_week
    AND (p_classroom_id IS NULL OR s.classroom_id = p_classroom_id)
    AND (p_exclude_schedule_id IS NULL OR s.id != p_exclude_schedule_id)
    AND (
        (s.start_time, s.end_time) OVERLAPS (p_start_time, p_end_time)
    )
    LIMIT 1;
    
    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, NULL::TEXT;
    END IF;
END;
$$;


