--
-- Name: claim_student_profile(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_student_profile(p_invitation_code text, p_device_id text, p_device_info jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_enrollment_id UUID;
  v_existing_user_id UUID;
  v_student_id UUID;
  v_student_name TEXT;
BEGIN
  -- Get current Auth User
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- 1. Find the enrollment with this code
  SELECT id, student_user_id, student_id 
  INTO v_enrollment_id, v_existing_user_id, v_student_id
  FROM public.student_enrollments
  WHERE invitation_code = p_invitation_code;

  IF v_enrollment_id IS NULL THEN
    RAISE EXCEPTION 'كود الدعوة غير صحيح';
  END IF;

  -- 2. Check if enrollment is already claimed
  IF v_existing_user_id IS NOT NULL THEN
    IF v_existing_user_id != auth.uid() THEN
      RAISE EXCEPTION 'هذا الكود مستخدم بالفعل';
    END IF;
  END IF;

  -- 3. Link Enrollment to Auth User
  UPDATE public.student_enrollments
  SET student_user_id = auth.uid(),
      updated_at = NOW()
  WHERE id = v_enrollment_id;

  -- 4. Link Student Profile & Sync Name
  IF v_student_id IS NOT NULL THEN
     -- Get Real Name from Students table
     SELECT full_name INTO v_student_name FROM public.students WHERE id = v_student_id;

     -- Link Student to User
     UPDATE public.students
     SET user_id = auth.uid(),
         last_login_at = NOW(),
         updated_at = NOW()
     WHERE id = v_student_id;
     
     -- CRITICAL FIX: Update public.users full_name with the Real Name from students table
     IF v_student_name IS NOT NULL THEN
         UPDATE public.users
         SET full_name = v_student_name
         WHERE id = auth.uid();
     END IF;

     -- Bind Device
     INSERT INTO public.student_devices (student_id, device_id, device_info)
     VALUES (v_student_id, p_device_id, p_device_info)
     ON CONFLICT (student_id, device_id) DO UPDATE 
     SET last_login_at = NOW(),
         device_info = COALESCE(EXCLUDED.device_info, student_devices.device_info);
  END IF;

  RETURN json_build_object(
    'success', true,
    'message', 'Profile claimed and name synced',
    'student_id', v_student_id
  );
END;
$$;


ALTER FUNCTION public.claim_student_profile(p_invitation_code text, p_device_id text, p_device_info jsonb) OWNER TO postgres;

--
-- Name: claim_teacher_invitation(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_teacher_invitation(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_inv RECORD;
    v_user_id UUID;
    v_teacher_id UUID;
BEGIN
    v_user_id := auth.uid();
    
    IF v_user_id IS NULL THEN
        RETURN '{"success": false, "error": "يجب تسجيل الدخول أولاً"}'::JSONB;
    END IF;
    
    -- البحث بالكود (العمود اسمه code)
    SELECT ti.*, c.name as center_name
    INTO v_inv
    FROM public.teacher_invitations ti
    JOIN public.centers c ON ti.center_id = c.id
    WHERE UPPER(ti.code) = UPPER(p_code);
    
    IF v_inv IS NULL THEN
        RETURN '{"success": false, "error": "كود الدعوة غير صحيح"}'::JSONB;
    END IF;
    
    IF v_inv.used = true THEN
        RETURN '{"success": false, "error": "هذا الكود مستخدم بالفعل"}'::JSONB;
    END IF;
    
    IF v_inv.expires_at IS NOT NULL AND v_inv.expires_at < NOW() THEN
        RETURN '{"success": false, "error": "انتهت صلاحية هذا الكود"}'::JSONB;
    END IF;
    
    -- تحديث المستخدم
    UPDATE public.users 
    SET role = 'teacher', 
        full_name = COALESCE(NULLIF(full_name, ''), v_inv.teacher_name),
        updated_at = NOW()
    WHERE id = v_user_id;
    
    -- إنشاء سجل المعلم
    INSERT INTO public.teachers (user_id, email)
    SELECT v_user_id, email FROM public.users WHERE id = v_user_id
    ON CONFLICT (user_id) DO NOTHING;
    
    SELECT id INTO v_teacher_id FROM public.teachers WHERE user_id = v_user_id;
    
    -- تسجيل المعلم في السنتر
    INSERT INTO public.teacher_enrollments (
        teacher_user_id, teacher_id, center_id, status, employment_status
    ) VALUES (
        v_user_id, v_teacher_id, v_inv.center_id, 'active', 'active'
    )
    ON CONFLICT DO NOTHING;
    
    -- تحديث الدعوة
    UPDATE public.teacher_invitations
    SET used = true, used_at = NOW()
    WHERE id = v_inv.id;
    
    RETURN jsonb_build_object(
        'success', true,
        'message', 'مرحباً بك في ' || v_inv.center_name || '!',
        'center_id', v_inv.center_id,
        'center_name', v_inv.center_name
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION public.claim_teacher_invitation(p_code text) OWNER TO postgres;

--
-- Name: cleanup_old_data(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cleanup_old_data() RETURNS TABLE(table_name text, deleted_count bigint, cleanup_date timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    deleted_rows BIGINT;
BEGIN
    -- حذف Analytics events الأقدم من سنة
    DELETE FROM public.analytics_events 
    WHERE created_at < NOW() - INTERVAL '1 year';
    
    GET DIAGNOSTICS deleted_rows = ROW_COUNT;
    RETURN QUERY SELECT 'analytics_events'::TEXT, deleted_rows, NOW();
    
    -- حذف Audit logs الأقدم من 6 أشهر
    DELETE FROM public.audit_log 
    WHERE created_at < NOW() - INTERVAL '6 months';
    
    GET DIAGNOSTICS deleted_rows = ROW_COUNT;
    RETURN QUERY SELECT 'audit_log'::TEXT, deleted_rows, NOW();
    
    -- حذف Audit logs enhanced الأقدم من 6 أشهر
    DELETE FROM public.audit_log_enhanced 
    WHERE created_at < NOW() - INTERVAL '6 months';
    
    GET DIAGNOSTICS deleted_rows = ROW_COUNT;
    RETURN QUERY SELECT 'audit_log_enhanced'::TEXT, deleted_rows, NOW();
    
    -- حذف Notifications القديمة المقروءة (أقدم من 3 أشهر)
    DELETE FROM public.notifications 
    WHERE read_at IS NOT NULL 
    AND read_at < NOW() - INTERVAL '3 months';
    
    GET DIAGNOSTICS deleted_rows = ROW_COUNT;
    RETURN QUERY SELECT 'notifications'::TEXT, deleted_rows, NOW();
    
    -- حذف Content access logs القديمة (أقدم من سنة)
    DELETE FROM public.content_access_log 
    WHERE accessed_at < NOW() - INTERVAL '1 year';
    
    GET DIAGNOSTICS deleted_rows = ROW_COUNT;
    RETURN QUERY SELECT 'content_access_log'::TEXT, deleted_rows, NOW();
    
    -- حذف User sessions القديمة (أقدم من 30 يوم)
    DELETE FROM public.user_sessions 
    WHERE last_activity < NOW() - INTERVAL '30 days';
    
    GET DIAGNOSTICS deleted_rows = ROW_COUNT;
    RETURN QUERY SELECT 'user_sessions'::TEXT, deleted_rows, NOW();
    
END;
$$;


