COMMENT ON FUNCTION public.cleanup_old_data() IS 'تنظيف البيانات القديمة غير الضرورية - يُنصح بتشغيله شهرياً';


--
-- Name: cleanup_soft_deleted_records(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cleanup_soft_deleted_records(days_to_keep integer DEFAULT 90) RETURNS TABLE(table_name text, deleted_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    tbl RECORD;
    deleted_rows BIGINT;
BEGIN
    FOR tbl IN 
        SELECT tablename 
        FROM pg_tables 
        WHERE schemaname = 'public' 
        AND tablename IN (
            SELECT table_name 
            FROM information_schema.columns 
            WHERE table_schema = 'public' 
            AND column_name = 'deleted_at'
        )
    LOOP
        EXECUTE format(
            'DELETE FROM public.%I WHERE deleted_at < NOW() - INTERVAL ''%s days'' AND deleted_at IS NOT NULL',
            tbl.tablename,
            days_to_keep
        );
        
        GET DIAGNOSTICS deleted_rows = ROW_COUNT;
        
        IF deleted_rows > 0 THEN
            RETURN QUERY SELECT tbl.tablename::TEXT, deleted_rows;
        END IF;
    END LOOP;
END;
$$;


