--
-- Name: FUNCTION cleanup_soft_deleted_records(days_to_keep integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cleanup_soft_deleted_records(days_to_keep integer) IS 'حذف السجلات المحذوفة نهائياً بعد فترة محددة';


--
-- Name: create_community_post(text, text, text, uuid, text[], text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_community_post(p_title text, p_content text DEFAULT NULL::text, p_post_type text DEFAULT 'question'::text, p_subject_id uuid DEFAULT NULL::uuid, p_topic_tags text[] DEFAULT ARRAY[]::text[], p_attachment_url text DEFAULT NULL::text, p_attachment_type text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_new_post_id UUID;
  v_academic_year TEXT;
  v_center_id UUID;
BEGIN
  -- Get center from profiles
  SELECT active_center_id INTO v_center_id
  FROM profiles
  WHERE user_id = auth.uid();
  
  -- Get academic_year from students table  
  SELECT academic_year INTO v_academic_year
  FROM students
  WHERE user_id = auth.uid();
  
  -- Debug logging
  RAISE NOTICE 'User ID: %, Center: %, Academic Year: %', auth.uid(), v_center_id, v_academic_year;
  
  -- Validate academic year exists
  IF v_academic_year IS NULL THEN
    RAISE EXCEPTION 'يجب تحديد السنة الدراسية أولاً في الملف الشخصي';
  END IF;
  
  -- Create the post
  INSERT INTO community_posts (
    author_id,
    author_center_id,
    academic_year,
    post_type,
    title,
    content,
    subject_id,
    topic_tags,
    attachment_url,
    attachment_type,
    ai_review_status,
    created_at,
    updated_at
  ) VALUES (
    auth.uid(),
    v_center_id,
    v_academic_year,
    p_post_type,
    p_title,
    p_content,
    p_subject_id,
    p_topic_tags,
    p_attachment_url,
    p_attachment_type,
    'safe',
    now(),
    now()
  )
  RETURNING id INTO v_new_post_id;
  
  RETURN v_new_post_id;
END;
$$;


ALTER FUNCTION public.create_community_post(p_title text, p_content text, p_post_type text, p_subject_id uuid, p_topic_tags text[], p_attachment_url text, p_attachment_type text) OWNER TO postgres;

--
-- Name: create_default_center_for_new_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_default_center_for_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    new_center_id UUID;
    user_full_name TEXT;
    user_phone TEXT;
    existing_center_id UUID;
BEGIN
    -- الحصول على بيانات المستخدم من metadata
    user_full_name := COALESCE(
        (NEW.raw_user_meta_data->>'full_name')::TEXT,
        'مدير السنتر'
    );
    
    user_phone := COALESCE(
        (NEW.raw_user_meta_data->>'phone')::TEXT,
        ''
    );

    -- تحقق ما إذا كان هناك سنتر موجود لهذا المستخدم
    SELECT id INTO existing_center_id FROM public.centers WHERE admin_user_id = NEW.id LIMIT 1;

    IF existing_center_id IS NOT NULL THEN
        -- استخدم المعرف الموجود
        new_center_id := existing_center_id;
    ELSE
        -- إنشاء سنتر جديد للمستخدم
        INSERT INTO public.centers (
            id,
            name,
            admin_user_id,
            address,
            city,
            governorate,
            phone,
            email,
            subscription_plan,
            subscription_start,
            subscription_end,
            max_students,
            max_teachers,
            max_subjects,
            is_active,
            created_at,
            updated_at
        ) VALUES (
            gen_random_uuid(),
            'سنتر ' || user_full_name,
            NEW.id,
            'العنوان غير محدد',
            '',
            '',
            user_phone,
            NEW.email,
            'basic',
            NOW(),
            NOW() + INTERVAL '30 days',
            100,
            10,
            20,
            true,
            NOW(),
            NOW()
        ) RETURNING id INTO new_center_id;
    END IF;

    -- تحديث metadata للمستخدم بمعرف السنتر (يحافظ على المفاتيح الموجودة)
    UPDATE auth.users
    SET raw_user_meta_data = COALESCE(raw_user_meta_data, '{}'::jsonb) || 
        jsonb_build_object(
            'center_id', new_center_id,
            'default_center_id', new_center_id,
            'role', COALESCE((NEW.raw_user_meta_data->>'role')::TEXT, 'center_admin'),
            'user_type', COALESCE((NEW.raw_user_meta_data->>'user_type')::TEXT, 'center_admin')
        )
    WHERE id = NEW.id;

    RAISE NOTICE 'تم إنشاء/استخدام سنتر: % للمستخدم: %', new_center_id, NEW.id;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.create_default_center_for_new_user() OWNER TO postgres;

--
-- Name: create_default_center_for_new_user(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_default_center_for_new_user(p_user_id uuid, p_full_name text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_center_id uuid;
BEGIN
  -- create center
  INSERT INTO public.centers(name, admin_user_id, created_at, updated_at)
  VALUES (COALESCE(p_full_name, 'Center') || ' Center', p_user_id, now(), now())
  RETURNING id INTO v_center_id;

  -- upsert profile: set active_center_id and full_name if missing
  INSERT INTO public.profiles(user_id, active_center_id, full_name, created_at, updated_at)
  VALUES (p_user_id, v_center_id, p_full_name, now(), now())
  ON CONFLICT (user_id) DO UPDATE
  SET active_center_id = EXCLUDED.active_center_id,
      full_name = COALESCE(NULLIF(profiles.full_name, ''), EXCLUDED.full_name),
      updated_at = now();

  -- update auth.users raw_user_meta_data to include center_id (keep existing keys)
  UPDATE auth.users
  SET raw_user_meta_data = jsonb_set(coalesce(raw_user_meta_data, '{}'::jsonb), '{center_id}', to_jsonb(v_center_id::text), true)
  WHERE id = p_user_id;
END;
$$;


ALTER FUNCTION public.create_default_center_for_new_user(p_user_id uuid, p_full_name text) OWNER TO postgres;

