-- Name: create_teacher_invitation(uuid, text, text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_teacher_invitation(p_center_id uuid, p_teacher_name text, p_teacher_phone text DEFAULT NULL::text, p_teacher_email text DEFAULT NULL::text, p_specialization text DEFAULT NULL::text, p_salary_type text DEFAULT 'percentage'::text, p_salary_amount numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_code TEXT;
BEGIN
    v_code := 'T' || UPPER(SUBSTRING(MD5(RANDOM()::TEXT || NOW()::TEXT) FROM 1 FOR 7));
    
    INSERT INTO public.teacher_invitations (
        center_id, invitation_code, teacher_name, teacher_phone, 
        teacher_email, specialization, salary_type, salary_amount, created_by
    ) VALUES (
        p_center_id, v_code, p_teacher_name, p_teacher_phone,
        p_teacher_email, p_specialization, p_salary_type, p_salary_amount, auth.uid()
    );
    
    RETURN jsonb_build_object(
        'success', true,
        'invitation_code', v_code,
        'message', 'كود الدعوة: ' || v_code
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


