--
-- Name: deactivate_device(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.deactivate_device(p_device_id text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_student_id UUID;
  v_updated INTEGER;
BEGIN
  SELECT id INTO v_student_id FROM public.students WHERE user_id = auth.uid();

  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'غير مصرح';
  END IF;

  UPDATE public.student_devices
  SET is_active = false
  WHERE student_id = v_student_id AND device_id = p_device_id;
  
  GET DIAGNOSTICS v_updated = ROW_COUNT;

  IF v_updated = 0 THEN
    RETURN json_build_object('success', false, 'message', 'الجهاز غير موجود');
  END IF;

  RETURN json_build_object('success', true, 'message', 'تم إلغاء الجهاز');
END;
$$;


ALTER FUNCTION public.deactivate_device(p_device_id text) OWNER TO postgres;

--
-- Name: debug_student_data(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.debug_student_data() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_id UUID;
  v_student_id UUID;
  v_student_id_from_enrollment UUID;
  v_result jsonb;
BEGIN
  v_user_id := auth.uid();
  
  -- البحث عن student_id
  SELECT id INTO v_student_id FROM students WHERE user_id = v_user_id LIMIT 1;
  SELECT student_id INTO v_student_id_from_enrollment FROM student_enrollments WHERE student_user_id = v_user_id LIMIT 1;
  
  SELECT jsonb_build_object(
    'auth_user_id', v_user_id,
    'student_found', v_student_id IS NOT NULL,
    'student_id_from_students_table', v_student_id,
    'student_id_from_enrollment', v_student_id_from_enrollment,
    'enrollments_count', (SELECT COUNT(*) FROM student_enrollments WHERE student_user_id = v_user_id),
    'groups_count', (SELECT COUNT(*) FROM student_group_enrollments WHERE student_id = COALESCE(v_student_id, v_student_id_from_enrollment, v_user_id)),
    'group_schedules_count', (
      SELECT COUNT(*) FROM group_schedules gs
      JOIN student_group_enrollments sge ON sge.group_id = gs.group_id
      WHERE sge.student_id = COALESCE(v_student_id, v_student_id_from_enrollment, v_user_id)
    ),
    'groups_with_schedule_in_groups_table', (
      SELECT COUNT(*) FROM groups g
      JOIN student_group_enrollments sge ON sge.group_id = g.id
      WHERE sge.student_id = COALESCE(v_student_id, v_student_id_from_enrollment, v_user_id)
      AND g.day_of_week IS NOT NULL
    ),
    'enrollments', (
      SELECT jsonb_agg(jsonb_build_object(
        'enrollment_id', se.id,
        'student_id', se.student_id,
        'center_id', se.center_id,
        'status', se.status
      ))
      FROM student_enrollments se
      WHERE se.student_user_id = v_user_id
    ),
    'groups', (
      SELECT jsonb_agg(jsonb_build_object(
        'group_id', g.id,
        'group_name', g.group_name,
        'center_id', g.center_id,
        'day_of_week', g.day_of_week,
        'start_time', g.start_time,
        'end_time', g.end_time,
        'has_group_schedule', EXISTS(SELECT 1 FROM group_schedules gs WHERE gs.group_id = g.id)
      ))
      FROM groups g
      JOIN student_group_enrollments sge ON sge.group_id = g.id
      WHERE sge.student_id = COALESCE(v_student_id, v_student_id_from_enrollment, v_user_id)
    )
  ) INTO v_result;
  
  RETURN v_result;
END;
$$;


