--
-- Name: end_attendance_session(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.end_attendance_session(p_session_id uuid, p_mark_absent boolean DEFAULT true) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_session RECORD;
  v_absent_count INTEGER := 0;
BEGIN
  SELECT * INTO v_session
  FROM attendance_sessions WHERE id = p_session_id;
  
  IF v_session IS NULL THEN
    RETURN 'جلسة غير موجودة';
  END IF;
  
  -- Mark absent students if requested
  IF p_mark_absent THEN
    INSERT INTO attendance (center_id, group_id, student_id, date, status)
    SELECT 
      v_session.center_id,
      v_session.group_id,
      sge.student_id,
      v_session.session_date,
      'absent'
    FROM student_group_enrollments sge
    WHERE sge.group_id = v_session.group_id
      AND sge.status = 'active'
      AND NOT EXISTS (
        SELECT 1 FROM attendance a
        WHERE a.group_id = v_session.group_id
          AND a.student_id = sge.student_id
          AND a.date = v_session.session_date
      );
    
    GET DIAGNOSTICS v_absent_count = ROW_COUNT;
  END IF;
  
  -- Update session status
  UPDATE attendance_sessions
  SET status = 'completed', updated_at = NOW()
  WHERE id = p_session_id;
  
  RETURN 'تم إنهاء الجلسة. تم تسجيل ' || v_absent_count || ' غائب';
END;
$$;


ALTER FUNCTION public.end_attendance_session(p_session_id uuid, p_mark_absent boolean) OWNER TO postgres;

--
-- Name: ensure_student_exists(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ensure_student_exists() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_student_id UUID;
  v_user_record RECORD;
  v_result jsonb;
  v_enrollments_updated INT := 0;
  v_group_enrollments_updated INT := 0;
BEGIN
  v_user_id := auth.uid();
  
  -- التحقق من تسجيل الدخول
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'User not authenticated',
      'error_ar', 'المستخدم غير مسجل الدخول'
    );
  END IF;
  
  -- جلب بيانات المستخدم من جدول users
  SELECT id, full_name, email, phone, avatar_url
  INTO v_user_record
  FROM users
  WHERE id = v_user_id;
  
  IF v_user_record.id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'User record not found',
      'error_ar', 'لم يتم العثور على بيانات المستخدم'
    );
  END IF;
  
  -- البحث عن سجل طالب موجود
  SELECT id INTO v_student_id FROM students WHERE user_id = v_user_id LIMIT 1;
  
  -- إذا لم يوجد سجل طالب، أنشئ واحداً جديداً
  IF v_student_id IS NULL THEN
    INSERT INTO students (
      user_id,
      full_name,
      phone,
      email,
      created_at,
      updated_at
    ) VALUES (
      v_user_id,
      COALESCE(v_user_record.full_name, 'طالب جديد'),
      v_user_record.phone,
      v_user_record.email,
      NOW(),
      NOW()
    )
    RETURNING id INTO v_student_id;
    
    RAISE NOTICE 'Created new student record: %', v_student_id;
    
    -- تحديث student_enrollments لربط student_id الجديد
    UPDATE student_enrollments
    SET student_id = v_student_id,
        updated_at = NOW()
    WHERE student_user_id = v_user_id
    AND (student_id IS NULL OR student_id = v_user_id);
    
    GET DIAGNOSTICS v_enrollments_updated = ROW_COUNT;
    
    -- تحديث student_group_enrollments أيضاً
    -- بعض الأنظمة تستخدم user_id مباشرة كـ student_id
    UPDATE student_group_enrollments
    SET student_id = v_student_id,
        updated_at = NOW()
    WHERE student_id = v_user_id;
    
    GET DIAGNOSTICS v_group_enrollments_updated = ROW_COUNT;
    
    v_result := jsonb_build_object(
      'success', true,
      'created', true,
      'student_id', v_student_id,
      'user_id', v_user_id,
      'enrollments_updated', v_enrollments_updated,
      'group_enrollments_updated', v_group_enrollments_updated,
      'message', 'Student record created and linked successfully',
      'message_ar', 'تم إنشاء سجل الطالب وربطه بنجاح'
    );
  ELSE
    -- سجل الطالب موجود، تحقق من الربط
    -- تأكد من أن student_enrollments مربوط بشكل صحيح
    UPDATE student_enrollments
    SET student_id = v_student_id,
        updated_at = NOW()
    WHERE student_user_id = v_user_id
    AND (student_id IS NULL OR student_id != v_student_id);
    
    GET DIAGNOSTICS v_enrollments_updated = ROW_COUNT;
    
    v_result := jsonb_build_object(
      'success', true,
      'created', false,
      'student_id', v_student_id,
      'user_id', v_user_id,
      'enrollments_fixed', v_enrollments_updated,
      'message', 'Student record already exists',
      'message_ar', 'سجل الطالب موجود مسبقاً'
    );
  END IF;
  
  RETURN v_result;
  
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM,
    'error_ar', 'حدث خطأ أثناء معالجة البيانات'
  );
END;
$$;


