-- Name: FUNCTION ensure_student_exists(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ensure_student_exists() IS 'ضمان وجود سجل الطالب في جدول students وإصلاح الربط مع enrollments - يُستدعى بعد تسجيل الدخول';


--
-- Name: generate_invitation_code(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_invitation_code() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  code text;
  exists_count int;
BEGIN
  LOOP
    code := upper(substring(md5(random()::text) from 1 for 8));
    
    SELECT COUNT(*) INTO exists_count 
    FROM student_enrollments 
    WHERE invitation_code = code;
    
    EXIT WHEN exists_count = 0;
  END LOOP;
  
  RETURN code;
END;
$$;


ALTER FUNCTION public.generate_invitation_code() OWNER TO postgres;

--
-- Name: FUNCTION generate_invitation_code(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.generate_invitation_code() IS 'Generate unique 8-character invitation code';


--
-- Name: generate_receipt_number(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_receipt_number() RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
  next_number INTEGER;
  receipt_num TEXT;
BEGIN
  -- Get the next number for this month
  SELECT COALESCE(MAX(
    CAST(
      SUBSTRING(receipt_number FROM '[0-9]+$') AS INTEGER
    )
  ), 0) + 1
  INTO next_number
  FROM payments
  WHERE month_year = TO_CHAR(CURRENT_DATE, 'YYYY-MM')
    AND receipt_number IS NOT NULL;
  
  -- Format: RCP-YYYYMM-0001
  receipt_num := 'RCP-' || TO_CHAR(CURRENT_DATE, 'YYYYMM') || '-' || LPAD(next_number::TEXT, 4, '0');
  
  RETURN receipt_num;
END;
$_$;


ALTER FUNCTION public.generate_receipt_number() OWNER TO postgres;

--
-- Name: generate_receipt_number(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_receipt_number(p_center_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE v_count INTEGER; v_receipt TEXT;
BEGIN
  SELECT COUNT(*) + 1 INTO v_count FROM invoice_payments ip JOIN student_invoices si ON si.id = ip.invoice_id WHERE si.center_id = p_center_id;
  v_receipt := 'REC-' || TO_CHAR(CURRENT_DATE, 'YYYYMM') || '-' || LPAD(v_count::text, 4, '0');
  RETURN v_receipt;
END;
$$;


