--
-- Name: generate_session_qr(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_session_qr(p_session_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_key text;
    v_timestamp bigint;
BEGIN
    SELECT qr_code_rotation_key INTO v_key
    FROM public.attendance_sessions
    WHERE id = p_session_id;
    
    -- Simple rotation: timestamp / 15 seconds
    v_timestamp := (EXTRACT(EPOCH FROM now())::bigint / 15);
    
    -- Return: SESSION_ID:HASH
    RETURN p_session_id || ':' || md5(v_key || v_timestamp::text);
END;
$$;


