--
-- Name: generate_student_monthly_invoice(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_student_monthly_invoice(p_student_id uuid, p_center_id uuid, p_month integer, p_year integer) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_invoice_id UUID;
  v_total DECIMAL(10, 2) := 0;
  v_course RECORD;
  v_due_date DATE;
  v_smart_price RECORD;
  v_price DECIMAL(10, 2);
  v_student_record RECORD;
BEGIN
  -- Check if invoice already exists
  SELECT id INTO v_invoice_id
  FROM student_invoices
  WHERE student_id = p_student_id
    AND center_id = p_center_id
    AND month = p_month
    AND year = p_year;
  
  IF v_invoice_id IS NOT NULL THEN
    -- Invoice exists, return it
    RETURN v_invoice_id;
  END IF;
  
  -- Calculate due date (10th of the month)
  v_due_date := make_date(p_year, p_month, 10);
  
  -- Create new invoice
  INSERT INTO student_invoices (
    student_id, center_id, month, year, due_date, status
  ) VALUES (
    p_student_id, p_center_id, p_month, p_year, v_due_date, 'pending'
  ) RETURNING id INTO v_invoice_id;
  
  -- Add invoice items for each enrolled course using smart pricing
  FOR v_course IN 
    SELECT 
      c.id as course_id, 
      c.name as course_name, 
      COALESCE(c.fee, 0) as default_fee,
      g.teacher_id,
      g.grade_level
    FROM student_group_enrollments sge
    JOIN groups g ON sge.group_id = g.id
    JOIN courses c ON g.course_id = c.id
    WHERE sge.student_id = p_student_id
      AND sge.status = 'active'
    -- REMOVED: Any reference to sge.joined_at
  LOOP
    -- Try to get smart price first
    v_price := 0;
    
    -- Call get_smart_price RPC
    SELECT monthly_price INTO v_price
    FROM get_smart_price(
      p_center_id,
      v_course.course_name,
      v_course.teacher_id,
      v_course.grade_level
    );
    
    -- If no smart price, use default course fee
    IF v_price IS NULL OR v_price = 0 THEN
      v_price := v_course.default_fee;
    END IF;
    
    -- Skip if still 0
    IF v_price > 0 THEN
      INSERT INTO invoice_items (invoice_id, course_id, course_name, amount, description)
      VALUES (v_invoice_id, v_course.course_id, v_course.course_name, v_price, 
              'اشتراك شهري - ' || to_char(make_date(p_year, p_month, 1), 'YYYY/MM'));
      
      v_total := v_total + v_price;
    END IF;
  END LOOP;
  
  -- Update total amount
  UPDATE student_invoices
  SET total_amount = v_total
  WHERE id = v_invoice_id;
  
  RETURN v_invoice_id;
END;
$$;


ALTER FUNCTION public.generate_student_monthly_invoice(p_student_id uuid, p_center_id uuid, p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: generate_subscription_invoice(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_subscription_invoice(subscription_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    sub_record RECORD;
    new_invoice_id TEXT;
BEGIN
    -- جلب بيانات الاشتراك
    SELECT * INTO sub_record FROM public.subscriptions WHERE id = subscription_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Subscription not found';
    END IF;
    
    -- إنشاء الفاتورة
    INSERT INTO public.invoices (
        center_id,
        student_id,
        amount,
        total_amount,
        issue_date,
        due_date,
        status,
        invoice_type,
        description
    ) VALUES (
        sub_record.center_id,
        sub_record.student_id,
        sub_record.amount,
        sub_record.amount,
        CURRENT_DATE,
        sub_record.next_billing_date,
        'pending',
        'subscription',
        'Subscription: ' || sub_record.plan_name
    ) RETURNING id INTO new_invoice_id;
    
    RETURN new_invoice_id::UUID;
END;
$$;


ALTER FUNCTION public.generate_subscription_invoice(subscription_id uuid) OWNER TO postgres;

--
-- Name: generate_universal_qr(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_universal_qr() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_key text;
    v_timestamp bigint;
    v_signature text;
BEGIN
    SELECT universal_qr_key INTO v_key FROM public.center_settings LIMIT 1;
    v_timestamp := (EXTRACT(EPOCH FROM now())::bigint / 15);
    v_signature := md5(v_key || v_timestamp::text);
    RETURN 'UNIVERSAL:DEFAULT:' || v_timestamp::text || ':' || v_signature;
END;
$$;


