--
-- Name: get_academic_performance(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_academic_performance(p_student_id uuid DEFAULT NULL::uuid, p_center_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_student_id UUID;
  v_result JSONB;
BEGIN
  -- Use provided student_id or get from auth
  IF p_student_id IS NOT NULL THEN
    v_student_id := p_student_id;
  ELSE
    SELECT id INTO v_student_id FROM students WHERE user_id = auth.uid() LIMIT 1;
    IF v_student_id IS NULL THEN
      v_student_id := auth.uid();
    END IF;
  END IF;

  SELECT jsonb_build_object(
    'total_grades', COALESCE(COUNT(*), 0),
    'average_grade', COALESCE(ROUND(AVG(CASE WHEN max_score > 0 THEN (score / max_score * 100) ELSE 0 END), 1), 0),
    'highest_grade', COALESCE(MAX(CASE WHEN max_score > 0 THEN (score / max_score * 100) ELSE 0 END), 0),
    'lowest_grade', COALESCE(MIN(CASE WHEN max_score > 0 THEN (score / max_score * 100) ELSE 0 END), 0),
    'excellent_count', COUNT(*) FILTER (WHERE max_score > 0 AND (score / max_score * 100) >= 90),
    'very_good_count', COUNT(*) FILTER (WHERE max_score > 0 AND (score / max_score * 100) >= 80 AND (score / max_score * 100) < 90),
    'good_count', COUNT(*) FILTER (WHERE max_score > 0 AND (score / max_score * 100) >= 70 AND (score / max_score * 100) < 80),
    'acceptable_count', COUNT(*) FILTER (WHERE max_score > 0 AND (score / max_score * 100) >= 60 AND (score / max_score * 100) < 70),
    'weak_count', COUNT(*) FILTER (WHERE max_score > 0 AND (score / max_score * 100) < 60)
  )
  INTO v_result
  FROM grades
  WHERE student_id = v_student_id;

  RETURN COALESCE(v_result, jsonb_build_object(
    'total_grades', 0,
    'average_grade', 0,
    'highest_grade', 0,
    'lowest_grade', 0,
    'excellent_count', 0,
    'very_good_count', 0,
    'good_count', 0,
    'acceptable_count', 0,
    'weak_count', 0
  ));
  
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'total_grades', 0,
    'average_grade', 0,
    'highest_grade', 0,
    'lowest_grade', 0,
    'excellent_count', 0,
    'very_good_count', 0,
    'good_count', 0,
    'acceptable_count', 0,
    'weak_count', 0
  );
END;
$$;


ALTER FUNCTION public.get_academic_performance(p_student_id uuid, p_center_id uuid) OWNER TO postgres;

--
-- Name: get_ai_credits(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_ai_credits(p_teacher_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    SELECT jsonb_build_object(
        'free_credits', COALESCE(free_credits, 50),
        'paid_credits', COALESCE(total_credits, 0) - COALESCE(used_credits, 0),
        'total_available', COALESCE(free_credits, 50) + (COALESCE(total_credits, 0) - COALESCE(used_credits, 0))
    ) INTO v_result
    FROM public.ai_credits
    WHERE teacher_id = p_teacher_id;
    
    IF NOT FOUND THEN
        -- إنشاء سجل جديد مع رصيد مجاني
        INSERT INTO public.ai_credits (teacher_id, free_credits)
        VALUES (p_teacher_id, 50);
        
        RETURN jsonb_build_object(
            'free_credits', 50,
            'paid_credits', 0,
            'total_available', 50
        );
    END IF;
    
    RETURN v_result;
END;
$$;


