CREATE FUNCTION public.get_available_teachers(p_center_id uuid) RETURNS TABLE(id uuid, full_name text, avatar_url text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT u.id, u.full_name, u.avatar_url
    FROM public.users u
    JOIN public.schedules s ON s.teacher_id = u.id
    JOIN public.student_enrollments se ON se.center_id = s.center_id
    WHERE s.center_id = p_center_id
    AND se.student_user_id = auth.uid()
    AND se.status = 'accepted'
    ORDER BY u.full_name;
END;
$$;


