--
-- Name: get_center_dashboard(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_center_dashboard(p_center_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE result JSON;
BEGIN
    SELECT json_build_object(
        'center_id', p_center_id,
        'total_students', (SELECT COUNT(DISTINCT user_id) FROM public.student_enrollments WHERE center_id = p_center_id AND status = 'active'),
        'total_teachers', (SELECT COUNT(DISTINCT user_id) FROM public.teacher_enrollments WHERE center_id = p_center_id AND status = 'active'),
        'total_courses', (SELECT COUNT(*) FROM public.courses WHERE center_id = p_center_id),
        'active_courses', (SELECT COUNT(*) FROM public.courses WHERE center_id = p_center_id AND is_active = true),
        'total_classrooms', (SELECT COUNT(*) FROM public.classrooms WHERE center_id = p_center_id),
        -- ✅ FIX: monthly_revenue from invoice_payments
        'monthly_revenue', (SELECT COALESCE(SUM(ip.amount), 0) FROM public.invoice_payments ip
          JOIN public.student_invoices si ON si.id = ip.invoice_id
          WHERE si.center_id = p_center_id AND si.month = EXTRACT(MONTH FROM CURRENT_DATE)::int AND si.year = EXTRACT(YEAR FROM CURRENT_DATE)::int),
        -- ✅ FIX: total_revenue from invoice_payments
        'total_revenue', (SELECT COALESCE(SUM(ip.amount), 0) FROM public.invoice_payments ip
          JOIN public.student_invoices si ON si.id = ip.invoice_id WHERE si.center_id = p_center_id),
        -- ✅ FIX: pending = invoiced - collected
        'pending_payments', (SELECT COALESCE(SUM(total_amount - paid_amount), 0) FROM public.student_invoices
          WHERE center_id = p_center_id AND status NOT IN ('paid', 'cancelled')),
        'pending_invoices', (SELECT COUNT(*) FROM public.student_invoices WHERE center_id = p_center_id AND status NOT IN ('paid', 'cancelled')),
        'overdue_invoices', (SELECT COUNT(*) FROM public.student_invoices WHERE center_id = p_center_id AND status NOT IN ('paid', 'cancelled') AND due_date < CURRENT_DATE),
        'total_schedules', (SELECT COUNT(*) FROM public.schedules WHERE center_id = p_center_id),
        'today_attendance_rate', (SELECT CASE WHEN COUNT(*) > 0 
            THEN ROUND((COUNT(*) FILTER (WHERE status = 'present')::NUMERIC / COUNT(*)) * 100, 2) ELSE 0 END
            FROM public.attendance WHERE center_id = p_center_id AND date = CURRENT_DATE)
    ) INTO result;
    RETURN result;
END;
$$;


