--
-- Name: get_center_financial_dashboard(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_center_financial_dashboard(p_center_id uuid, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_period_start DATE;
    v_period_end DATE;
    v_current_month INTEGER := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::INTEGER);
    v_current_year INTEGER := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER);
    v_total_invoiced DECIMAL(10,2) := 0;
    v_total_collected DECIMAL(10,2) := 0;
    v_total_teacher_dues DECIMAL(10,2) := 0;
    v_total_teacher_paid DECIMAL(10,2) := 0;
    v_total_expenses DECIMAL(10,2) := 0;
    v_center_share DECIMAL(10,2) := 0;
    v_net_profit DECIMAL(10,2) := 0;
    v_teachers_summary JSONB := '[]'::jsonb;
    v_teacher RECORD;
BEGIN
    v_period_start := make_date(v_current_year, v_current_month, 1);
    v_period_end := (v_period_start + INTERVAL '1 month - 1 day')::date;
    
    -- Total invoiced
    SELECT COALESCE(SUM(total_amount), 0) INTO v_total_invoiced
    FROM public.student_invoices
    WHERE center_id = p_center_id AND month = v_current_month AND year = v_current_year;
    
    -- ✅ FIX: Total collected from invoice_payments
    SELECT COALESCE(SUM(ip.amount), 0) INTO v_total_collected
    FROM public.invoice_payments ip
    JOIN public.student_invoices si ON si.id = ip.invoice_id
    WHERE si.center_id = p_center_id AND si.month = v_current_month AND si.year = v_current_year;
    
    -- Teacher dues
    FOR v_teacher IN
        SELECT te.teacher_id, u.full_name as teacher_name, te.salary_type, te.salary_amount
        FROM public.teacher_enrollments te
        JOIN public.teachers t ON t.id = te.teacher_id
        JOIN public.users u ON u.id = t.user_id
        WHERE te.center_id = p_center_id AND te.employment_status = 'active'
    LOOP
        DECLARE
            v_teacher_collected DECIMAL(10,2) := 0;
            v_teacher_due DECIMAL(10,2) := 0;
            v_teacher_paid DECIMAL(10,2) := 0;
        BEGIN
            -- ✅ FIX: Collected from invoice_payments for this teacher's groups
            SELECT COALESCE(SUM(ip.amount), 0) INTO v_teacher_collected
            FROM public.invoice_payments ip
            JOIN public.student_invoices si ON si.id = ip.invoice_id
            JOIN public.student_group_enrollments sge ON sge.student_id = si.student_id
            JOIN public.groups g ON g.id = sge.group_id
            WHERE g.teacher_id = v_teacher.teacher_id
              AND g.center_id = p_center_id
              AND si.month = v_current_month AND si.year = v_current_year;
            
            IF v_teacher.salary_type = 'fixed' THEN
                v_teacher_due := v_teacher.salary_amount;
            ELSIF v_teacher.salary_type = 'percentage' THEN
                v_teacher_due := v_teacher_collected * (v_teacher.salary_amount / 100);
            ELSE -- per_session
                SELECT COUNT(*) * v_teacher.salary_amount * 4 INTO v_teacher_due
                FROM public.schedules s
                JOIN public.groups g ON g.id = s.group_id
                WHERE g.teacher_id = v_teacher.teacher_id AND g.center_id = p_center_id;
            END IF;
            
            SELECT COALESCE(SUM(net_salary), 0) INTO v_teacher_paid
            FROM public.teacher_salaries
            WHERE teacher_id = v_teacher.teacher_id AND center_id = p_center_id
              AND month = v_current_month AND year = v_current_year AND status = 'paid';
            
            v_total_teacher_dues := v_total_teacher_dues + v_teacher_due;
            v_total_teacher_paid := v_total_teacher_paid + v_teacher_paid;
            v_center_share := v_center_share + (v_teacher_collected - v_teacher_due);
            
            v_teachers_summary := v_teachers_summary || jsonb_build_object(
                'teacher_id', v_teacher.teacher_id, 'teacher_name', v_teacher.teacher_name,
                'collected', v_teacher_collected, 'due', v_teacher_due,
                'paid', v_teacher_paid, 'remaining', v_teacher_due - v_teacher_paid
            );
        END;
    END LOOP;
    
    SELECT COALESCE(SUM(amount), 0) INTO v_total_expenses
    FROM public.expenses WHERE center_id = p_center_id
      AND expense_date BETWEEN v_period_start AND v_period_end;
    
    v_net_profit := v_center_share - v_total_expenses;
    
    RETURN json_build_object(
        'center_id', p_center_id, 'month', v_current_month, 'year', v_current_year,
        'period_start', v_period_start, 'period_end', v_period_end,
        'students', json_build_object(
            'total_invoiced', v_total_invoiced, 'total_collected', v_total_collected,
            'collection_rate', CASE WHEN v_total_invoiced > 0 THEN ROUND((v_total_collected / v_total_invoiced * 100)::numeric, 1) ELSE 0 END,
            'outstanding', v_total_invoiced - v_total_collected),
        'teachers', json_build_object(
            'total_dues', v_total_teacher_dues, 'total_paid', v_total_teacher_paid,
            'remaining', v_total_teacher_dues - v_total_teacher_paid, 'details', v_teachers_summary),
        'center', json_build_object(
            'gross_revenue', v_total_collected, 'center_share', v_center_share,
            'expenses', v_total_expenses, 'net_profit', v_net_profit,
            'profit_margin', CASE WHEN v_total_collected > 0 THEN ROUND((v_net_profit / v_total_collected * 100)::numeric, 1) ELSE 0 END)
    );
END;
$$;


ALTER FUNCTION public.get_center_financial_dashboard(p_center_id uuid, p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: get_center_pulse(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_center_pulse(p_center_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_current_month_start DATE := date_trunc('month', CURRENT_DATE);
  v_last_month_start DATE := date_trunc('month', CURRENT_DATE - INTERVAL '1 month');
  v_total_students INT := 0;
  v_total_invoices INT := 0;
  v_days_since_creation INT := 0;
  v_is_new_center BOOLEAN := false;
  v_total_invoiced DECIMAL(10, 2) := 0;
  v_total_collected DECIMAL(10, 2) := 0;
  v_collection_rate DECIMAL(5, 2) := 0;
  v_teacher_expenses DECIMAL(10, 2) := 0;
  v_profit_margin DECIMAL(5, 2) := 0;
  v_last_month_revenue DECIMAL(10, 2) := 0;
  v_current_month_revenue DECIMAL(10, 2) := 0;
  v_growth_rate DECIMAL(5, 2) := 0;
  v_health_score INT := 0;
  v_pulse_status TEXT;
  v_pulse_message TEXT;
  v_has_students BOOLEAN; v_has_teachers BOOLEAN; v_has_courses BOOLEAN; v_has_groups BOOLEAN; v_has_invoices BOOLEAN;
  v_setup_progress INT := 0;
  v_checklist_json JSON;
  v_current_month INT := EXTRACT(MONTH FROM CURRENT_DATE)::INT;
  v_current_year INT := EXTRACT(YEAR FROM CURRENT_DATE)::INT;
BEGIN
  SELECT EXTRACT(DAY FROM (CURRENT_TIMESTAMP - created_at))::INT INTO v_days_since_creation FROM centers WHERE id = p_center_id;
  SELECT COUNT(*)::INT INTO v_total_students FROM student_enrollments WHERE center_id = p_center_id;
  -- ✅ FIX: Check student_invoices instead of payments
  SELECT COUNT(*)::INT INTO v_total_invoices FROM student_invoices WHERE center_id = p_center_id;
  v_is_new_center := (v_days_since_creation < 7) OR (v_total_students = 0) OR (v_total_invoices = 0);

  IF v_is_new_center THEN
    v_has_students := v_total_students > 0;
    SELECT COUNT(*)::INT > 0 INTO v_has_teachers FROM teacher_enrollments WHERE center_id = p_center_id;
    SELECT COUNT(*)::INT > 0 INTO v_has_courses FROM courses WHERE center_id = p_center_id AND deleted_at IS NULL;
    SELECT COUNT(*)::INT > 0 INTO v_has_groups FROM groups WHERE center_id = p_center_id AND deleted_at IS NULL;
    v_has_invoices := v_total_invoices > 0;
    IF v_has_students THEN v_setup_progress := v_setup_progress + 20; END IF;
    IF v_has_teachers THEN v_setup_progress := v_setup_progress + 20; END IF;
    IF v_has_courses THEN v_setup_progress := v_setup_progress + 20; END IF;
    IF v_has_groups THEN v_setup_progress := v_setup_progress + 20; END IF;
    IF v_has_invoices THEN v_setup_progress := v_setup_progress + 20; END IF;
    v_checklist_json := json_build_object('has_students', v_has_students, 'has_teachers', v_has_teachers, 'has_courses', v_has_courses, 'has_groups', v_has_groups, 'has_invoices', v_has_invoices);
    RETURN json_build_object('score', v_setup_progress, 'status', CASE WHEN v_setup_progress >= 80 THEN 'almost_ready' ELSE 'setting_up' END,
      'message', CASE WHEN v_setup_progress = 100 THEN 'أحسنت! السنتر جاهز تماماً للانطلاق 🚀' WHEN v_setup_progress >= 80 THEN 'رائع! خطوة واحدة متبقية لتفعيل الذكاء المالي' ELSE 'أكمل إعداد بيانات السنتر لتفعيل التحليلات الذكية' END,
      'is_new_center', true, 'setup_progress', v_setup_progress, 'checklist', v_checklist_json, 'collection_rate', 0, 'profit_margin', 0, 'growth_rate', 0);
  END IF;

  -- ✅ FIX: All financials from invoice_payments
  SELECT COALESCE(SUM(total_amount), 0) INTO v_total_invoiced FROM student_invoices WHERE center_id = p_center_id AND month = v_current_month AND year = v_current_year;
  SELECT COALESCE(SUM(ip.amount), 0) INTO v_total_collected FROM invoice_payments ip JOIN student_invoices si ON si.id = ip.invoice_id WHERE si.center_id = p_center_id AND si.month = v_current_month AND si.year = v_current_year;
  v_current_month_revenue := v_total_collected;
  IF v_total_invoiced > 0 THEN v_collection_rate := (v_total_collected / v_total_invoiced) * 100; ELSE v_collection_rate := 100; END IF;
  
  v_teacher_expenses := v_current_month_revenue * 0.30;
  IF v_current_month_revenue > 0 THEN v_profit_margin := ((v_current_month_revenue - v_teacher_expenses) / v_current_month_revenue) * 100; ELSE v_profit_margin := 0; END IF;

  -- Last month revenue from invoice_payments
  SELECT COALESCE(SUM(ip.amount), 0) INTO v_last_month_revenue FROM invoice_payments ip JOIN student_invoices si ON si.id = ip.invoice_id
  WHERE si.center_id = p_center_id AND si.month = CASE WHEN v_current_month = 1 THEN 12 ELSE v_current_month - 1 END
    AND si.year = CASE WHEN v_current_month = 1 THEN v_current_year - 1 ELSE v_current_year END;

  IF v_last_month_revenue > 0 THEN v_growth_rate := ((v_current_month_revenue - v_last_month_revenue) / v_last_month_revenue) * 100;
    v_growth_rate := GREATEST(-100, LEAST(100, v_growth_rate));
  ELSE v_growth_rate := CASE WHEN v_current_month_revenue > 0 THEN 100 ELSE 0 END; END IF;

  v_health_score := ((v_collection_rate * 0.4) + (v_profit_margin * 0.3) + (GREATEST(0, LEAST(100, 50 + (v_growth_rate / 2))) * 0.3))::INT;
  v_health_score := GREATEST(0, LEAST(100, v_health_score));

  IF v_health_score >= 80 THEN v_pulse_status := 'excellent'; v_pulse_message := 'السنتر في حالة ممتازة! استمر 🚀';
  ELSIF v_health_score >= 60 THEN v_pulse_status := 'healthy'; v_pulse_message := 'أداء جيد مع فرص للتحسين';
  ELSIF v_health_score >= 40 THEN v_pulse_status := 'attention'; v_pulse_message := 'انتبه! هناك مجالات تحتاج تحسين';
  ELSE v_pulse_status := 'critical'; v_pulse_message := 'تحذير! راجع التحصيل والمصروفات'; END IF;

  RETURN json_build_object('score', v_health_score, 'status', v_pulse_status, 'message', v_pulse_message,
    'is_new_center', false, 'setup_progress', 100, 'checklist', null,
    'collection_rate', ROUND(v_collection_rate, 1), 'profit_margin', ROUND(v_profit_margin, 1), 'growth_rate', ROUND(v_growth_rate, 1));
END;
$$;


ALTER FUNCTION public.get_center_pulse(p_center_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_center_pulse(p_center_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_center_pulse(p_center_id uuid) IS 'Smart center health score with new center detection and onboarding progress';


--
-- Name: get_center_revenue_report(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_center_revenue_report(p_center_id uuid, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_expected_revenue DECIMAL(10,2) := 0;
    v_actual_revenue DECIMAL(10,2) := 0;
    v_total_students INTEGER := 0;
    v_enrollment RECORD;
    v_monthly_price DECIMAL(10,2);
    v_current_month INTEGER := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::INTEGER);
    v_current_year INTEGER := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER);
    v_groups_data JSONB := '[]'::jsonb;
BEGIN
    -- حساب الإيراد المتوقع من كل مجموعة باستخدام course_prices
    FOR v_enrollment IN
        SELECT 
            g.id as group_id,
            g.group_name,
            g.monthly_fee,
            c.name as course_name,
            c.fee as course_fee,
            COUNT(sge.id) as student_count
        FROM public.groups g
        LEFT JOIN public.courses c ON c.id = g.course_id
        LEFT JOIN public.student_group_enrollments sge 
            ON sge.group_id = g.id AND sge.status = 'active'
        WHERE g.center_id = p_center_id AND g.status = 'active'
        GROUP BY g.id, g.group_name, g.monthly_fee, c.name, c.fee
    LOOP
        SELECT cp.monthly_price INTO v_monthly_price
        FROM public.course_prices cp
        WHERE cp.center_id = p_center_id 
          AND cp.subject_name = v_enrollment.course_name
          AND cp.is_active = true
        ORDER BY cp.teacher_id NULLS LAST
        LIMIT 1;
        
        v_monthly_price := COALESCE(v_monthly_price, v_enrollment.monthly_fee, v_enrollment.course_fee, 0);
        
        v_expected_revenue := v_expected_revenue + (v_monthly_price * v_enrollment.student_count);
        v_total_students := v_total_students + v_enrollment.student_count;
        
        v_groups_data := v_groups_data || jsonb_build_object(
            'group_id', v_enrollment.group_id,
            'group_name', v_enrollment.group_name,
            'course_name', v_enrollment.course_name,
            'monthly_price', v_monthly_price,
            'student_count', v_enrollment.student_count,
            'expected_revenue', v_monthly_price * v_enrollment.student_count
        );
    END LOOP;
    
    -- ✅ FIX: حساب الإيراد الفعلي من invoice_payments بدلاً من payments
    SELECT COALESCE(SUM(ip.amount), 0) INTO v_actual_revenue
    FROM public.invoice_payments ip
    JOIN public.student_invoices si ON si.id = ip.invoice_id
    WHERE si.center_id = p_center_id
      AND si.month = v_current_month
      AND si.year = v_current_year;
    
    RETURN json_build_object(
        'month', v_current_month,
        'year', v_current_year,
        'expected_revenue', v_expected_revenue,
        'actual_revenue', v_actual_revenue,
        'collection_rate', CASE WHEN v_expected_revenue > 0 
            THEN ROUND((v_actual_revenue / v_expected_revenue * 100)::numeric, 2) 
            ELSE 0 END,
        'overdue_amount', GREATEST(v_expected_revenue - v_actual_revenue, 0),
        'total_students', v_total_students,
        'groups', v_groups_data
    );
END;
$$;


ALTER FUNCTION public.get_center_revenue_report(p_center_id uuid, p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: get_center_statistics(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_center_statistics(p_center_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE result JSON;
BEGIN
    SELECT json_build_object(
        'total_students', (SELECT COUNT(DISTINCT user_id) FROM student_enrollments WHERE center_id = p_center_id AND status = 'accepted' AND (deleted_at IS NULL OR deleted_at > NOW())),
        'total_teachers', (SELECT COUNT(DISTINCT user_id) FROM teacher_enrollments WHERE center_id = p_center_id AND status = 'active' AND (deleted_at IS NULL OR deleted_at > NOW())),
        'total_courses', (SELECT COUNT(*) FROM courses WHERE center_id = p_center_id AND (deleted_at IS NULL OR deleted_at > NOW())),
        'active_schedules', (SELECT COUNT(*) FROM schedules WHERE center_id = p_center_id AND (deleted_at IS NULL OR deleted_at > NOW())),
        'pending_invoices', (SELECT COUNT(*) FROM student_invoices WHERE center_id = p_center_id AND status IN ('pending', 'partial')),
        -- ✅ FIX: Revenue from invoice_payments
        'total_revenue_this_month', (SELECT COALESCE(SUM(ip.amount), 0) FROM invoice_payments ip
          JOIN student_invoices si ON si.id = ip.invoice_id
          WHERE si.center_id = p_center_id AND si.month = EXTRACT(MONTH FROM CURRENT_DATE)::int AND si.year = EXTRACT(YEAR FROM CURRENT_DATE)::int)
    ) INTO result;
    RETURN result;
END;
$$;


