--
-- Name: get_center_stats(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_center_stats(p_center_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE result JSON;
BEGIN
  SELECT json_build_object(
    'total_students', COALESCE((SELECT COUNT(DISTINCT user_id) FROM student_enrollments WHERE center_id = p_center_id AND status = 'accepted'), 0),
    'total_teachers', COALESCE((SELECT COUNT(DISTINCT user_id) FROM teacher_enrollments WHERE center_id = p_center_id AND status = 'active'), 0),
    'total_courses', COALESCE((SELECT COUNT(*) FROM courses WHERE center_id = p_center_id), 0),
    'total_groups', COALESCE((SELECT COUNT(*) FROM groups WHERE center_id = p_center_id AND is_active = true), 0),
    'total_classrooms', COALESCE((SELECT COUNT(*) FROM classrooms WHERE center_id = p_center_id), 0),
    'active_schedules', COALESCE((SELECT COUNT(*) FROM schedules WHERE center_id = p_center_id AND status = 'active'), 0),
    'monthly_revenue', COALESCE((SELECT SUM(ip.amount) FROM invoice_payments ip JOIN student_invoices si ON si.id = ip.invoice_id
      WHERE si.center_id = p_center_id AND si.month = EXTRACT(MONTH FROM CURRENT_DATE)::int AND si.year = EXTRACT(YEAR FROM CURRENT_DATE)::int), 0),
    'total_revenue', COALESCE((SELECT SUM(ip.amount) FROM invoice_payments ip JOIN student_invoices si ON si.id = ip.invoice_id WHERE si.center_id = p_center_id), 0),
    'pending_payments', COALESCE((SELECT SUM(total_amount - paid_amount) FROM student_invoices WHERE center_id = p_center_id AND status NOT IN ('paid', 'cancelled')), 0)
  ) INTO result;
  RETURN result;
END;
$$;


