--
-- Name: get_community_post_details(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_community_post_details(p_post_id uuid) RETURNS TABLE(id uuid, author_id uuid, author_name text, author_avatar text, author_center_name text, academic_year text, post_type text, title text, content text, subject_name text, topic_tags text[], attachment_url text, attachment_type text, view_count integer, reply_count integer, upvote_count integer, created_at timestamp with time zone, has_user_voted boolean, is_mine boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_post_id uuid := p_post_id;
  v_current_user uuid := auth.uid();
  v_author_id uuid;
  v_view_exists boolean;
BEGIN
  -- Get post author
  SELECT cp.author_id INTO v_author_id 
  FROM community_posts cp 
  WHERE cp.id = v_post_id;
  
  -- Only count view if:
  -- 1. User is not the author
  -- 2. User hasn't viewed before
  IF v_current_user IS NOT NULL AND v_current_user != v_author_id THEN
    -- Check if view already exists
    SELECT EXISTS(
      SELECT 1 FROM community_post_views 
      WHERE post_id = v_post_id AND user_id = v_current_user
    ) INTO v_view_exists;
    
    -- If new view, insert and update count
    IF NOT v_view_exists THEN
      INSERT INTO community_post_views (post_id, user_id)
      VALUES (v_post_id, v_current_user)
      ON CONFLICT (post_id, user_id) DO NOTHING;
      
      -- Update view count
      UPDATE community_posts cp 
      SET view_count = cp.view_count + 1 
      WHERE cp.id = v_post_id;
    END IF;
  END IF;
  
  -- Return post details
  RETURN QUERY
  SELECT 
    p.id,
    p.author_id,
    COALESCE(u.full_name, 'طالب')::text,
    COALESCE(u.avatar_url, '')::text,
    COALESCE(c.name, '')::text,
    p.academic_year,
    p.post_type,
    p.title,
    p.content,
    COALESCE(sub.name, '')::text,
    p.topic_tags,
    p.attachment_url,
    p.attachment_type,
    p.view_count,
    p.reply_count,
    p.upvote_count,
    p.created_at,
    EXISTS(
      SELECT 1 FROM community_votes v 
      WHERE v.target_id = p.id 
      AND v.target_type = 'post' 
      AND v.user_id = v_current_user
    ),
    (p.author_id = v_current_user)
  FROM community_posts p
  JOIN users u ON p.author_id = u.id
  LEFT JOIN centers c ON p.author_center_id = c.id
  LEFT JOIN subjects sub ON p.subject_id = sub.id
  WHERE p.id = v_post_id;
END;
$$;


ALTER FUNCTION public.get_community_post_details(p_post_id uuid) OWNER TO postgres;

--
-- Name: get_community_posts(text, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_community_posts(p_post_type text DEFAULT NULL::text, p_subject_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, author_id uuid, author_name text, author_avatar text, author_center_name text, academic_year text, post_type text, title text, content text, subject_name text, topic_tags text[], attachment_url text, attachment_type text, view_count integer, reply_count integer, upvote_count integer, created_at timestamp with time zone, has_user_voted boolean, is_mine boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_my_year TEXT;
BEGIN
  -- جلب سنة الطالب الحالي
  SELECT s.academic_year INTO v_my_year
  FROM students s
  WHERE s.user_id = auth.uid();
  
  RETURN QUERY
  SELECT 
    p.id,
    p.author_id,
    COALESCE(u.full_name, 'طالب') as author_name,
    COALESCE(u.avatar_url, '') as author_avatar,
    COALESCE(c.name, '') as author_center_name,
    p.academic_year,
    p.post_type,
    p.title,
    p.content,
    COALESCE(sub.name, '') as subject_name,
    p.topic_tags,
    p.attachment_url,
    p.attachment_type,
    p.view_count,
    p.reply_count,
    p.upvote_count,
    p.created_at,
    EXISTS(
      SELECT 1 FROM community_votes v 
      WHERE v.target_id = p.id 
      AND v.target_type = 'post' 
      AND v.user_id = auth.uid()
    ) as has_user_voted,
    (p.author_id = auth.uid()) as is_mine
  FROM community_posts p
  JOIN users u ON p.author_id = u.id
  LEFT JOIN centers c ON p.author_center_id = c.id
  LEFT JOIN subjects sub ON p.subject_id = sub.id
  WHERE p.academic_year = v_my_year
    AND p.is_hidden = false
    AND (p.ai_review_status = 'safe' 
         OR (p.ai_review_status = 'suspicious' AND p.admin_review_status = 'approved')
         OR p.author_id = auth.uid())
    AND (p_post_type IS NULL OR p.post_type = p_post_type)
    AND (p_subject_id IS NULL OR p.subject_id = p_subject_id)
  ORDER BY p.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.get_community_posts(p_post_type text, p_subject_id uuid, p_limit integer, p_offset integer) OWNER TO postgres;

