--

CREATE FUNCTION public.get_community_stats() RETURNS TABLE(total_posts integer, total_students integer, total_centers integer, my_posts_count integer, my_replies_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_my_year TEXT;
BEGIN
  SELECT s.academic_year INTO v_my_year
  FROM students s WHERE s.user_id = auth.uid();
  
  RETURN QUERY
  SELECT 
    (SELECT COUNT(*)::INT FROM community_posts WHERE academic_year = v_my_year AND is_hidden = false),
    (SELECT COUNT(DISTINCT author_id)::INT FROM community_posts WHERE academic_year = v_my_year),
    (SELECT COUNT(DISTINCT author_center_id)::INT FROM community_posts WHERE academic_year = v_my_year),
    (SELECT COUNT(*)::INT FROM community_posts WHERE author_id = auth.uid()),
    (SELECT COUNT(*)::INT FROM community_replies WHERE author_id = auth.uid());
END;
$$;


