--
-- Name: get_dashboard_summary(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_dashboard_summary(p_center_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  result JSON;
  today_dow TEXT;
  today_date DATE;
  current_time_val TIME;
BEGIN
  today_dow := LOWER(TRIM(TO_CHAR(CURRENT_DATE, 'Day')));
  today_date := CURRENT_DATE;
  current_time_val := CURRENT_TIME;
  
  SELECT json_build_object(
    'student_count', (SELECT COUNT(*)::int FROM student_enrollments WHERE center_id = p_center_id AND status = 'accepted'),
    'teacher_count', (SELECT COUNT(*)::int FROM teacher_enrollments WHERE center_id = p_center_id AND employment_status = 'active'),
    'course_count', (SELECT COUNT(*)::int FROM courses WHERE center_id = p_center_id AND deleted_at IS NULL),
    'group_count', (SELECT COUNT(*)::int FROM groups WHERE center_id = p_center_id AND status = 'active' AND deleted_at IS NULL),
    'active_students', (SELECT COUNT(*)::int FROM student_enrollments WHERE center_id = p_center_id AND status = 'active'),
    'today_sessions_count', (SELECT COUNT(*)::int FROM schedules WHERE center_id = p_center_id AND day_of_week = today_dow AND status != 'cancelled' AND status != 'archived'),
    'completed_sessions', (SELECT COUNT(*)::int FROM schedules WHERE center_id = p_center_id AND day_of_week = today_dow AND status = 'completed'),
    -- ✅ FIX: today_revenue from invoice_payments
    'today_revenue', COALESCE((
      SELECT SUM(ip.amount) FROM invoice_payments ip
      JOIN student_invoices si ON si.id = ip.invoice_id
      WHERE si.center_id = p_center_id AND ip.paid_at::date = today_date
    ), 0),
    'today_revenue_change', 0,
    'next_session_time', (
      SELECT start_time FROM schedules WHERE center_id = p_center_id AND day_of_week = today_dow 
      AND status != 'completed' AND status != 'cancelled' AND start_time::time > current_time_val
      ORDER BY start_time ASC LIMIT 1),
    'next_session_name', (
      SELECT COALESCE(g.group_name, c.name) FROM schedules s
      LEFT JOIN groups g ON s.group_id = g.id LEFT JOIN courses c ON s.course_id = c.id
      WHERE s.center_id = p_center_id AND s.day_of_week = today_dow 
      AND s.status != 'completed' AND s.status != 'cancelled' AND s.start_time::time > current_time_val
      ORDER BY s.start_time ASC LIMIT 1),
    -- ✅ FIX: monthly_revenue from invoice_payments
    'monthly_revenue', (
      SELECT COALESCE(json_agg(json_build_object(
        'month', TO_CHAR(month_date, 'Month'), 'month_num', EXTRACT(MONTH FROM month_date), 'revenue', COALESCE(revenue, 0)
      )), '[]'::json)
      FROM (
        SELECT dates.payment_date::date as month_date,
          (SELECT SUM(ip.amount) FROM invoice_payments ip
           JOIN student_invoices si ON si.id = ip.invoice_id
           WHERE si.center_id = p_center_id AND DATE_TRUNC('month', ip.paid_at) = dates.payment_date) as revenue
        FROM (SELECT generate_series(DATE_TRUNC('month', today_date) - INTERVAL '5 months', DATE_TRUNC('month', today_date), '1 month')::date as payment_date) dates
        ORDER BY month_date DESC
      ) sub),
    'weekly_attendance_chart', (
       SELECT COALESCE(json_agg(json_build_object('date', day_date, 'present', COALESCE(present_count, 0), 'absent', COALESCE(absent_count, 0))), '[]'::json)
       FROM (SELECT series_date::date as day_date,
         COUNT(*) FILTER (WHERE status = 'present') as present_count,
         COUNT(*) FILTER (WHERE status = 'absent') as absent_count
       FROM generate_series(today_date - INTERVAL '6 days', today_date - INTERVAL '1 day', '1 day') as series_date
       LEFT JOIN attendance a ON DATE(a.date) = series_date AND a.center_id = p_center_id
       GROUP BY series_date ORDER BY series_date DESC) sub),
    'center_pulse', get_center_pulse(p_center_id),
    'financial_forecast', get_financial_forecast(p_center_id)
  ) INTO result;
  RETURN result;
END;
$$;


ALTER FUNCTION public.get_dashboard_summary(p_center_id uuid) OWNER TO postgres;

--
-- Name: get_financial_forecast(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_financial_forecast(p_center_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_current_month_start DATE := date_trunc('month', CURRENT_DATE);
  v_current_revenue DECIMAL(10, 2) := 0;
  v_last_month_revenue DECIMAL(10, 2) := 0;
  v_projected_revenue DECIMAL(10, 2) := 0;
  v_days_in_month INT;
  v_days_passed INT;
  v_projection_status TEXT;
  v_forecast_message TEXT;
  
  -- Smart metrics
  v_has_data BOOLEAN := false;
  v_avg_daily_revenue DECIMAL(10, 2) := 0;
  v_expected_invoices DECIMAL(10, 2) := 0;
  v_pending_invoices DECIMAL(10, 2) := 0;
  v_growth_percent DECIMAL(5, 2) := 0;
BEGIN
  v_days_in_month := EXTRACT(DAY FROM (date_trunc('month', CURRENT_DATE) + INTERVAL '1 month' - INTERVAL '1 day'));
  v_days_passed := EXTRACT(DAY FROM CURRENT_DATE);

  -- Get Current Collected Revenue this month
  SELECT COALESCE(SUM(amount), 0) INTO v_current_revenue
  FROM invoice_payments p
  JOIN student_invoices i ON p.invoice_id = i.id
  WHERE i.center_id = p_center_id
    AND p.created_at >= v_current_month_start;

  -- Get Last Month Total Revenue
  SELECT COALESCE(SUM(amount), 0) INTO v_last_month_revenue
  FROM invoice_payments p
  JOIN student_invoices i ON p.invoice_id = i.id
  WHERE i.center_id = p_center_id
    AND p.created_at >= (v_current_month_start - INTERVAL '1 month')
    AND p.created_at < v_current_month_start;

  -- Get pending invoices amount (unpaid this month)
  SELECT COALESCE(SUM(total_amount - paid_amount), 0) INTO v_pending_invoices
  FROM student_invoices
  WHERE center_id = p_center_id
    AND status IN ('pending', 'partial', 'overdue')
    AND due_date >= v_current_month_start;

  -- Check if center has any financial data
  v_has_data := (v_current_revenue > 0) OR (v_last_month_revenue > 0) OR (v_pending_invoices > 0);

  IF NOT v_has_data THEN
    -- 🆕 NEW CENTER: No financial data yet
    RETURN json_build_object(
      'has_data', false,
      'current_revenue', 0,
      'projected_revenue', 0,
      'last_month_revenue', 0,
      'pending_invoices', 0,
      'status', 'no_data',
      'message', 'ابدأ بإصدار فواتير للطلاب لتفعيل التنبؤ المالي الذكي',
      'days_passed', v_days_passed,
      'days_total', v_days_in_month,
      'tips', json_build_array(
        'أضف طلاب إلى المجموعات',
        'أصدر فواتير شهرية',
        'سجل المدفوعات فور استلامها'
      )
    );
  END IF;

  -- 📈 CALCULATE PROJECTIONS
  IF v_days_passed > 0 THEN
    v_avg_daily_revenue := v_current_revenue / v_days_passed;
    v_projected_revenue := v_avg_daily_revenue * v_days_in_month;
  ELSE
    v_projected_revenue := 0;
  END IF;

  -- Add expected from pending invoices (assume 70% collection rate)
  v_expected_invoices := v_pending_invoices * 0.7;

  -- Calculate growth compared to last month
  IF v_last_month_revenue > 0 THEN
    v_growth_percent := ((v_projected_revenue - v_last_month_revenue) / v_last_month_revenue) * 100;
  ELSE
    v_growth_percent := CASE WHEN v_projected_revenue > 0 THEN 100 ELSE 0 END;
  END IF;

  -- Determine Status and Message
  IF v_projected_revenue > (v_last_month_revenue * 1.2) THEN 
    v_projection_status := 'surging';
    v_forecast_message := '🚀 نمو استثنائي! الإيرادات متوقع تتجاوز الشهر الماضي بـ ' || ROUND(v_growth_percent)::TEXT || '%';
  ELSIF v_projected_revenue > (v_last_month_revenue * 1.05) THEN 
    v_projection_status := 'growing';
    v_forecast_message := '📈 نمو إيجابي! استمر في تحصيل المستحقات';
  ELSIF v_projected_revenue > (v_last_month_revenue * 0.95) THEN 
    v_projection_status := 'stable';
    v_forecast_message := '⚖️ استقرار جيد. حافظ على معدل التحصيل';
  ELSIF v_projected_revenue > (v_last_month_revenue * 0.8) THEN 
    v_projection_status := 'declining';
    v_forecast_message := '⚠️ انخفاض طفيف. ركز على تحصيل المتأخرات';
  ELSE 
    v_projection_status := 'critical';
    v_forecast_message := '🔴 انخفاض حاد! راجع الفواتير المتأخرة فوراً';
  END IF;

  RETURN json_build_object(
    'has_data', true,
    'current_revenue', v_current_revenue,
    'projected_revenue', ROUND(v_projected_revenue, 2),
    'last_month_revenue', v_last_month_revenue,
    'pending_invoices', v_pending_invoices,
    'expected_from_pending', ROUND(v_expected_invoices, 2),
    'avg_daily_revenue', ROUND(v_avg_daily_revenue, 2),
    'growth_percent', ROUND(v_growth_percent, 1),
    'status', v_projection_status,
    'message', v_forecast_message,
    'days_passed', v_days_passed,
    'days_total', v_days_in_month,
    'tips', CASE 
      WHEN v_projection_status IN ('declining', 'critical') THEN 
        json_build_array(
          'تابع الفواتير المتأخرة',
          'أرسل تذكيرات للأولياء',
          'راجع أسعار الدورات'
        )
      ELSE NULL
    END
  );
END;
$$;


ALTER FUNCTION public.get_financial_forecast(p_center_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_financial_forecast(p_center_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_financial_forecast(p_center_id uuid) IS 'Smart financial projection with guidance and tips';


--
-- Name: get_full_student_profile(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_full_student_profile() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_result JSON;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT json_build_object(
    'id', COALESCE(s.id::TEXT, v_user_id::TEXT),
    'full_name', COALESCE(s.full_name, u.full_name, null),
    'email', COALESCE(s.email, u.email),
    'phone', COALESCE(s.phone, u.phone),
    'avatar_url', COALESCE(s.avatar_url, u.avatar_url),
    'student_code', s.student_code,
    'academic_year', s.academic_year,
    'school_name', s.school_name,
    'address', s.address,
    'birth_date', s.birth_date,
    'parent_phone', s.parent_phone,
    'guardian_name', s.guardian_name,
    'guardian_phone', s.guardian_phone,
    'gender', s.gender,
    'city', s.city,
    'created_at', s.created_at
  ) INTO v_result
  FROM public.users u
  LEFT JOIN public.students s ON s.user_id = u.id
  WHERE u.id = v_user_id
  LIMIT 1;
  
  RETURN v_result;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.get_full_student_profile() OWNER TO postgres;

--
-- Name: get_group_attendance_sheet(uuid, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_group_attendance_sheet(p_group_id uuid, p_date timestamp without time zone) RETURNS TABLE(student_id uuid, student_name text, student_phone text, avatar_url text, attendance_status text, check_in_time timestamp without time zone, notes text, is_enrolled boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        s.id AS student_id,
        s.name AS student_name,
        s.phone AS student_phone,
        s.image_url AS avatar_url,
        a.status AS attendance_status,
        a.check_in_time,
        a.notes,
        true AS is_enrolled
    FROM 
        student_group_enrollment e
    JOIN 
        students s ON e.student_id = s.id
    LEFT JOIN 
        attendance a ON s.id = a.student_id 
        AND a.group_id = p_group_id 
        AND DATE(a.date) = DATE(p_date) -- Match specific date only
    WHERE 
        e.group_id = p_group_id
        AND e.status = 'active' -- Only active students
        AND (e.dropped_at IS NULL OR e.dropped_at > p_date) -- Was active at that time
    ORDER BY 
        s.name ASC;
END;
$$;


ALTER FUNCTION public.get_group_attendance_sheet(p_group_id uuid, p_date timestamp without time zone) OWNER TO postgres;

--
-- Name: get_group_price(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_group_price(p_group_id uuid) RETURNS TABLE(session_price numeric, monthly_price numeric, price_source text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_group RECORD;
    v_override JSONB;
BEGIN
    -- جلب بيانات المجموعة
    SELECT g.*, c.name as course_name, s.name as subject_name
    INTO v_group
    FROM groups g
    LEFT JOIN courses c ON g.course_id = c.id
    LEFT JOIN subjects s ON c.subject_id = s.id
    WHERE g.id = p_group_id;
    
    IF NOT FOUND THEN
        RETURN;
    END IF;
    
    -- التحقق من تجاوز السعر
    v_override := v_group.price_override;
    IF v_override IS NOT NULL 
       AND (v_override->>'session_price') IS NOT NULL
       AND (v_override->>'valid_until' IS NULL OR (v_override->>'valid_until')::DATE >= CURRENT_DATE)
    THEN
        RETURN QUERY
        SELECT 
            (v_override->>'session_price')::DECIMAL(10,2),
            (v_override->>'session_price')::DECIMAL(10,2) * 8,
            'تجاوز خاص: ' || COALESCE(v_override->>'reason', 'بدون سبب');
        RETURN;
    END IF;
    
    -- استخدام نظام التسعير الذكي
    RETURN QUERY
    SELECT 
        sp.session_price,
        sp.monthly_price,
        sp.match_description
    FROM get_smart_price(
        v_group.center_id,
        v_group.subject_name,
        v_group.teacher_id,
        v_group.grade_level
    ) sp
    LIMIT 1;
    
END;
$$;


ALTER FUNCTION public.get_group_price(p_group_id uuid) OWNER TO postgres;

--
-- Name: get_groups_roster(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_groups_roster(p_center_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_result JSON;
BEGIN
  SELECT json_agg(t) INTO v_result
  FROM (
    SELECT 
      g.id,
      g.group_name as name, -- Alias to 'name' if needed, or just group_name. Let's use group_name
      g.group_name, -- Explicitly selecting group_name
      g.center_id,
      g.course_id,
      g.teacher_id,
      g.classroom_id as room_id, -- Mapping classroom_id to room_id
      g.days,
      g.start_time,
      g.end_time,
      g.grade_level,
      g.max_students,
      g.created_at,
      c.name as course_name,
      r.name as room_name,
      0 as student_count
    FROM groups g
    LEFT JOIN courses c ON g.course_id = c.id
    LEFT JOIN classrooms r ON g.classroom_id = r.id
    WHERE g.center_id = p_center_id AND g.deleted_at IS NULL
    ORDER BY g.group_name ASC
  ) t;

  RETURN COALESCE(v_result, '[]'::json);
END;
$$;


ALTER FUNCTION public.get_groups_roster(p_center_id uuid) OWNER TO postgres;

--
-- Name: get_hardest_questions(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_hardest_questions(p_center_id uuid, p_limit integer DEFAULT 5) RETURNS TABLE(question_text text, failure_percentage numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT e.title AS question_text,
           100.0 - COALESCE(avg((er.score / NULLIF(e.max_score, 0)) * 100), 0) AS failure_percentage
    FROM public.exams e
    JOIN public.exam_results er ON e.id = er.exam_id
    WHERE e.center_id = p_center_id
    GROUP BY e.id, e.title
    ORDER BY failure_percentage DESC
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.get_hardest_questions(p_center_id uuid, p_limit integer) OWNER TO postgres;

