-- Name: get_my_devices(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_devices() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_student_id UUID;
  v_devices JSON;
BEGIN
  SELECT id INTO v_student_id FROM public.students WHERE user_id = auth.uid();

  SELECT json_agg(
    json_build_object(
      'id', id,
      'device_id', device_id,
      'device_info', device_info,
      'device_name', device_name,
      'is_active', is_active,
      'first_login_at', first_login_at,
      'last_login_at', last_login_at
    ) ORDER BY last_login_at DESC
  ) INTO v_devices
  FROM public.student_devices
  WHERE student_id = v_student_id AND is_active = true;

  RETURN COALESCE(v_devices, '[]'::json);
END;
$$;


