--
-- Name: get_my_groups(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_groups(p_center_id uuid) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_group_ids UUID[];
    v_is_full_access BOOLEAN;
BEGIN
    SELECT ur.group_ids, (ur.group_ids IS NULL)
    INTO v_group_ids, v_is_full_access
    FROM public.user_roles ur
    WHERE ur.user_id = auth.uid()
      AND ur.center_id = p_center_id
      AND ur.is_active = TRUE;
    
    -- NULL means full access - return all groups
    IF v_is_full_access THEN
        SELECT ARRAY_AGG(id) INTO v_group_ids
        FROM public.groups
        WHERE center_id = p_center_id AND deleted_at IS NULL;
    END IF;
    
    RETURN COALESCE(v_group_ids, ARRAY[]::UUID[]);
END;
$$;


ALTER FUNCTION public.get_my_groups(p_center_id uuid) OWNER TO postgres;

--
-- Name: get_my_notifications(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_notifications(p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, type text, priority text, title text, body text, data jsonb, is_read boolean, created_at timestamp with time zone, time_ago text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_center_id UUID;
BEGIN
  -- جلب center_id للمستخدم الحالي
  SELECT cu.center_id INTO v_center_id
  FROM center_users cu
  WHERE cu.user_id = auth.uid()
  LIMIT 1;
  
  RETURN QUERY
  SELECT 
    n.id,
    n.type,
    n.priority,
    n.title,
    n.body,
    n.data,
    n.is_read,
    n.created_at,
    CASE
      WHEN n.created_at > NOW() - INTERVAL '1 minute' THEN 'الآن'
      WHEN n.created_at > NOW() - INTERVAL '1 hour' THEN 
        (EXTRACT(MINUTE FROM NOW() - n.created_at)::int)::text || ' دقيقة'
      WHEN n.created_at > NOW() - INTERVAL '1 day' THEN 
        (EXTRACT(HOUR FROM NOW() - n.created_at)::int)::text || ' ساعة'
      WHEN n.created_at > NOW() - INTERVAL '7 days' THEN 
        (EXTRACT(DAY FROM NOW() - n.created_at)::int)::text || ' يوم'
      ELSE to_char(n.created_at, 'DD/MM/YYYY')
    END as time_ago
  FROM notifications n
  WHERE n.center_id = v_center_id
  ORDER BY n.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.get_my_notifications(p_limit integer) OWNER TO postgres;

--
-- Name: get_my_permissions(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_permissions(p_center_id uuid) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_permissions TEXT[];
    v_role TEXT;
BEGIN
    v_role := get_my_role(p_center_id);
    
    -- Owner has all permissions
    IF v_role = 'owner' THEN
        SELECT ARRAY_AGG(code) INTO v_permissions FROM public.permissions;
        RETURN v_permissions;
    END IF;
    
    -- Get role-based permissions
    SELECT ARRAY_AGG(rp.permission_code) INTO v_permissions
    FROM public.user_roles ur
    JOIN public.role_permissions rp ON rp.role_id = ur.role_id
    WHERE ur.user_id = auth.uid()
      AND ur.center_id = p_center_id
      AND ur.is_active = TRUE;
    
    RETURN COALESCE(v_permissions, ARRAY[]::TEXT[]);
END;
$$;


ALTER FUNCTION public.get_my_permissions(p_center_id uuid) OWNER TO postgres;

--
-- Name: get_my_role(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_role(p_center_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_role_code TEXT;
BEGIN
    -- Check if user is center admin first
    IF EXISTS (SELECT 1 FROM public.centers WHERE id = p_center_id AND admin_user_id = auth.uid()) THEN
        RETURN 'owner';
    END IF;
    
    -- Then check user_roles
    SELECT ar.code INTO v_role_code
    FROM public.user_roles ur
    JOIN public.app_roles ar ON ur.role_id = ar.id
    WHERE ur.user_id = auth.uid()
      AND ur.center_id = p_center_id
      AND ur.is_active = TRUE;
    
    RETURN COALESCE(v_role_code, 'guest');
END;
$$;


ALTER FUNCTION public.get_my_role(p_center_id uuid) OWNER TO postgres;

--
-- Name: get_or_create_conversation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_or_create_conversation(p_teacher_id uuid, p_center_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_conversation_id UUID;
    v_student_id UUID;
BEGIN
    v_student_id := auth.uid();

    -- Check if conversation exists
    SELECT id INTO v_conversation_id
    FROM public.conversations
    WHERE student_id = v_student_id
    AND teacher_id = p_teacher_id
    AND center_id = p_center_id;

    -- If not, create it
    IF v_conversation_id IS NULL THEN
        INSERT INTO public.conversations (student_id, teacher_id, center_id)
        VALUES (v_student_id, p_teacher_id, p_center_id)
        RETURNING id INTO v_conversation_id;
    END IF;

    RETURN v_conversation_id;
END;
$$;


ALTER FUNCTION public.get_or_create_conversation(p_teacher_id uuid, p_center_id uuid) OWNER TO postgres;

--
-- Name: get_or_create_student_invoice(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_or_create_student_invoice(p_student_id uuid, p_center_id uuid, p_month integer, p_year integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_invoice_id UUID;
    v_student_name TEXT;
    v_total_amount DECIMAL(10,2) := 0;
    v_paid_amount DECIMAL(10,2) := 0;
    v_enrollment RECORD;
    v_item_amount DECIMAL(10,2);
    v_monthly_price DECIMAL(10,2);
    v_items_arr JSONB := '[]'::jsonb;
    v_existing_invoice RECORD;
    v_new_status TEXT;
BEGIN
    -- 1. Check if invoice exists
    SELECT * INTO v_existing_invoice
    FROM student_invoices
    WHERE student_id = p_student_id
      AND center_id = p_center_id
      AND month = p_month
      AND year = p_year;

    -- Return existing if found (sync paid amount from invoice_payments)
    IF v_existing_invoice.id IS NOT NULL THEN
        -- FIX: Read from invoice_payments (single source of truth)
        SELECT COALESCE(SUM(ip.amount), 0) INTO v_paid_amount
        FROM public.invoice_payments ip
        WHERE ip.invoice_id = v_existing_invoice.id;

        -- Sync paid_amount and status if changed
        IF v_paid_amount != COALESCE(v_existing_invoice.paid_amount, 0) THEN
            IF v_paid_amount >= v_existing_invoice.total_amount - 0.5 THEN
                v_new_status := 'paid';
            ELSIF v_paid_amount > 0 THEN
                v_new_status := 'partial';
            ELSE
                v_new_status := 'pending';
            END IF;

            UPDATE student_invoices 
            SET paid_amount = v_paid_amount, 
                status = v_new_status,
                updated_at = NOW()
            WHERE id = v_existing_invoice.id;
            
            v_existing_invoice.paid_amount := v_paid_amount;
            v_existing_invoice.status := v_new_status;
        END IF;

        SELECT full_name INTO v_student_name FROM public.students WHERE id = p_student_id;

        RETURN json_build_object(
            'invoice_id', v_existing_invoice.id,
            'student_id', p_student_id,
            'student_name', v_student_name,
            'center_id', p_center_id,
            'month', p_month,
            'year', p_year,
            'total_amount', v_existing_invoice.total_amount,
            'paid_amount', v_paid_amount,
            'remaining', v_existing_invoice.total_amount - v_paid_amount,
            'status', v_existing_invoice.status,
            'items', '[]'::jsonb
        );
    END IF;

    -- 3. If NOT exists, Calculate & Insert
    SELECT full_name INTO v_student_name FROM public.students WHERE id = p_student_id;

    FOR v_enrollment IN
        SELECT
            sge.group_id,
            g.group_name,
            c.name as course_name,
            g.monthly_fee
        FROM public.student_group_enrollments sge
        JOIN public.groups g ON g.id = sge.group_id
        LEFT JOIN public.courses c ON c.id = g.course_id
        WHERE sge.student_id = p_student_id
          AND sge.status = 'active'
          AND g.center_id = p_center_id
    LOOP
        v_monthly_price := 0;

        SELECT monthly_price INTO v_monthly_price
        FROM public.course_prices
        WHERE center_id = p_center_id
          AND subject_name = v_enrollment.course_name
          AND is_active = true
        LIMIT 1;

        v_monthly_price := COALESCE(v_monthly_price, v_enrollment.monthly_fee, 0);
        v_item_amount := v_monthly_price;
        v_total_amount := v_total_amount + v_item_amount;

        v_items_arr := v_items_arr || jsonb_build_object(
            'group_name', v_enrollment.group_name,
            'course_name', v_enrollment.course_name,
            'amount', v_item_amount
        );
    END LOOP;

    -- Insert new invoice
    INSERT INTO student_invoices (
        center_id, student_id, month, year, total_amount, paid_amount, status, created_at, updated_at
    ) VALUES (
        p_center_id, p_student_id, p_month, p_year, v_total_amount, 0, 'pending', NOW(), NOW()
    ) RETURNING id INTO v_invoice_id;

    RETURN json_build_object(
        'invoice_id', v_invoice_id,
        'student_id', p_student_id,
        'student_name', v_student_name,
        'center_id', p_center_id,
        'month', p_month,
        'year', p_year,
        'total_amount', v_total_amount,
        'paid_amount', 0,
        'remaining', v_total_amount,
        'status', 'pending',
        'items', v_items_arr
    );
END;
$$;


ALTER FUNCTION public.get_or_create_student_invoice(p_student_id uuid, p_center_id uuid, p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: get_parent_investment_stats(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_parent_investment_stats(p_student_id uuid, p_center_id uuid, p_month timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result jsonb;
    v_hours_attended numeric := 0;
    v_exams_taken int := 0;
    v_materials_accessed int := 0;
    v_start_date timestamp with time zone := date_trunc('month', p_month);
    v_end_date timestamp with time zone := v_start_date + interval '1 month';
BEGIN
    -- Simplified hours calculation (assuming 1 attendance = 2 hours avg if duration not directly easily sumable)
    SELECT COUNT(*) * 2 INTO v_hours_attended
    FROM public.attendance a
    WHERE a.student_id = p_student_id
      AND a.center_id = p_center_id
      AND a.created_at >= v_start_date
      AND a.created_at < v_end_date
      AND a.status IN ('present', 'late');

    -- Exams taken
    SELECT COUNT(*) INTO v_exams_taken
    FROM public.exam_results er
    JOIN public.exams e ON er.exam_id = e.id
    WHERE er.student_id = p_student_id
      AND e.center_id = p_center_id
      AND er.submitted_at >= v_start_date
      AND er.submitted_at < v_end_date;

    -- Materials accessed
    SELECT COUNT(*) INTO v_materials_accessed
    FROM public.content_access_log cal
    JOIN public.content_library cl ON cal.content_id = cl.id
    WHERE cal.user_id = p_student_id
      AND cl.center_id = p_center_id
      AND cal.accessed_at >= v_start_date
      AND cal.accessed_at < v_end_date;

    v_result := jsonb_build_object(
        'hours_attended', v_hours_attended,
        'exams_taken', v_exams_taken,
        'materials_accessed', v_materials_accessed
    );
    
    RETURN v_result;
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('hours_attended', 0, 'exams_taken', 0, 'materials_accessed', 0);
END;
$$;


ALTER FUNCTION public.get_parent_investment_stats(p_student_id uuid, p_center_id uuid, p_month timestamp with time zone) OWNER TO postgres;

--
-- Name: get_payment_status(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_payment_status(p_student_id uuid, p_center_id uuid, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE v_cm INTEGER := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::INTEGER); v_cy INTEGER := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER); v_inv RECORD;
BEGIN
  SELECT * INTO v_inv FROM student_invoices WHERE student_id = p_student_id AND center_id = p_center_id AND month = v_cm AND year = v_cy;
  IF v_inv IS NULL THEN RETURN json_build_object('status', 'no_invoice', 'total', 0, 'paid', 0, 'remaining', 0); END IF;
  RETURN json_build_object('invoice_id', v_inv.id, 'status', v_inv.status, 'total', v_inv.total_amount, 'paid', v_inv.paid_amount, 'remaining', v_inv.total_amount - v_inv.paid_amount);
END;
$$;


ALTER FUNCTION public.get_payment_status(p_student_id uuid, p_center_id uuid, p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: get_payments_roster(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_payments_roster(p_center_id uuid, p_page integer DEFAULT 1, p_limit integer DEFAULT 20) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_offset INT := (p_page - 1) * p_limit;
  v_result JSON;
BEGIN
  SELECT json_agg(t) INTO v_result
  FROM (
    SELECT 
      ip.id,
      ip.amount,
      ip.paid_at as paid_date,
      ip.payment_method,
      ip.reference_number as notes, -- Using reference as notes or combine
      'paid' as status, -- invoice_payments are always successful transactions
      si.student_id,
      COALESCE(u.full_name, s.full_name, 'طالب غير معروف') as student_name,
      si.month,
      si.year
    FROM invoice_payments ip
    JOIN student_invoices si ON ip.invoice_id = si.id
    LEFT JOIN students s ON si.student_id = s.id
    LEFT JOIN users u ON s.user_id = u.id
    WHERE si.center_id = p_center_id
    ORDER BY ip.paid_at DESC
    LIMIT p_limit OFFSET v_offset
  ) t;

  RETURN COALESCE(v_result, '[]'::json);
END;
$$;


ALTER FUNCTION public.get_payments_roster(p_center_id uuid, p_page integer, p_limit integer) OWNER TO postgres;

--
-- Name: get_post_replies(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_post_replies(p_post_id uuid) RETURNS TABLE(id uuid, author_id uuid, author_name text, author_avatar text, content text, upvote_count integer, is_accepted_answer boolean, created_at timestamp with time zone, has_user_voted boolean, is_mine boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    r.id,
    r.author_id,
    COALESCE(u.full_name, 'طالب') as author_name,
    COALESCE(u.avatar_url, '') as author_avatar,
    r.content,
    r.upvote_count,
    r.is_accepted_answer,
    r.created_at,
    EXISTS(
      SELECT 1 FROM community_votes v 
      WHERE v.target_id = r.id 
      AND v.target_type = 'reply' 
      AND v.user_id = auth.uid()
    ) as has_user_voted,
    (r.author_id = auth.uid()) as is_mine
  FROM community_replies r
  JOIN users u ON r.author_id = u.id
  WHERE r.post_id = p_post_id
    AND r.is_hidden = false
    AND r.ai_review_status != 'rejected'
  ORDER BY r.is_accepted_answer DESC, r.upvote_count DESC, r.created_at ASC;
END;
$$;


ALTER FUNCTION public.get_post_replies(p_post_id uuid) OWNER TO postgres;

--
-- Name: get_session_attendance_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_session_attendance_status(p_session_id uuid) RETURNS TABLE(total_students bigint, present_count bigint, absent_count bigint, attendance_rate numeric, present_students jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_session RECORD;
BEGIN
  SELECT * INTO v_session
  FROM attendance_sessions WHERE id = p_session_id;
  
  IF v_session IS NULL THEN
    RETURN;
  END IF;
  
  RETURN QUERY
  WITH group_students_cte AS (
    SELECT sge.student_id
    FROM student_group_enrollments sge
    WHERE sge.group_id = v_session.group_id
  ),
  attendance_cte AS (
    SELECT a.student_id
    FROM attendance a
    WHERE a.group_id = v_session.group_id
      AND a.date = v_session.session_date
      AND a.status = 'present'
  ),
  present_list AS (
    SELECT 
      s.id,
      s.full_name,
      a.check_in_time
    FROM students s
    JOIN attendance_cte ac ON s.id = ac.student_id
    JOIN attendance a ON a.student_id = s.id 
      AND a.group_id = v_session.group_id 
      AND a.date = v_session.session_date
  )
  SELECT 
    (SELECT COUNT(*) FROM group_students_cte) as total_students,
    (SELECT COUNT(*) FROM attendance_cte) as present_count,
    (SELECT COUNT(*) FROM group_students_cte) - (SELECT COUNT(*) FROM attendance_cte) as absent_count,
    CASE 
      WHEN (SELECT COUNT(*) FROM group_students_cte) > 0 
      THEN ROUND((SELECT COUNT(*) FROM attendance_cte)::DECIMAL / (SELECT COUNT(*) FROM group_students_cte) * 100, 1)
      ELSE 0
    END as attendance_rate,
    (SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', pl.id,
      'name', pl.full_name,
      'check_in_time', pl.check_in_time
    )), '[]'::jsonb) FROM present_list pl) as present_students;
END;
$$;


ALTER FUNCTION public.get_session_attendance_status(p_session_id uuid) OWNER TO postgres;

--
-- Name: get_smart_price(uuid, character varying, uuid, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_smart_price(p_center_id uuid, p_subject_name character varying, p_teacher_id uuid DEFAULT NULL::uuid, p_grade_level character varying DEFAULT NULL::character varying) RETURNS TABLE(price_id uuid, session_price numeric, monthly_price numeric, match_level integer, match_description text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- المستوى 1: البحث الأدق (المادة + المدرس + المرحلة)
    IF p_teacher_id IS NOT NULL AND p_grade_level IS NOT NULL THEN
        RETURN QUERY
        SELECT 
            cp.id,
            cp.session_price,
            COALESCE(cp.monthly_price, cp.session_price * cp.sessions_per_month),
            1,
            'سعر محدد: ' || p_subject_name || ' - ' || p_grade_level
        FROM course_prices cp
        WHERE cp.center_id = p_center_id
            AND LOWER(TRIM(cp.subject_name)) = LOWER(TRIM(p_subject_name))
            AND cp.teacher_id = p_teacher_id
            AND cp.grade_level = p_grade_level
            AND cp.is_active = true
        LIMIT 1;
        
        IF FOUND THEN RETURN; END IF;
    END IF;
    
    -- المستوى 2أ: المادة + المدرس (بدون مرحلة)
    IF p_teacher_id IS NOT NULL THEN
        RETURN QUERY
        SELECT 
            cp.id,
            cp.session_price,
            COALESCE(cp.monthly_price, cp.session_price * cp.sessions_per_month),
            2,
            'سعر المدرس العام: ' || p_subject_name
        FROM course_prices cp
        WHERE cp.center_id = p_center_id
            AND LOWER(TRIM(cp.subject_name)) = LOWER(TRIM(p_subject_name))
            AND cp.teacher_id = p_teacher_id
            AND cp.is_active = true
        LIMIT 1;
        
        IF FOUND THEN RETURN; END IF;
    END IF;
    
    -- المستوى 2ب: المادة + المرحلة (بدون مدرس)
    IF p_grade_level IS NOT NULL THEN
        RETURN QUERY
        SELECT 
            cp.id,
            cp.session_price,
            COALESCE(cp.monthly_price, cp.session_price * cp.sessions_per_month),
            2,
            'سعر المرحلة: ' || p_subject_name || ' - ' || p_grade_level
        FROM course_prices cp
        WHERE cp.center_id = p_center_id
            AND LOWER(TRIM(cp.subject_name)) = LOWER(TRIM(p_subject_name))
            AND cp.teacher_id IS NULL
            AND cp.grade_level = p_grade_level
            AND cp.is_active = true
        LIMIT 1;
        
        IF FOUND THEN RETURN; END IF;
    END IF;
    
    -- المستوى 3: المادة فقط (السعر الافتراضي للمادة - teacher_id IS NULL و grade_level IS NULL)
    RETURN QUERY
    SELECT 
        cp.id,
        cp.session_price,
        COALESCE(cp.monthly_price, cp.session_price * cp.sessions_per_month),
        3,
        'السعر الافتراضي: ' || p_subject_name
    FROM course_prices cp
    WHERE cp.center_id = p_center_id
        AND LOWER(TRIM(cp.subject_name)) = LOWER(TRIM(p_subject_name))
        AND cp.teacher_id IS NULL
        AND (cp.grade_level IS NULL OR cp.grade_level = '')
        AND cp.is_active = true
    LIMIT 1;
    
    IF FOUND THEN RETURN; END IF;
    
    -- ═══════════════════════════════════════════════════════════════════════════
    -- 🆕 المستوى 3.5: أي سعر للمادة (بغض النظر عن المدرس/المرحلة)
    -- هذا يحل مشكلة: السعر محفوظ بمدرس/مرحلة لكن البحث يمر بـ null
    -- ═══════════════════════════════════════════════════════════════════════════
    RETURN QUERY
    SELECT 
        cp.id,
        cp.session_price,
        COALESCE(cp.monthly_price, cp.session_price * cp.sessions_per_month),
        3,
        'سعر المادة (عام): ' || p_subject_name
    FROM course_prices cp
    WHERE cp.center_id = p_center_id
        AND LOWER(TRIM(cp.subject_name)) = LOWER(TRIM(p_subject_name))
        AND cp.is_active = true
    ORDER BY 
        -- الأولوية: الأسعار العامة (بدون مدرس/مرحلة) أولاً
        CASE WHEN cp.teacher_id IS NULL AND (cp.grade_level IS NULL OR cp.grade_level = '') THEN 0 ELSE 1 END,
        cp.created_at DESC
    LIMIT 1;
    
    IF FOUND THEN RETURN; END IF;
    
    -- المستوى 4: السعر الافتراضي للسنتر (من billing_config)
    RETURN QUERY
    SELECT 
        NULL::UUID,
        COALESCE((c.billing_config->>'default_session_price')::DECIMAL(10,2), 50.00),
        COALESCE((c.billing_config->>'default_session_price')::DECIMAL(10,2), 50.00) * 8,
        4,
        'السعر الافتراضي للسنتر'
    FROM centers c
    WHERE c.id = p_center_id
    LIMIT 1;
    
END;
$$;


ALTER FUNCTION public.get_smart_price(p_center_id uuid, p_subject_name character varying, p_teacher_id uuid, p_grade_level character varying) OWNER TO postgres;

--
-- Name: get_squad_leaderboard(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_squad_leaderboard(limit_count integer DEFAULT 10) RETURNS TABLE(squad_id uuid, name text, motto text, avatar_emoji text, total_xp integer, rank bigint)
    LANGUAGE sql
    AS $$
    SELECT 
        id, name, motto, avatar_emoji, total_xp,
        RANK() OVER (ORDER BY total_xp DESC) as rank
    FROM public.squads
    ORDER BY total_xp DESC
    LIMIT limit_count;
$$;


ALTER FUNCTION public.get_squad_leaderboard(limit_count integer) OWNER TO postgres;

--
-- Name: get_student_account_statement(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_account_statement(p_student_id uuid, p_center_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSON;
    v_student_name TEXT;
    v_total_due DECIMAL(10,2) := 0;
    v_total_paid DECIMAL(10,2) := 0;
BEGIN
    SELECT full_name INTO v_student_name FROM public.students WHERE id = p_student_id;
    
    -- Total due from active enrollments
    SELECT COALESCE(SUM(COALESCE(g.monthly_fee, c.fee, 0)), 0) INTO v_total_due
    FROM public.student_group_enrollments sge 
    JOIN public.groups g ON g.id = sge.group_id
    LEFT JOIN public.courses c ON c.id = g.course_id
    WHERE sge.student_id = p_student_id AND sge.status = 'active' AND g.center_id = p_center_id;
    
    -- ✅ FIX: Total paid from invoice_payments
    SELECT COALESCE(SUM(ip.amount), 0) INTO v_total_paid
    FROM public.invoice_payments ip
    JOIN public.student_invoices si ON si.id = ip.invoice_id
    WHERE si.student_id = p_student_id AND si.center_id = p_center_id;
    
    v_result := json_build_object(
        'student_id', p_student_id, 'student_name', v_student_name,
        'total_due', v_total_due, 'total_paid', v_total_paid, 'balance', v_total_due - v_total_paid,
        'transactions', (SELECT COALESCE(json_agg(json_build_object(
            'id', ip.id, 
            'date', ip.paid_at, 
            'amount', ip.amount, 
            'paid_amount', ip.amount,
            'type', 'payment', 
            'status', 'paid', 
            'notes', ip.notes,
            'payment_method', ip.payment_method,
            'month', si.month,
            'year', si.year
        ) ORDER BY ip.paid_at DESC), '[]'::json) 
        FROM public.invoice_payments ip
        JOIN public.student_invoices si ON si.id = ip.invoice_id
        WHERE si.student_id = p_student_id AND si.center_id = p_center_id)
    );
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_student_account_statement(p_student_id uuid, p_center_id uuid) OWNER TO postgres;

--
-- Name: get_student_assignments(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_assignments(p_center_id uuid DEFAULT NULL::uuid, p_subject_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text) RETURNS TABLE(assignment_id uuid, title text, description text, course_id uuid, course_name text, due_date timestamp with time zone, max_score numeric, submission_id uuid, submitted_at timestamp with time zone, score numeric, feedback text, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_student_id uuid;
BEGIN
  SELECT st.id INTO v_student_id FROM students st WHERE st.user_id = v_user_id LIMIT 1;
  IF v_student_id IS NULL THEN
    SELECT se.student_id INTO v_student_id FROM student_enrollments se WHERE se.student_user_id = v_user_id LIMIT 1;
  END IF;
  v_student_id := COALESCE(v_student_id, v_user_id);

  RETURN QUERY
  SELECT 
    a.id as assignment_id,
    COALESCE(a.title, 'واجب')::TEXT as title,
    a.description::TEXT,
    c.id as course_id,
    COALESCE(c.name, 'غير محدد')::TEXT as course_name,
    a.due_date,
    COALESCE(a.max_score, 100)::NUMERIC as max_score,
    sub.id as submission_id,
    sub.submitted_at,
    sub.score,
    sub.feedback::TEXT,
    CASE 
      WHEN sub.score IS NOT NULL THEN 'graded'
      WHEN sub.id IS NOT NULL THEN 'submitted'
      ELSE 'pending'
    END::TEXT as status
  FROM assignments a
  JOIN courses c ON a.course_id = c.id
  JOIN groups g ON g.course_id = c.id
  JOIN student_group_enrollments sge ON sge.group_id = g.id
  LEFT JOIN assignment_submissions sub ON sub.assignment_id = a.id 
    AND (sub.student_user_id = v_user_id)
  WHERE (sge.student_id = v_student_id OR sge.student_id = v_user_id)
  AND sge.status = 'active'
  AND (p_center_id IS NULL OR c.center_id = p_center_id)
  AND (p_subject_id IS NULL OR c.id = p_subject_id)
  AND (p_status IS NULL OR 
    (p_status = 'pending' AND sub.id IS NULL) OR
    (p_status = 'submitted' AND sub.id IS NOT NULL AND sub.score IS NULL) OR
    (p_status = 'graded' AND sub.score IS NOT NULL))
  GROUP BY a.id, c.id, c.name, sub.id, sub.submitted_at, sub.score, sub.feedback, a.due_date, a.max_score, a.title, a.description
  ORDER BY a.due_date DESC;
END;
$$;


ALTER FUNCTION public.get_student_assignments(p_center_id uuid, p_subject_id uuid, p_status text) OWNER TO postgres;

--
-- Name: get_student_attendance(uuid, integer, date, date, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_attendance(p_center_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_student_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(attendance_id uuid, group_id uuid, group_name text, course_name text, attendance_date date, status text, notes text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_student_id UUID;
  v_user_id UUID;
BEGIN
  -- Use provided student_user_id if given, otherwise use auth.uid()
  v_user_id := COALESCE(p_student_user_id, auth.uid());
  
  -- Get student ID from students table
  SELECT id INTO v_student_id FROM students WHERE user_id = v_user_id LIMIT 1;
  
  -- If no student record found, return empty
  IF v_student_id IS NULL THEN
    RAISE NOTICE 'No student record found for user_id: %', v_user_id;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT 
    a.id,
    g.id,
    COALESCE(g.group_name, 'مجموعة')::TEXT,
    COALESCE(c.name, 'غير محدد')::TEXT,
    a.attendance_date,
    COALESCE(a.status, 'absent')::TEXT,
    COALESCE(a.notes, '')::TEXT
  FROM attendance a
  JOIN groups g ON a.group_id = g.id
  JOIN courses c ON g.course_id = c.id
  WHERE a.student_id = v_student_id
  AND (p_center_id IS NULL OR g.center_id = p_center_id)
  AND (p_start_date IS NULL OR a.attendance_date >= p_start_date)
  AND (p_end_date IS NULL OR a.attendance_date <= p_end_date)
  ORDER BY a.attendance_date DESC
  LIMIT p_limit;
  
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'Error in get_student_attendance: %', SQLERRM;
  RETURN;
END;
$$;


ALTER FUNCTION public.get_student_attendance(p_center_id uuid, p_limit integer, p_start_date date, p_end_date date, p_student_user_id uuid) OWNER TO postgres;

--
-- Name: get_student_balance_summary(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_balance_summary(p_student_id uuid, p_center_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_total_due DECIMAL(10,2) := 0;
    v_total_paid DECIMAL(10,2) := 0;
    v_billing_type TEXT := 'monthly';
    v_enrollment RECORD;
    v_monthly_price DECIMAL(10,2);
    v_session_price DECIMAL(10,2);
    v_sessions_count INTEGER;
    v_current_month INTEGER := EXTRACT(MONTH FROM CURRENT_DATE);
    v_current_year INTEGER := EXTRACT(YEAR FROM CURRENT_DATE);
    v_period_start DATE;
    v_period_end DATE;
BEGIN
    v_period_start := make_date(v_current_year, v_current_month, 1);
    v_period_end := (v_period_start + INTERVAL '1 month - 1 day')::date;
    
    v_billing_type := 'monthly';
    
    FOR v_enrollment IN
        SELECT 
            sge.enrollment_date,
            sge.group_id,
            g.monthly_fee,
            c.name as course_name,
            c.fee as course_fee
        FROM public.student_group_enrollments sge
        JOIN public.groups g ON g.id = sge.group_id
        LEFT JOIN public.courses c ON c.id = g.course_id
        WHERE sge.student_id = p_student_id
          AND sge.status = 'active'
          AND g.center_id = p_center_id
    LOOP
        SELECT cp.monthly_price, cp.session_price 
        INTO v_monthly_price, v_session_price
        FROM public.course_prices cp
        WHERE cp.center_id = p_center_id 
          AND cp.subject_name = v_enrollment.course_name
          AND cp.is_active = true
        ORDER BY cp.teacher_id NULLS LAST
        LIMIT 1;
        
        v_monthly_price := COALESCE(v_monthly_price, v_enrollment.monthly_fee, v_enrollment.course_fee, 0);
        v_session_price := COALESCE(v_session_price, 0);
        
        IF v_billing_type = 'per_session' THEN
            SELECT COUNT(*) INTO v_sessions_count
            FROM public.attendance a
            JOIN public.schedules s ON a.session_id = s.id
            WHERE a.student_id = p_student_id
              AND s.group_id = v_enrollment.group_id
              AND a.date BETWEEN v_period_start AND v_period_end
              AND a.status IN ('present', 'late');
            
            v_total_due := v_total_due + (v_sessions_count * v_session_price);
        ELSE
            v_total_due := v_total_due + v_monthly_price;
        END IF;
    END LOOP;
    
    -- FIX: Read total paid from invoice_payments via student_invoices
    SELECT COALESCE(SUM(ip.amount), 0) INTO v_total_paid
    FROM public.invoice_payments ip
    JOIN public.student_invoices si ON ip.invoice_id = si.id
    WHERE si.student_id = p_student_id 
      AND si.center_id = p_center_id;
    
    RETURN json_build_object(
        'total_due', v_total_due,
        'total_paid', v_total_paid,
        'balance', v_total_due - v_total_paid
    );
END;
$$;


ALTER FUNCTION public.get_student_balance_summary(p_student_id uuid, p_center_id uuid) OWNER TO postgres;

--
-- Name: get_student_burnout_risk(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_burnout_risk(p_student_id uuid, p_center_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_last_month_attendance_count int;
    v_this_month_attendance_count int;
    v_last_month_avg_grade numeric;
    v_this_month_avg_grade numeric;
    v_attendance_drop_risk boolean := false;
    v_grades_drop_risk boolean := false;
BEGIN
    -- Attendance Drop Logic
    SELECT COUNT(*) INTO v_last_month_attendance_count
    FROM public.attendance
    WHERE student_id = p_student_id
      AND center_id = p_center_id
      AND created_at >= (now() - interval '60 days')
      AND created_at < (now() - interval '30 days')
      AND status IN ('present', 'late');

    SELECT COUNT(*) INTO v_this_month_attendance_count
    FROM public.attendance
    WHERE student_id = p_student_id
      AND center_id = p_center_id
      AND created_at >= (now() - interval '30 days')
      AND status IN ('present', 'late');

    IF v_last_month_attendance_count > 0 THEN
        IF ((v_last_month_attendance_count - v_this_month_attendance_count)::numeric / v_last_month_attendance_count) > 0.20 THEN
            v_attendance_drop_risk := true;
        END IF;
    END IF;

    -- Grades Drop Logic
    SELECT avg((score / NULLIF(max_score, 0)) * 100) INTO v_last_month_avg_grade
    FROM public.grades
    WHERE student_id = p_student_id
      AND center_id = p_center_id
      AND created_at >= (now() - interval '60 days')
      AND created_at < (now() - interval '30 days');

    SELECT avg((score / NULLIF(max_score, 0)) * 100) INTO v_this_month_avg_grade
    FROM public.grades
    WHERE student_id = p_student_id
      AND center_id = p_center_id
      AND created_at >= (now() - interval '30 days');

    IF v_last_month_avg_grade IS NOT NULL AND v_last_month_avg_grade > 0 THEN
        IF ((v_last_month_avg_grade - COALESCE(v_this_month_avg_grade, 0)) / v_last_month_avg_grade) > 0.15 THEN
            v_grades_drop_risk := true;
        END IF;
    END IF;

    RETURN v_attendance_drop_risk AND v_grades_drop_risk;
END;
$$;


ALTER FUNCTION public.get_student_burnout_risk(p_student_id uuid, p_center_id uuid) OWNER TO postgres;

--
-- Name: get_student_centers_detailed(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_centers_detailed(p_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE v_student_id UUID; v_result JSON;
BEGIN
  -- Get the student ID
  SELECT id INTO v_student_id FROM students WHERE user_id = p_user_id LIMIT 1;
  IF v_student_id IS NULL THEN RETURN '[]'::json; END IF;
  
  -- Gather center info, ensuring we use student_user_id
  SELECT COALESCE(json_agg(center_info), '[]'::json) INTO v_result
  FROM (
    SELECT json_build_object(
      'center_id', ct.id, 'center_name', ct.name, 'logo_url', ct.logo_url, 'enrollment_status', se.status,
      'groups_count', (SELECT COUNT(*) FROM student_group_enrollments sge JOIN groups g ON g.id = sge.group_id WHERE sge.student_id = v_student_id AND g.center_id = ct.id AND sge.status = 'active'),
      'total_due', COALESCE((SELECT SUM(total_amount - paid_amount) FROM student_invoices WHERE student_id = v_student_id AND center_id = ct.id AND status NOT IN ('paid', 'cancelled')), 0),
      'total_paid', COALESCE((SELECT SUM(paid_amount) FROM student_invoices WHERE student_id = v_student_id AND center_id = ct.id), 0)
    ) as center_info
    FROM student_enrollments se 
    JOIN centers ct ON ct.id = se.center_id
    WHERE se.student_user_id = p_user_id AND se.status IN ('accepted', 'active')
  ) sub;
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_student_centers_detailed(p_user_id uuid) OWNER TO postgres;

--
-- Name: get_student_conversations(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_conversations(p_center_id uuid) RETURNS TABLE(conversation_id uuid, teacher_id uuid, teacher_name text, teacher_avatar text, last_message text, last_message_at timestamp with time zone, unread_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        c.id AS conversation_id,
        c.teacher_id,
        u.full_name AS teacher_name,
        u.avatar_url AS teacher_avatar,
        c.last_message,
        c.last_message_at,
        c.unread_count_student AS unread_count
    FROM public.conversations c
    JOIN public.users u ON c.teacher_id = u.id
    WHERE c.student_id = auth.uid()
    AND c.center_id = p_center_id
    ORDER BY c.last_message_at DESC NULLS LAST;
END;
$$;


ALTER FUNCTION public.get_student_conversations(p_center_id uuid) OWNER TO postgres;

--
-- Name: get_student_course_attendance(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_course_attendance(p_student_id uuid, p_center_id uuid DEFAULT NULL::uuid) RETURNS TABLE(course_id uuid, course_name text, teacher_name text, total_sessions bigint, present_count bigint, absent_count bigint, late_count bigint, attendance_rate double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_center_id UUID;
    v_student_id UUID;
BEGIN
    -- 1. Get actual student_id
    SELECT id INTO v_student_id FROM students WHERE user_id = p_student_id LIMIT 1;
    IF v_student_id IS NULL THEN
        v_student_id := p_student_id;
    END IF;

    -- 2. Determine Center ID
    IF p_center_id IS NULL THEN
        SELECT se.center_id INTO v_center_id 
        FROM student_enrollments se 
        WHERE se.student_id = v_student_id OR se.student_user_id = p_student_id
        LIMIT 1;
    ELSE
        v_center_id := p_center_id;
    END IF;

    -- 3. Query Stats Grouped by Course (via groups, not direct course_id)
    RETURN QUERY
    SELECT 
        c.id as course_id,
        COALESCE(c.name, g.group_name, 'غير محدد')::TEXT as course_name,
        COALESCE(u.full_name, 'غير محدد')::TEXT as teacher_name,
        COUNT(a.id) as total_sessions,
        COUNT(a.id) FILTER (WHERE a.status = 'present') as present_count,
        COUNT(a.id) FILTER (WHERE a.status = 'absent') as absent_count,
        COUNT(a.id) FILTER (WHERE a.status = 'late') as late_count,
        CASE 
            WHEN COUNT(a.id) = 0 THEN 0.0
            ELSE (COUNT(a.id) FILTER (WHERE a.status IN ('present', 'late'))::FLOAT / COUNT(a.id)::FLOAT) * 100
        END as attendance_rate
    FROM attendance a
    JOIN groups g ON a.group_id = g.id
    LEFT JOIN courses c ON g.course_id = c.id
    LEFT JOIN users u ON g.teacher_id = u.id
    LEFT JOIN student_group_enrollments sge ON sge.group_id = g.id 
        AND (sge.student_id = v_student_id OR sge.student_id = p_student_id)
    WHERE a.student_id = v_student_id
      AND (v_center_id IS NULL OR g.center_id = v_center_id)
    GROUP BY c.id, c.name, g.group_name, u.full_name;
END;
$$;


ALTER FUNCTION public.get_student_course_attendance(p_student_id uuid, p_center_id uuid) OWNER TO postgres;

--
-- Name: get_student_courses(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_courses() RETURNS TABLE(id uuid, name text, description text, center_id uuid, teacher_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_student_id uuid;
BEGIN
  SELECT s.id INTO v_student_id FROM students s WHERE s.user_id = v_user_id LIMIT 1;
  IF v_student_id IS NULL THEN
    SELECT se.student_id INTO v_student_id FROM student_enrollments se WHERE se.student_user_id = v_user_id LIMIT 1;
  END IF;
  v_student_id := COALESCE(v_student_id, v_user_id);

  RETURN QUERY
  SELECT DISTINCT
    c.id,
    COALESCE(c.name, 'غير محدد')::TEXT as name,
    c.description::TEXT,
    c.center_id,
    COALESCE(u.full_name, 'غير محدد')::TEXT
  FROM courses c
  JOIN groups g ON g.course_id = c.id
  JOIN student_group_enrollments sge ON sge.group_id = g.id
  LEFT JOIN teachers t ON g.teacher_id = t.id
  LEFT JOIN users u ON t.user_id = u.id
  WHERE (sge.student_id = v_student_id OR sge.student_id = v_user_id)
  AND sge.status = 'active'
  ORDER BY 2;
END;
$$;


ALTER FUNCTION public.get_student_courses() OWNER TO postgres;

--
-- Name: get_student_dashboard_summary(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_dashboard_summary(p_user_id uuid, p_center_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_student_id UUID;
  v_today_text TEXT;
  v_result JSON;
BEGIN
  -- Get Student ID
  SELECT id INTO v_student_id
  FROM students
  WHERE user_id = p_user_id
  LIMIT 1;

  -- Fallback
  IF v_student_id IS NULL THEN
      SELECT student_id INTO v_student_id FROM student_enrollments WHERE student_user_id = p_user_id LIMIT 1;
  END IF;

  -- Get Today's Day Name
  SELECT lower(trim(to_char(CURRENT_DATE, 'Day'))) INTO v_today_text;

  SELECT json_build_object(
    'today_classes', (
      SELECT COUNT(*)
      FROM schedules s
      JOIN student_group_enrollments sge ON s.group_id = sge.group_id
      WHERE sge.student_id = v_student_id
      AND sge.status = 'active'
      AND lower(s.day_of_week) = v_today_text
      AND (p_center_id IS NULL OR s.center_id = p_center_id)
    ),
    'upcoming_assignments', (
      SELECT COUNT(*)
      FROM assignments a
      JOIN courses c ON a.course_id = c.id
      JOIN groups g ON g.course_id = c.id
      JOIN student_group_enrollments sge ON sge.group_id = g.id
      LEFT JOIN assignment_submissions sub ON sub.assignment_id = a.id AND sub.student_user_id = p_user_id
      WHERE sge.student_id = v_student_id
      AND sge.status = 'active'
      AND (p_center_id IS NULL OR a.center_id = p_center_id)
      AND a.due_date >= CURRENT_DATE
      AND sub.id IS NULL
    ),
    'pending_invoices', (
      SELECT COUNT(*)
      FROM student_invoices i
      WHERE i.student_id = v_student_id
      AND i.status = 'pending'
      AND (p_center_id IS NULL OR i.center_id = p_center_id)
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_student_dashboard_summary(p_user_id uuid, p_center_id uuid) OWNER TO postgres;

--
-- Name: get_student_grades(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_grades(p_center_id uuid DEFAULT NULL::uuid, p_course_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS TABLE(grade_id uuid, course_id uuid, course_name text, exam_type text, score numeric, max_score numeric, percentage numeric, comments text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_student_id UUID;
BEGIN
  SELECT id INTO v_student_id FROM students WHERE user_id = auth.uid() LIMIT 1;
  IF v_student_id IS NULL THEN RETURN; END IF;

  RETURN QUERY
  SELECT 
    gr.id AS grade_id,  -- ✅ Explicit alias
    c.id AS course_id,
    c.name AS course_name,
    gr.exam_type,
    gr.score,
    gr.max_score,
    ROUND((gr.score / NULLIF(gr.max_score, 0)) * 100, 1) AS percentage,
    gr.comments,
    gr.created_at
  FROM grades gr
  JOIN courses c ON gr.course_id = c.id
  LEFT JOIN groups g ON g.course_id = c.id 
  LEFT JOIN student_group_enrollments sge ON sge.group_id = g.id AND sge.student_id = gr.student_id
  WHERE gr.student_id = v_student_id
  AND (p_center_id IS NULL OR sge.center_id = p_center_id)
  AND (p_course_id IS NULL OR gr.course_id = p_course_id)
  ORDER BY gr.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.get_student_grades(p_center_id uuid, p_course_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: get_student_grades(uuid, text, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_grades(p_center_id uuid DEFAULT NULL::uuid, p_exam_type text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_student_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(grade_id uuid, course_id uuid, course_name text, exam_type text, score numeric, max_score numeric, grade_letter text, percentage numeric, comments text, graded_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_student_id UUID;
  v_user_id UUID;
BEGIN
  -- Use provided student_user_id if given, otherwise use auth.uid()
  v_user_id := COALESCE(p_student_user_id, auth.uid());
  
  -- Get student record
  SELECT id INTO v_student_id FROM students WHERE user_id = v_user_id LIMIT 1;
  
  IF v_student_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT 
    g.id,
    g.course_id,
    COALESCE(c.name, 'غير محدد')::TEXT,
    g.exam_type,
    g.score,
    g.max_score,
    g.grade_letter,
    CASE WHEN g.max_score > 0 THEN (g.score / g.max_score * 100) ELSE 0 END,
    g.comments,
    g.graded_at,
    g.created_at
  FROM grades g
  LEFT JOIN courses c ON g.course_id = c.id
  WHERE g.student_id = v_student_id
  AND g.deleted_at IS NULL
  AND (p_center_id IS NULL OR g.center_id = p_center_id)
  AND (p_exam_type IS NULL OR g.exam_type = p_exam_type)
  ORDER BY g.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.get_student_grades(p_center_id uuid, p_exam_type text, p_limit integer, p_offset integer, p_student_user_id uuid) OWNER TO postgres;

--
-- Name: get_student_grades(uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_grades(p_center_id uuid DEFAULT NULL::uuid, p_course_id uuid DEFAULT NULL::uuid, p_exam_type text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(grade_id uuid, course_id uuid, course_name text, exam_type text, score numeric, max_score numeric, percentage numeric, comments text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_student_id UUID;
BEGIN
  SELECT id INTO v_student_id FROM students WHERE user_id = auth.uid() LIMIT 1;
  IF v_student_id IS NULL THEN RETURN; END IF;

  RETURN QUERY
  SELECT 
    gr.id AS grade_id,
    c.id AS course_id,
    c.name AS course_name,
    gr.exam_type,
    gr.score,
    gr.max_score,
    ROUND((gr.score / NULLIF(gr.max_score, 0)) * 100, 1) AS percentage,
    gr.comments,
    gr.created_at
  FROM grades gr
  JOIN courses c ON gr.course_id = c.id
  LEFT JOIN groups g ON g.course_id = c.id 
  LEFT JOIN student_group_enrollments sge ON sge.group_id = g.id AND sge.student_id = gr.student_id
  WHERE gr.student_id = v_student_id
  AND (p_center_id IS NULL OR sge.center_id = p_center_id)
  AND (p_course_id IS NULL OR gr.course_id = p_course_id)
  AND (p_exam_type IS NULL OR gr.exam_type = p_exam_type)
  ORDER BY gr.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.get_student_grades(p_center_id uuid, p_course_id uuid, p_exam_type text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: get_student_home_stats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_home_stats() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_student_id uuid;
  v_courses_count INT := 0;
  v_centers_count INT := 0;
  v_attendance_rate NUMERIC := 0;
  v_pending_assignments INT := 0;
BEGIN
  -- Get student ID
  SELECT id INTO v_student_id FROM students WHERE user_id = v_user_id LIMIT 1;
  v_student_id := COALESCE(v_student_id, v_user_id);
  
  -- Count distinct courses from active enrollments
  SELECT COUNT(DISTINCT c.id) INTO v_courses_count
  FROM courses c
  JOIN groups g ON g.course_id = c.id
  JOIN student_group_enrollments sge ON sge.group_id = g.id
  WHERE (sge.student_id = v_student_id OR sge.student_id = v_user_id)
  AND sge.status = 'active';
  
  -- Count distinct centers
  SELECT COUNT(DISTINCT c.center_id) INTO v_centers_count
  FROM courses c
  JOIN groups g ON g.course_id = c.id
  JOIN student_group_enrollments sge ON sge.group_id = g.id
  WHERE (sge.student_id = v_student_id OR sge.student_id = v_user_id)
  AND sge.status = 'active';
  
  -- Count pending assignments
  SELECT COUNT(*) INTO v_pending_assignments
  FROM assignments a
  JOIN courses c ON a.course_id = c.id
  JOIN groups g ON g.course_id = c.id
  JOIN student_group_enrollments sge ON sge.group_id = g.id
  LEFT JOIN assignment_submissions sub ON sub.assignment_id = a.id 
    AND sub.student_user_id = v_user_id
  WHERE (sge.student_id = v_student_id OR sge.student_id = v_user_id)
  AND sge.status = 'active'
  AND sub.id IS NULL
  AND (a.due_date IS NULL OR a.due_date > NOW());
  
  RETURN json_build_object(
    'active_courses', v_courses_count,
    'centers_count', v_centers_count,
    'attendance_rate', v_attendance_rate,
    'pending_assignments', v_pending_assignments
  );
END;
$$;


ALTER FUNCTION public.get_student_home_stats() OWNER TO postgres;

--
-- Name: get_student_invoice_summary(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_invoice_summary(p_student_id uuid, p_center_id uuid, p_month integer, p_year integer) RETURNS TABLE(invoice_id uuid, total_amount numeric, paid_amount numeric, remaining_amount numeric, status text, items json, payments json)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    si.id as invoice_id,
    COALESCE(si.total_amount, 0) as total_amount,
    COALESCE((
      SELECT SUM(ip.amount) 
      FROM invoice_payments ip 
      WHERE ip.invoice_id = si.id
    ), 0) as paid_amount,
    COALESCE(si.total_amount, 0) - COALESCE((
      SELECT SUM(ip.amount) 
      FROM invoice_payments ip 
      WHERE ip.invoice_id = si.id
    ), 0) as remaining_amount,
    si.status::text,
    COALESCE((
      SELECT json_agg(json_build_object(
        'course_name', ii.course_name,
        'amount', ii.amount,
        'description', ii.description
      ))
      FROM invoice_items ii
      WHERE ii.invoice_id = si.id
    ), '[]'::json) as items,
    COALESCE((
      SELECT json_agg(json_build_object(
        'amount', ip.amount,
        'method', ip.payment_method,
        'paid_at', ip.paid_at
      ))
      FROM invoice_payments ip
      WHERE ip.invoice_id = si.id
    ), '[]'::json) as payments
  FROM student_invoices si
  WHERE si.student_id = p_student_id
    AND si.center_id = p_center_id
    AND si.month = p_month
    AND si.year = p_year;
END;
$$;


ALTER FUNCTION public.get_student_invoice_summary(p_student_id uuid, p_center_id uuid, p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: get_student_materials(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_materials(p_center_id uuid) RETURNS TABLE(id uuid, title text, description text, file_url text, file_type text, file_size bigint, course_name text, teacher_name text, created_at timestamp with time zone, download_count integer, course_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        sm.id,
        sm.title,
        sm.description,
        sm.file_url,
        sm.file_type,
        sm.file_size,
        c.name AS course_name,
        u.full_name AS teacher_name,
        sm.created_at,
        sm.download_count,
        sm.course_id 
    FROM public.study_materials sm
    LEFT JOIN public.courses c ON sm.course_id = c.id
    LEFT JOIN public.users u ON sm.teacher_id = u.id
    WHERE sm.center_id = p_center_id
    AND sm.is_published = true
    ORDER BY sm.created_at DESC;
END;
$$;


