--
-- Name: get_student_payments(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_payments(p_center_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_student_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, amount numeric, status text, payment_method text, payment_date date, notes text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_student_id UUID;
  v_user_id UUID;
BEGIN
  v_user_id := COALESCE(p_student_user_id, auth.uid());
  
  SELECT s.id INTO v_student_id FROM students s WHERE s.user_id = v_user_id LIMIT 1;
  
  IF v_student_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT 
    ip.id,
    ip.amount,
    'paid'::TEXT as status,
    ip.payment_method,
    ip.paid_at::date as payment_date,
    ip.notes,
    ip.created_at::timestamptz
  FROM invoice_payments ip
  JOIN student_invoices si ON ip.invoice_id = si.id
  WHERE si.student_id = v_student_id
  AND (p_center_id IS NULL OR si.center_id = p_center_id)
  ORDER BY ip.paid_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.get_student_payments(p_center_id uuid, p_limit integer, p_student_user_id uuid) OWNER TO postgres;

--
-- Name: get_student_payments(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_payments(p_center_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_limit integer DEFAULT NULL::integer) RETURNS TABLE(id uuid, course_id uuid, center_id uuid, amount numeric, paid_amount numeric, status text, due_date date, paid_at timestamp with time zone, description text, notes text, course_name text, center_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_student_id UUID;
BEGIN
  SELECT s.id INTO v_student_id FROM students s WHERE s.user_id = v_user_id LIMIT 1;
  IF v_student_id IS NULL THEN v_student_id := v_user_id; END IF;

  RETURN QUERY
  SELECT 
    ip.id,
    ii.course_id,
    si.center_id,
    ip.amount,
    ip.amount as paid_amount,
    'paid'::TEXT as status,
    si.due_date,
    ip.paid_at::TIMESTAMPTZ,
    ('فاتورة ' || si.month || '/' || si.year)::TEXT as description,
    ip.notes,
    COALESCE(
      (SELECT string_agg(ii2.course_name, ', ') FROM invoice_items ii2 WHERE ii2.invoice_id = si.id),
      'رسوم دراسية'
    )::TEXT as course_name,
    ctr.name as center_name
  FROM invoice_payments ip
  JOIN student_invoices si ON ip.invoice_id = si.id
  LEFT JOIN invoice_items ii ON ii.invoice_id = si.id
  LEFT JOIN centers ctr ON si.center_id = ctr.id
  WHERE si.student_id = v_student_id
  AND (p_center_id IS NULL OR si.center_id = p_center_id)
  GROUP BY ip.id, ip.amount, ip.paid_at, ip.notes, ip.payment_method,
           ii.course_id, si.center_id, si.due_date, si.month, si.year, si.id,
           ctr.name
  ORDER BY ip.paid_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.get_student_payments(p_center_id uuid, p_status text, p_limit integer) OWNER TO postgres;

--
-- Name: get_student_profitability_analysis(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_profitability_analysis(p_center_id uuid, p_limit integer DEFAULT 50) RETURNS TABLE(student_id uuid, student_name text, phone text, total_invoiced numeric, total_paid numeric, payment_reliability numeric, active_courses_count integer, profitability_score numeric, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  WITH student_financials AS (
    SELECT 
      s.id,
      s.name,
      s.phone,
      COALESCE(SUM(inv.total_amount), 0) as invoiced,
      COALESCE(SUM(inv.paid_amount), 0) as paid,
      (SELECT COUNT(*) FROM student_enrollments se 
       WHERE se.student_id = s.id 
       AND se.center_id = p_center_id 
       AND se.status = 'active') as courses_count
    FROM students s
    LEFT JOIN student_invoices inv ON inv.student_id = s.id AND inv.center_id = p_center_id
    WHERE EXISTS (
      SELECT 1 FROM student_enrollments se 
      WHERE se.student_id = s.id AND se.center_id = p_center_id
    )
    GROUP BY s.id, s.name, s.phone
  )
  SELECT 
    id,
    name,
    phone,
    invoiced,
    paid,
    -- Calculate Reliability
    CASE 
      WHEN invoiced > 0 THEN (paid / invoiced) * 100 
      ELSE 100 
    END as reliability,
    courses_count,
    -- Profitability Score (Simplified: Paid Amount weighted by Reliability)
    -- "Heavy Resource User" but "Low Payer" = Low Score
    (paid * (CASE WHEN invoiced > 0 THEN (paid/invoiced) ELSE 1 END)) as score,
    
    -- Status Tag
    CASE 
      WHEN (paid / NULLIF(invoiced, 0)) >= 0.95 THEN 'star'       -- يدفع بانتظام
      WHEN (paid / NULLIF(invoiced, 0)) >= 0.80 THEN 'good'       -- جيد
      WHEN (paid / NULLIF(invoiced, 0)) < 0.50 THEN 'drain'       -- استنزاف (يأخذ موارد ولا يدفع)
      ELSE 'monitor'
    END
    
  FROM student_financials
  ORDER BY score DESC -- Default: Most profitable first
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.get_student_profitability_analysis(p_center_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: get_student_schedule(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_schedule(p_day_of_week text DEFAULT NULL::text, p_center_id uuid DEFAULT NULL::uuid) RETURNS TABLE(schedule_id uuid, group_id uuid, course_id uuid, course_name text, group_name text, teacher_name text, day_of_week text, start_time time without time zone, end_time time without time zone, room_name text, center_id uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_student_id UUID;
BEGIN
  -- Get Student ID
  SELECT id INTO v_student_id
  FROM students
  WHERE user_id = v_user_id;

  RETURN QUERY
  SELECT
    s.id AS schedule_id,
    g.id AS group_id,
    c.id AS course_id,
    COALESCE(c.name, 'غير محدد')::TEXT,
    COALESCE(g.group_name, 'مجموعة')::TEXT,
    COALESCE(u.full_name, 'غير محدد')::TEXT,
    -- Capitalize first letter for consistency with app expectations (Monday, Tuesday...)
    initcap(s.day_of_week)::TEXT AS day_of_week,
    s.start_time,
    s.end_time,
    COALESCE(r.name, 'القاعة الرئيسية')::TEXT,
    s.center_id
  FROM schedules s
  JOIN groups g ON s.group_id = g.id
  JOIN courses c ON g.course_id = c.id
  LEFT JOIN users u ON g.teacher_id = u.id
  LEFT JOIN classrooms r ON s.classroom_id = r.id
  JOIN student_group_enrollments sge ON sge.group_id = g.id
  WHERE (sge.student_id = v_student_id OR sge.student_id = v_user_id)
  AND sge.status = 'active'
  AND (p_center_id IS NULL OR s.center_id = p_center_id)
  AND (
      p_day_of_week IS NULL 
      OR 
      lower(s.day_of_week) = lower(p_day_of_week)
  )
  ORDER BY 
    CASE lower(s.day_of_week)
      WHEN 'saturday' THEN 1
      WHEN 'sunday' THEN 2
      WHEN 'monday' THEN 3
      WHEN 'tuesday' THEN 4
      WHEN 'wednesday' THEN 5
      WHEN 'thursday' THEN 6
      WHEN 'friday' THEN 7
      ELSE 8
    END,
    s.start_time;
END;
$$;


ALTER FUNCTION public.get_student_schedule(p_day_of_week text, p_center_id uuid) OWNER TO postgres;

--
-- Name: get_student_statistics(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_statistics(p_student_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    result JSON;
BEGIN
    SELECT json_build_object(
        'student_id', p_student_id,
        'total_enrollments', COUNT(DISTINCT se.id),
        'active_enrollments', COUNT(*) FILTER (WHERE se.status = 'active'),
        'completed_enrollments', COUNT(*) FILTER (WHERE se.status = 'completed'),
        'total_courses', COUNT(DISTINCT se.center_id),
        'total_payments', COALESCE(SUM(p.amount), 0),
        'completed_payments', COALESCE(SUM(p.amount) FILTER (WHERE p.status = 'completed'), 0),
        'pending_payments', COALESCE(SUM(p.amount) FILTER (WHERE p.status = 'pending'), 0),
        'average_grade', COALESCE(AVG(g.percentage), 0),
        'highest_grade', COALESCE(MAX(g.percentage), 0),
        'lowest_grade', COALESCE(MIN(g.percentage), 0),
        'total_attendance', COUNT(DISTINCT a.id),
        'present_count', COUNT(*) FILTER (WHERE a.status = 'present'),
        'absent_count', COUNT(*) FILTER (WHERE a.status = 'absent'),
        'attendance_rate', CASE 
            WHEN COUNT(DISTINCT a.id) > 0 
            THEN ROUND((COUNT(*) FILTER (WHERE a.status = 'present')::NUMERIC / COUNT(DISTINCT a.id)) * 100, 2)
            ELSE 0
        END
    )
    INTO result
    FROM public.student_enrollments se
    LEFT JOIN public.payments p ON p.student_id = se.user_id
    LEFT JOIN public.grades g ON g.user_id = se.user_id
    LEFT JOIN public.attendance a ON a.user_id = se.user_id
    WHERE se.user_id = p_student_id;
    
    RETURN result;
END;
$$;


ALTER FUNCTION public.get_student_statistics(p_student_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_student_statistics(p_student_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_student_statistics(p_student_id uuid) IS 'إحصائيات شاملة للطالب - الدرجات، الحضور، المدفوعات';


--
-- Name: get_student_statistics(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_student_statistics(p_student_id uuid, p_center_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_result json; v_groups_data json; v_enrollment_months numeric;
  v_total_paid_amount numeric := 0; v_total_due_amount numeric := 0;
  v_attendance_rate numeric := 0; v_present_count integer := 0; v_total_attendance integer := 0; v_user_id uuid;
BEGIN
  SELECT user_id INTO v_user_id FROM students WHERE id = p_student_id;
  SELECT COALESCE(json_agg(json_build_object(
    'group_id', g.id, 'group_name', g.group_name, 'course_name', c.name, 'grade_level', g.grade_level,
    'day_of_week', g.day_of_week, 'start_time', g.start_time, 'end_time', g.end_time, 'monthly_fee', COALESCE(g.monthly_fee, c.fee, 0),
    'enrollment_date', sge.enrolled_at, 'status', sge.status
  )), '[]'::json) INTO v_groups_data
  FROM student_group_enrollments sge JOIN groups g ON sge.group_id = g.id LEFT JOIN courses c ON g.course_id = c.id
  WHERE sge.student_id = p_student_id AND sge.status = 'active' AND (p_center_id IS NULL OR g.center_id = p_center_id);
  
  SELECT COALESCE(SUM(si.paid_amount), 0), COALESCE(SUM(si.total_amount - si.paid_amount) FILTER (WHERE si.status != 'paid'), 0)
  INTO v_total_paid_amount, v_total_due_amount FROM student_invoices si
  WHERE si.student_id = p_student_id AND (p_center_id IS NULL OR si.center_id = p_center_id);
  
  SELECT COUNT(*) FILTER (WHERE a.status = 'present'), COUNT(*) INTO v_present_count, v_total_attendance
  FROM attendance a WHERE a.student_user_id = v_user_id AND (p_center_id IS NULL OR a.center_id = p_center_id) AND a.attendance_date >= CURRENT_DATE - INTERVAL '30 days';
  v_attendance_rate := CASE WHEN v_total_attendance > 0 THEN ROUND((v_present_count::numeric / v_total_attendance) * 100, 1) ELSE 0 END;
  
  SELECT COALESCE(EXTRACT(MONTH FROM AGE(NOW(), MIN(sge.enrolled_at))), 0) INTO v_enrollment_months
  FROM student_group_enrollments sge WHERE sge.student_id = p_student_id AND (p_center_id IS NULL OR EXISTS (SELECT 1 FROM groups g WHERE g.id = sge.group_id AND g.center_id = p_center_id));
  
  v_result := json_build_object(
    'student_id', p_student_id, 'groups_count', json_array_length(v_groups_data), 'groups', v_groups_data,
    'total_paid', v_total_paid_amount, 'total_due', v_total_due_amount, 'balance', -v_total_due_amount,
    'attendance', json_build_object('rate', v_attendance_rate, 'present', v_present_count, 'total', v_total_attendance),
    'enrollment_months', v_enrollment_months, 'average_grade', COALESCE((SELECT AVG(score) FROM grades WHERE student_id = p_student_id), 0));
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_student_statistics(p_student_id uuid, p_center_id uuid) OWNER TO postgres;

--
-- Name: get_students_roster(uuid, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_students_roster(p_center_id uuid, p_page integer DEFAULT 1, p_limit integer DEFAULT 20, p_search_query text DEFAULT ''::text) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_offset INT := (p_page - 1) * p_limit;
  v_result JSON;
BEGIN
  SELECT json_agg(t) INTO v_result
  FROM (
    SELECT 
      s.id,
      s.student_code,
      COALESCE(u.full_name, s.full_name) as full_name,
      COALESCE(u.phone, s.phone) as phone,
      COALESCE(u.avatar_url, s.avatar_url) as avatar_url,
      se.grade_level,
      se.enrolled_at as enrollment_date,
      NULL as group_name,
      NULL as group_id,
      COALESCE((
        SELECT SUM(inv.total_amount - inv.paid_amount)
        FROM student_invoices inv
        WHERE inv.center_id = p_center_id 
          AND inv.student_id = s.id 
          AND inv.status != 'void'
      ), 0) as balance
    FROM student_enrollments se
    JOIN students s ON se.student_id = s.id
    LEFT JOIN users u ON se.student_user_id = u.id

    WHERE se.center_id = p_center_id
      AND se.status IN ('active', 'accepted')
      AND (
        p_search_query = '' OR 
        COALESCE(u.full_name, s.full_name) ILIKE '%' || p_search_query || '%' OR
        COALESCE(u.phone, s.phone) ILIKE '%' || p_search_query || '%' OR
        s.student_code ILIKE '%' || p_search_query || '%'
      )
    ORDER BY u.full_name ASC
    LIMIT p_limit OFFSET v_offset
  ) t;

  RETURN COALESCE(v_result, '[]'::json);
END;
$$;


ALTER FUNCTION public.get_students_roster(p_center_id uuid, p_page integer, p_limit integer, p_search_query text) OWNER TO postgres;

--
-- Name: get_students_roster(uuid, integer, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_students_roster(p_center_id uuid, p_page integer DEFAULT 1, p_limit integer DEFAULT 20, p_search_query text DEFAULT ''::text, p_status text DEFAULT NULL::text, p_grade_level text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_offset INT := (p_page - 1) * p_limit;
  v_result JSON;
BEGIN
  SELECT json_agg(t) INTO v_result
  FROM (
    SELECT 
      s.id,
      s.student_code,
      COALESCE(u.full_name, s.full_name) as full_name,
      COALESCE(u.phone, s.phone) as phone,
      COALESCE(u.avatar_url, s.avatar_url) as avatar_url,
      se.grade_level,
      se.status,
      se.enrolled_at as enrollment_date,
      NULL as group_name,
      NULL as group_id,
      COALESCE((
        SELECT SUM(inv.total_amount - inv.paid_amount)
        FROM student_invoices inv
        WHERE inv.center_id = p_center_id 
          AND inv.student_id = s.id 
          AND inv.status != 'void'
      ), 0) as balance
    FROM student_enrollments se
    JOIN students s ON se.student_id = s.id
    LEFT JOIN users u ON se.student_user_id = u.id

    WHERE se.center_id = p_center_id
      -- Status Filter
      AND (
         p_status IS NULL 
         OR (p_status = 'active' AND se.status IN ('active', 'accepted'))
         OR (p_status = 'suspended' AND se.status = 'suspended')
         OR (p_status = 'inactive' AND se.status = 'rejected')
         OR se.status = p_status
      )
      -- Grade Level Filter
      AND (
          p_grade_level IS NULL OR p_grade_level = '' OR p_grade_level = 'الكل'
          OR se.grade_level = p_grade_level
      )
      -- Search Query
      AND (
        p_search_query = '' OR 
        COALESCE(u.full_name, s.full_name) ILIKE '%' || p_search_query || '%' OR
        COALESCE(u.phone, s.phone) ILIKE '%' || p_search_query || '%' OR
        s.student_code ILIKE '%' || p_search_query || '%'
      )
    ORDER BY u.full_name ASC
    LIMIT p_limit OFFSET v_offset
  ) t;

  RETURN COALESCE(v_result, '[]'::json);
END;
$$;


ALTER FUNCTION public.get_students_roster(p_center_id uuid, p_page integer, p_limit integer, p_search_query text, p_status text, p_grade_level text) OWNER TO postgres;

--
-- Name: get_table_sizes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_table_sizes() RETURNS TABLE(schema_name text, table_name text, total_size text, table_size text, indexes_size text, row_count bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        schemaname::TEXT,
        tablename::TEXT,
        pg_size_pretty(pg_total_relation_size(schemaname||'.'||tablename)) AS total_size,
        pg_size_pretty(pg_relation_size(schemaname||'.'||tablename)) AS table_size,
        pg_size_pretty(pg_total_relation_size(schemaname||'.'||tablename) - pg_relation_size(schemaname||'.'||tablename)) AS indexes_size,
        (SELECT COUNT(*) FROM (SELECT 1 FROM ONLY pg_catalog.pg_class WHERE relname = tablename LIMIT 1000000) t) AS row_count
    FROM pg_tables
    WHERE schemaname = 'public'
    ORDER BY pg_total_relation_size(schemaname||'.'||tablename) DESC;
END;
$$;


ALTER FUNCTION public.get_table_sizes() OWNER TO postgres;

--
-- Name: FUNCTION get_table_sizes(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_table_sizes() IS 'الحصول على أحجام الجداول والـ Indexes';


--
-- Name: get_teacher_salary_breakdown(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_teacher_salary_breakdown(p_teacher_id uuid, p_center_id uuid, p_month integer, p_year integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_teacher_name TEXT;
  v_salary_type TEXT;
  v_salary_amount DECIMAL;
  v_base_salary DECIMAL := 0;
  v_sessions_items JSONB := '[]'::JSONB;
  v_percentage_items JSONB := '[]'::JSONB;
  v_sessions_total DECIMAL := 0;
  v_percentage_total DECIMAL := 0;
  v_existing_salary_id UUID;
  v_existing_status TEXT;
  v_existing_bonuses JSONB := '[]'::JSONB;
  v_existing_deductions JSONB := '[]'::JSONB;
BEGIN
  -- 1. Get Teacher Info
  SELECT 
    COALESCE(u.full_name, 'معلم'),
    COALESCE(te.salary_type, 'fixed'),
    COALESCE(te.salary_amount, 0)
  INTO v_teacher_name, v_salary_type, v_salary_amount
  FROM teachers t
  LEFT JOIN users u ON u.id = t.user_id
  LEFT JOIN teacher_enrollments te ON te.teacher_id = t.id AND te.center_id = p_center_id
  WHERE t.id = p_teacher_id;

  -- 2. Check for existing saved salary
  SELECT id, status INTO v_existing_salary_id, v_existing_status
  FROM teacher_salaries
  WHERE teacher_id = p_teacher_id 
    AND center_id = p_center_id 
    AND month = p_month 
    AND year = p_year;

  IF v_existing_salary_id IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'description', description, 
        'amount', amount,
        'type', 'bonus'
      )
    ), '[]'::jsonb)
    INTO v_existing_bonuses
    FROM salary_items 
    WHERE salary_id = v_existing_salary_id AND type = 'bonus';
    
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'description', description, 
        'amount', amount,
        'type', 'deduction'
      )
    ), '[]'::jsonb)
    INTO v_existing_deductions
    FROM salary_items 
    WHERE salary_id = v_existing_salary_id AND type = 'deduction';
  END IF;

  -- 3. Calculate Components based on Type
  IF v_salary_type = 'fixed' THEN
    v_base_salary := v_salary_amount;
    
  ELSIF v_salary_type = 'per_session' THEN
    v_base_salary := 0;
    
    -- Count sessions from attendance
    WITH teacher_sessions AS (
      SELECT DISTINCT a.group_id, a.date::date
      FROM attendance a
      JOIN groups g ON g.id = a.group_id
      WHERE g.teacher_id = p_teacher_id
        AND g.center_id = p_center_id
        AND EXTRACT(MONTH FROM a.date) = p_month
        AND EXTRACT(YEAR FROM a.date) = p_year
    )
    SELECT 
      COALESCE(jsonb_agg(jsonb_build_object(
        'group', g.group_name,
        'count', session_data.cnt,
        'rate', v_salary_amount,
        'total', session_data.cnt * v_salary_amount
      )), '[]'::jsonb),
      COALESCE(SUM(session_data.cnt * v_salary_amount), 0)
    INTO v_sessions_items, v_sessions_total
    FROM (
      SELECT ts.group_id, COUNT(*) as cnt
      FROM teacher_sessions ts
      GROUP BY ts.group_id
    ) session_data
    JOIN groups g ON g.id = session_data.group_id;
    
  ELSIF v_salary_type = 'percentage' THEN
    v_base_salary := 0;
    
    -- FIX: Calculate percentage of collected fees from invoice_payments (single source of truth)
    WITH group_collections AS (
      SELECT 
        g.id as group_id,
        g.group_name,
        g.current_students,
        COUNT(DISTINCT ip.id) as payment_count,
        COALESCE(SUM(ip.amount), 0) as collected
      FROM groups g
      LEFT JOIN student_group_enrollments sge ON sge.group_id = g.id AND sge.status = 'active'
      LEFT JOIN student_invoices si ON si.student_id = sge.student_id 
        AND si.center_id = g.center_id
        AND si.month = p_month
        AND si.year = p_year
      LEFT JOIN invoice_payments ip ON ip.invoice_id = si.id
      WHERE g.teacher_id = p_teacher_id
        AND g.center_id = p_center_id
        AND g.is_active = true
      GROUP BY g.id, g.group_name, g.current_students
    )
    SELECT 
      COALESCE(jsonb_agg(jsonb_build_object(
        'group', gc.group_name,
        'students', gc.current_students,
        'collected', gc.collected,
        'percentage', v_salary_amount,
        'total', ROUND((gc.collected * v_salary_amount / 100), 2),
        'center_share', ROUND((gc.collected * (100 - v_salary_amount) / 100), 2)
      )), '[]'::jsonb),
      COALESCE(SUM(ROUND((gc.collected * v_salary_amount / 100), 2)), 0)
    INTO v_percentage_items, v_percentage_total
    FROM group_collections gc;
  END IF;

  -- Defaults
  v_sessions_items := COALESCE(v_sessions_items, '[]'::JSONB);
  v_percentage_items := COALESCE(v_percentage_items, '[]'::JSONB);
  v_existing_bonuses := COALESCE(v_existing_bonuses, '[]'::JSONB);
  v_existing_deductions := COALESCE(v_existing_deductions, '[]'::JSONB);

  -- Return comprehensive object
  RETURN jsonb_build_object(
    'teacher_name', v_teacher_name,
    'salary_id', v_existing_salary_id,
    'status', COALESCE(v_existing_status, 'draft'),
    'salary_type', v_salary_type,
    'salary_percentage', v_salary_amount,
    'base_salary', v_base_salary,
    'sessions_total', v_sessions_total,
    'percentage_total', v_percentage_total,
    'sessions', v_sessions_items,
    'percentage_items', v_percentage_items,
    'bonuses', v_existing_bonuses,
    'deductions', v_existing_deductions,
    'gross_preview', v_base_salary + v_sessions_total + v_percentage_total
  );
END;
$$;


ALTER FUNCTION public.get_teacher_salary_breakdown(p_teacher_id uuid, p_center_id uuid, p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: get_teacher_salary_detailed(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_teacher_salary_detailed(p_teacher_id uuid, p_center_id uuid, p_month integer, p_year integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_result JSONB;
  v_teacher_info JSONB;
  v_groups_data JSONB;
  v_by_grade JSONB;
  v_summary JSONB;
  v_comparison JSONB;
  v_insights JSONB;
  v_bonuses JSONB;
  v_deductions JSONB;
  
  v_teacher_name TEXT;
  v_salary_type TEXT;
  v_percentage DECIMAL;
  v_salary_amount DECIMAL;
  
  v_total_students INTEGER := 0;
  v_paid_students INTEGER := 0;
  v_total_expected DECIMAL := 0;
  v_total_collected DECIMAL := 0;
  v_teacher_share DECIMAL := 0;
  
  v_last_month_collected DECIMAL := 0;
  v_last_month_share DECIMAL := 0;
  
  v_existing_salary_id UUID;
  v_existing_status TEXT := 'draft';
BEGIN
  -- Step 1: Get teacher info
  SELECT 
    COALESCE(u.full_name, 'معلم'),
    COALESCE(te.salary_type, 'percentage'),
    COALESCE(te.salary_amount, 40),
    COALESCE(te.salary_amount, 0)
  INTO v_teacher_name, v_salary_type, v_percentage, v_salary_amount
  FROM teachers t
  LEFT JOIN users u ON u.id = t.user_id
  LEFT JOIN teacher_enrollments te ON te.teacher_id = t.id AND te.center_id = p_center_id
  WHERE t.id = p_teacher_id;
  
  IF v_salary_type = 'fixed' THEN v_percentage := 0;
  ELSIF v_salary_type = 'per_session' THEN v_percentage := 0;
  END IF;
  
  v_teacher_info := jsonb_build_object(
    'name', v_teacher_name, 'salary_type', v_salary_type,
    'percentage', v_percentage, 'salary_amount', v_salary_amount
  );
  
  -- Step 2: Group details — ✅ FIX: Use invoice_payments
  WITH group_details AS (
    SELECT 
      g.id as group_id, g.group_name,
      COALESCE(g.grade_level, c.grade_level, 'غير محدد') as grade_level,
      COALESCE(g.monthly_fee, c.fee, 0) as fee,
      (SELECT COUNT(*) FROM student_group_enrollments sge WHERE sge.group_id = g.id AND sge.status = 'active') as total_students,
      -- ✅ Paid students from invoice_payments
      (SELECT COUNT(DISTINCT sge2.student_id) 
       FROM student_group_enrollments sge2
       JOIN student_invoices si ON si.student_id = sge2.student_id AND si.center_id = p_center_id
         AND si.month = p_month AND si.year = p_year
       JOIN invoice_payments ip ON ip.invoice_id = si.id
       WHERE sge2.group_id = g.id AND sge2.status = 'active') as paid_students,
      -- ✅ Collected from invoice_payments
      (SELECT COALESCE(SUM(ip.amount), 0)
       FROM student_group_enrollments sge3
       JOIN student_invoices si ON si.student_id = sge3.student_id AND si.center_id = p_center_id
         AND si.month = p_month AND si.year = p_year
       JOIN invoice_payments ip ON ip.invoice_id = si.id
       WHERE sge3.group_id = g.id AND sge3.status = 'active') as collected,
      (SELECT COUNT(DISTINCT a.date::date) FROM attendance a
       WHERE a.group_id = g.id AND EXTRACT(MONTH FROM a.date) = p_month AND EXTRACT(YEAR FROM a.date) = p_year) as sessions_count
    FROM groups g
    LEFT JOIN courses c ON c.id = g.course_id
    WHERE g.teacher_id = p_teacher_id AND g.center_id = p_center_id AND g.is_active = true
  )
  SELECT 
    jsonb_agg(jsonb_build_object(
      'id', gd.group_id, 'name', gd.group_name, 'grade_level', gd.grade_level, 'fee', gd.fee,
      'students', jsonb_build_object('total', gd.total_students, 'paid', gd.paid_students, 'unpaid', gd.total_students - gd.paid_students),
      'sessions_count', gd.sessions_count, 'expected', gd.total_students * gd.fee, 'collected', gd.collected,
      'teacher_share', CASE 
        WHEN v_salary_type = 'percentage' THEN gd.collected * v_percentage / 100
        WHEN v_salary_type = 'per_session' THEN gd.sessions_count * v_salary_amount
        ELSE 0 END,
      'collection_rate', CASE WHEN gd.total_students > 0 THEN ROUND((gd.paid_students::DECIMAL / gd.total_students) * 100) ELSE 0 END
    ) ORDER BY gd.collected DESC),
    SUM(gd.total_students), SUM(gd.paid_students), SUM(gd.total_students * gd.fee), SUM(gd.collected),
    SUM(CASE WHEN v_salary_type = 'percentage' THEN gd.collected * v_percentage / 100
             WHEN v_salary_type = 'per_session' THEN gd.sessions_count * v_salary_amount ELSE 0 END)
  INTO v_groups_data, v_total_students, v_paid_students, v_total_expected, v_total_collected, v_teacher_share
  FROM group_details gd;
  
  v_groups_data := COALESCE(v_groups_data, '[]'::jsonb);
  v_total_students := COALESCE(v_total_students, 0);
  v_paid_students := COALESCE(v_paid_students, 0);
  v_total_expected := COALESCE(v_total_expected, 0);
  v_total_collected := COALESCE(v_total_collected, 0);
  v_teacher_share := COALESCE(v_teacher_share, 0);
  
  IF v_salary_type = 'fixed' THEN v_teacher_share := v_salary_amount; END IF;
  
  -- Step 3: By grade — ✅ FIX: Use invoice_payments
  WITH grade_summary AS (
    SELECT 
      COALESCE(g.grade_level, c.grade_level, 'غير محدد') as grade,
      COUNT(DISTINCT sge.student_id) as students,
      COALESCE(SUM(ip.amount), 0) as collected
    FROM groups g
    LEFT JOIN courses c ON c.id = g.course_id
    LEFT JOIN student_group_enrollments sge ON sge.group_id = g.id AND sge.status = 'active'
    LEFT JOIN student_invoices si ON si.student_id = sge.student_id AND si.center_id = p_center_id
      AND si.month = p_month AND si.year = p_year
    LEFT JOIN invoice_payments ip ON ip.invoice_id = si.id
    WHERE g.teacher_id = p_teacher_id AND g.center_id = p_center_id AND g.is_active = true
    GROUP BY COALESCE(g.grade_level, c.grade_level, 'غير محدد')
  )
  SELECT jsonb_agg(jsonb_build_object(
    'grade', gs.grade, 'students', gs.students, 'collected', gs.collected,
    'share', CASE WHEN v_salary_type = 'percentage' THEN gs.collected * v_percentage / 100 ELSE 0 END,
    'percentage', CASE WHEN v_total_collected > 0 THEN ROUND((gs.collected / v_total_collected) * 100) ELSE 0 END
  ) ORDER BY gs.collected DESC)
  INTO v_by_grade FROM grade_summary gs;
  v_by_grade := COALESCE(v_by_grade, '[]'::jsonb);
  
  -- Step 4: Comparison — ✅ FIX: Use invoice_payments
  WITH last_month AS (
    SELECT 
      CASE WHEN p_month = 1 THEN 12 ELSE p_month - 1 END as lm_month,
      CASE WHEN p_month = 1 THEN p_year - 1 ELSE p_year END as lm_year
  )
  SELECT COALESCE(SUM(ip.amount), 0)
  INTO v_last_month_collected
  FROM invoice_payments ip
  JOIN student_invoices si ON si.id = ip.invoice_id
  JOIN student_group_enrollments sge ON sge.student_id = si.student_id
  JOIN groups g ON g.id = sge.group_id AND g.teacher_id = p_teacher_id
  CROSS JOIN last_month lm
  WHERE si.center_id = p_center_id AND si.month = lm.lm_month AND si.year = lm.lm_year;
  
  IF v_salary_type = 'percentage' THEN v_last_month_share := v_last_month_collected * v_percentage / 100;
  ELSIF v_salary_type = 'fixed' THEN v_last_month_share := v_salary_amount;
  END IF;
  
  v_comparison := jsonb_build_object(
    'last_month', jsonb_build_object('collected', v_last_month_collected, 'share', v_last_month_share),
    'current', jsonb_build_object('collected', v_total_collected, 'share', v_teacher_share),
    'change_amount', v_teacher_share - v_last_month_share,
    'change_percentage', CASE WHEN v_last_month_share > 0 THEN ROUND(((v_teacher_share - v_last_month_share) / v_last_month_share) * 100) ELSE 0 END
  );
  
  -- Step 5: Insights
  v_insights := '[]'::jsonb;
  IF jsonb_array_length(v_groups_data) > 0 THEN
    v_insights := v_insights || jsonb_build_array(jsonb_build_object('type', 'success', 'icon', '🏆',
      'message', 'أفضل مجموعة: ' || (v_groups_data->0->>'name') || ' - تحصيل ' || (v_groups_data->0->>'collection_rate') || '%'));
  END IF;
  IF v_total_students > 0 AND (v_paid_students::DECIMAL / v_total_students) < 0.7 THEN
    v_insights := v_insights || jsonb_build_array(jsonb_build_object('type', 'warning', 'icon', '⚠️',
      'message', 'نسبة التحصيل منخفضة (' || ROUND((v_paid_students::DECIMAL / v_total_students) * 100) || '%) - ' || (v_total_students - v_paid_students) || ' طالب لم يدفعوا'));
  END IF;
  IF v_teacher_share > v_last_month_share AND v_last_month_share > 0 THEN
    v_insights := v_insights || jsonb_build_array(jsonb_build_object('type', 'success', 'icon', '📈',
      'message', 'رائع! أداؤك تحسن بنسبة ' || ROUND(((v_teacher_share - v_last_month_share) / v_last_month_share) * 100) || '% عن الشهر السابق'));
  ELSIF v_teacher_share < v_last_month_share AND v_last_month_share > 0 THEN
    v_insights := v_insights || jsonb_build_array(jsonb_build_object('type', 'info', 'icon', '📉',
      'message', 'انخفض الدخل بنسبة ' || ROUND(((v_last_month_share - v_teacher_share) / v_last_month_share) * 100) || '% عن الشهر السابق'));
  END IF;
  IF v_total_expected > v_total_collected AND v_salary_type = 'percentage' THEN
    v_insights := v_insights || jsonb_build_array(jsonb_build_object('type', 'info', 'icon', '💡',
      'message', 'لو كان التحصيل 100% كان نصيبك سيكون: ' || ROUND(v_total_expected * v_percentage / 100) || ' ج (+' || ROUND((v_total_expected - v_total_collected) * v_percentage / 100) || ' ج)'));
  END IF;
  
  -- Step 6: Bonuses & deductions
  SELECT id, status INTO v_existing_salary_id, v_existing_status
  FROM teacher_salaries WHERE teacher_id = p_teacher_id AND center_id = p_center_id AND month = p_month AND year = p_year;
  v_existing_status := COALESCE(v_existing_status, 'draft');
  
  IF v_existing_salary_id IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object('description', description, 'amount', amount)), '[]'::jsonb)
    INTO v_bonuses FROM salary_items WHERE salary_id = v_existing_salary_id AND type = 'bonus';
    SELECT COALESCE(jsonb_agg(jsonb_build_object('description', description, 'amount', amount)), '[]'::jsonb)
    INTO v_deductions FROM salary_items WHERE salary_id = v_existing_salary_id AND type = 'deduction';
  ELSE
    v_bonuses := '[]'::jsonb; v_deductions := '[]'::jsonb;
  END IF;
  
  -- Step 7: Build result
  v_summary := jsonb_build_object(
    'total_students', v_total_students, 'paid_students', v_paid_students,
    'unpaid_students', v_total_students - v_paid_students, 'total_expected', v_total_expected,
    'total_collected', v_total_collected, 'teacher_share', v_teacher_share,
    'collection_rate', CASE WHEN v_total_students > 0 THEN ROUND((v_paid_students::DECIMAL / v_total_students) * 100) ELSE 0 END
  );
  
  v_result := jsonb_build_object(
    'teacher', v_teacher_info, 'salary_id', v_existing_salary_id, 'status', v_existing_status,
    'summary', v_summary, 'groups', v_groups_data, 'by_grade', v_by_grade,
    'bonuses', v_bonuses, 'deductions', v_deductions, 'comparison', v_comparison, 'insights', v_insights,
    'teacher_name', v_teacher_name, 'salary_type', v_salary_type,
    'base_salary', CASE WHEN v_salary_type = 'fixed' THEN v_salary_amount ELSE 0 END,
    'sessions_total', 0,
    'percentage_total', CASE WHEN v_salary_type = 'percentage' THEN v_teacher_share ELSE 0 END,
    'gross_salary', v_teacher_share, 'net_salary', v_teacher_share
  );
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_teacher_salary_detailed(p_teacher_id uuid, p_center_id uuid, p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: get_teacher_salary_history(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_teacher_salary_history(p_teacher_id uuid) RETURNS TABLE(id uuid, month integer, year integer, net_salary numeric, status text, payment_date timestamp with time zone, payment_method text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    ts.id, 
    ts.month, 
    ts.year, 
    ts.net_salary, 
    ts.status, 
    ts.payment_date::timestamptz,
    ts.payment_method
  FROM teacher_salaries ts
  WHERE ts.teacher_id = p_teacher_id
  ORDER BY ts.year DESC, ts.month DESC;
END;
$$;


ALTER FUNCTION public.get_teacher_salary_history(p_teacher_id uuid) OWNER TO postgres;

--
-- Name: get_teacher_statistics(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_teacher_statistics(p_center_id uuid, p_teacher_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_teacher RECORD;
    v_group RECORD;
    v_teachers_data JSONB := '[]'::jsonb;
    v_groups_data JSONB;
    v_schedules_count INTEGER;
    v_students_count INTEGER;
    v_monthly_price DECIMAL(10,2);
    v_group_revenue DECIMAL(10,2);
    v_teacher_total_revenue DECIMAL(10,2);
    v_teacher_total_students INTEGER;
BEGIN
    FOR v_teacher IN
        SELECT DISTINCT
            te.teacher_id,
            u.full_name as teacher_name,
            u.phone
        FROM public.teacher_enrollments te
        JOIN public.teachers t ON t.id = te.teacher_id
        JOIN public.users u ON u.id = t.user_id
        WHERE te.center_id = p_center_id
          AND (p_teacher_id IS NULL OR te.teacher_id = p_teacher_id)
    LOOP
        v_groups_data := '[]'::jsonb;
        v_teacher_total_revenue := 0;
        v_teacher_total_students := 0;
        
        FOR v_group IN
            SELECT g.id as group_id, g.group_name, g.grade_level, g.monthly_fee,
                   c.name as course_name, c.fee as course_fee
            FROM public.groups g
            LEFT JOIN public.courses c ON c.id = g.course_id
            WHERE g.teacher_id = v_teacher.teacher_id
              AND g.center_id = p_center_id AND g.status = 'active'
        LOOP
            SELECT COUNT(*) INTO v_students_count
            FROM public.student_group_enrollments sge
            WHERE sge.group_id = v_group.group_id AND sge.status = 'active';
            
            SELECT COUNT(*) INTO v_schedules_count
            FROM public.schedules s WHERE s.group_id = v_group.group_id;
            
            SELECT cp.monthly_price INTO v_monthly_price
            FROM public.course_prices cp
            WHERE cp.center_id = p_center_id 
              AND cp.subject_name = v_group.course_name
              AND cp.is_active = true
            ORDER BY cp.grade_level NULLS LAST LIMIT 1;
            
            v_monthly_price := COALESCE(v_monthly_price, v_group.monthly_fee, v_group.course_fee, 0);
            v_group_revenue := v_monthly_price * v_students_count;
            
            v_teacher_total_revenue := v_teacher_total_revenue + v_group_revenue;
            v_teacher_total_students := v_teacher_total_students + v_students_count;
            
            v_groups_data := v_groups_data || jsonb_build_object(
                'group_id', v_group.group_id, 'group_name', v_group.group_name,
                'course_name', v_group.course_name, 'grade_level', v_group.grade_level,
                'students_count', v_students_count, 'schedules_count', v_schedules_count,
                'monthly_price', v_monthly_price, 'expected_revenue', v_group_revenue
            );
        END LOOP;
        
        v_teachers_data := v_teachers_data || jsonb_build_object(
            'teacher_id', v_teacher.teacher_id, 'teacher_name', v_teacher.teacher_name,
            'phone', v_teacher.phone, 'groups_count', jsonb_array_length(v_groups_data),
            'total_students', v_teacher_total_students, 'total_revenue', v_teacher_total_revenue,
            'groups', v_groups_data
        );
    END LOOP;
    
    RETURN json_build_object(
        'center_id', p_center_id,
        'teachers_count', jsonb_array_length(v_teachers_data),
        'teachers', v_teachers_data
    );
END;
$$;


ALTER FUNCTION public.get_teacher_statistics(p_center_id uuid, p_teacher_id uuid) OWNER TO postgres;

--
-- Name: get_teacher_statistics(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_teacher_statistics(p_center_id uuid, p_teacher_id uuid DEFAULT NULL::uuid, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_teacher RECORD;
    v_group RECORD;
    v_teachers_data JSONB := '[]'::jsonb;
    v_groups_data JSONB;
    v_schedules_count INTEGER;
    v_students_count INTEGER;
    v_monthly_price DECIMAL(10,2);
    v_expected_revenue DECIMAL(10,2);
    v_collected_revenue DECIMAL(10,2);
    v_teacher_share DECIMAL(10,2);
    v_center_share DECIMAL(10,2);
    v_teacher_total_expected DECIMAL(10,2);
    v_teacher_total_collected DECIMAL(10,2);
    v_teacher_total_students INTEGER;
    v_salary_type TEXT;
    v_salary_amount DECIMAL(10,2);
    v_current_month INTEGER := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::INTEGER);
    v_current_year INTEGER := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER);
BEGIN
    FOR v_teacher IN
        SELECT DISTINCT te.teacher_id, u.full_name as teacher_name, u.phone, te.salary_type, te.salary_amount
        FROM public.teacher_enrollments te
        JOIN public.teachers t ON t.id = te.teacher_id
        JOIN public.users u ON u.id = t.user_id
        WHERE te.center_id = p_center_id
          AND (p_teacher_id IS NULL OR te.teacher_id = p_teacher_id)
          AND te.employment_status = 'active'
    LOOP
        v_groups_data := '[]'::jsonb;
        v_teacher_total_expected := 0; v_teacher_total_collected := 0; v_teacher_total_students := 0;
        v_salary_type := COALESCE(v_teacher.salary_type, 'percentage');
        v_salary_amount := COALESCE(v_teacher.salary_amount, 0);
        
        FOR v_group IN
            SELECT g.id as group_id, g.group_name, g.grade_level, g.monthly_fee, c.name as course_name, c.fee as course_fee
            FROM public.groups g LEFT JOIN public.courses c ON c.id = g.course_id
            WHERE g.teacher_id = v_teacher.teacher_id AND g.center_id = p_center_id AND g.status = 'active'
        LOOP
            SELECT COUNT(*) INTO v_students_count FROM public.student_group_enrollments sge
            WHERE sge.group_id = v_group.group_id AND sge.status = 'active';
            
            SELECT COUNT(*) INTO v_schedules_count FROM public.schedules s WHERE s.group_id = v_group.group_id;
            
            SELECT cp.monthly_price INTO v_monthly_price FROM public.course_prices cp
            WHERE cp.center_id = p_center_id AND cp.subject_name = v_group.course_name AND cp.is_active = true
            ORDER BY cp.grade_level NULLS LAST LIMIT 1;
            
            v_monthly_price := COALESCE(v_monthly_price, v_group.monthly_fee, v_group.course_fee, 0);
            v_expected_revenue := v_monthly_price * v_students_count;
            
            -- ✅ FIX: Collected from invoice_payments
            SELECT COALESCE(SUM(ip.amount), 0) INTO v_collected_revenue
            FROM public.invoice_payments ip
            JOIN public.student_invoices si ON si.id = ip.invoice_id
            JOIN public.student_group_enrollments sge ON sge.student_id = si.student_id AND sge.group_id = v_group.group_id
            WHERE si.center_id = p_center_id AND si.month = v_current_month AND si.year = v_current_year;
            
            IF v_salary_type = 'percentage' THEN
                v_teacher_share := v_collected_revenue * (v_salary_amount / 100);
                v_center_share := v_collected_revenue - v_teacher_share;
            ELSIF v_salary_type = 'per_session' THEN
                v_teacher_share := v_schedules_count * v_salary_amount * 4;
                v_center_share := v_collected_revenue - v_teacher_share;
            ELSE
                v_teacher_share := v_salary_amount / GREATEST(jsonb_array_length(v_groups_data) + 1, 1);
                v_center_share := v_collected_revenue;
            END IF;
            
            v_teacher_total_expected := v_teacher_total_expected + v_expected_revenue;
            v_teacher_total_collected := v_teacher_total_collected + v_collected_revenue;
            v_teacher_total_students := v_teacher_total_students + v_students_count;
            
            v_groups_data := v_groups_data || jsonb_build_object(
                'group_id', v_group.group_id, 'group_name', v_group.group_name,
                'course_name', v_group.course_name, 'grade_level', v_group.grade_level,
                'students_count', v_students_count, 'schedules_count', v_schedules_count,
                'monthly_price', v_monthly_price, 'expected_revenue', v_expected_revenue,
                'collected_revenue', v_collected_revenue,
                'collection_rate', CASE WHEN v_expected_revenue > 0 THEN ROUND((v_collected_revenue / v_expected_revenue * 100)::numeric, 1) ELSE 0 END,
                'teacher_share', v_teacher_share, 'center_share', v_center_share);
        END LOOP;
        
        IF v_salary_type = 'fixed' THEN
            v_teacher_share := v_salary_amount; v_center_share := v_teacher_total_collected - v_salary_amount;
        ELSIF v_salary_type = 'percentage' THEN
            v_teacher_share := v_teacher_total_collected * (v_salary_amount / 100); v_center_share := v_teacher_total_collected - v_teacher_share;
        ELSE
            SELECT COUNT(*) * v_salary_amount * 4 INTO v_teacher_share FROM public.schedules s
            JOIN public.groups g ON g.id = s.group_id WHERE g.teacher_id = v_teacher.teacher_id AND g.center_id = p_center_id;
            v_center_share := v_teacher_total_collected - v_teacher_share;
        END IF;
        
        v_teachers_data := v_teachers_data || jsonb_build_object(
            'teacher_id', v_teacher.teacher_id, 'teacher_name', v_teacher.teacher_name, 'phone', v_teacher.phone,
            'salary_type', v_salary_type, 'salary_amount', v_salary_amount,
            'groups_count', jsonb_array_length(v_groups_data), 'total_students', v_teacher_total_students,
            'expected_revenue', v_teacher_total_expected, 'collected_revenue', v_teacher_total_collected,
            'collection_rate', CASE WHEN v_teacher_total_expected > 0 THEN ROUND((v_teacher_total_collected / v_teacher_total_expected * 100)::numeric, 1) ELSE 0 END,
            'teacher_share', v_teacher_share, 'center_share', v_center_share, 'groups', v_groups_data);
    END LOOP;
    
    RETURN json_build_object('center_id', p_center_id, 'month', v_current_month, 'year', v_current_year,
        'teachers_count', jsonb_array_length(v_teachers_data), 'teachers', v_teachers_data);
END;
$$;


ALTER FUNCTION public.get_teacher_statistics(p_center_id uuid, p_teacher_id uuid, p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: get_ticket_details(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_ticket_details(p_ticket_id uuid) RETURNS TABLE(ticket_id uuid, subject text, status text, priority text, category text, created_at timestamp with time zone, messages jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_center_id UUID;
  v_user_center_id UUID;
BEGIN
  -- Security check: ensure user belongs to the ticket's center
  SELECT center_id INTO v_center_id FROM support_tickets WHERE id = p_ticket_id;
  
  -- Get user's center (simplified for single center admins)
  SELECT id INTO v_user_center_id FROM centers WHERE admin_user_id = auth.uid();
  
  -- Allow if user is admin of the center
  IF v_center_id != v_user_center_id AND v_user_center_id IS NOT NULL THEN
     -- Check if teacher belongs to center (optional, for now strict admin/owner only or expanded later)
     -- For now we assume RLS handles basic visibility, but RPC needs explicit check or use VIEW
     NULL; 
  END IF;

  RETURN QUERY
  SELECT 
    t.id,
    t.subject,
    t.status,
    t.priority,
    t.category,
    t.created_at,
    (
      SELECT jsonb_agg(jsonb_build_object(
        'id', m.id,
        'message', m.message,
        'sender_id', m.sender_id,
        'is_admin_reply', m.is_admin_reply,
        'created_at', m.created_at,
        'sender_name', (SELECT full_name FROM users u WHERE u.id = m.sender_id)
      ) ORDER BY m.created_at ASC)
      FROM support_messages m
      WHERE m.ticket_id = t.id
    ) as messages
  FROM support_tickets t
  WHERE t.id = p_ticket_id;
END;
$$;


ALTER FUNCTION public.get_ticket_details(p_ticket_id uuid) OWNER TO postgres;

--
-- Name: get_unpaid_months(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unpaid_months(p_student_id uuid) RETURNS TABLE(group_id uuid, group_name text, subject_name text, month_date date, monthly_fee numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_start_date DATE := DATE_TRUNC('month', NOW()) - INTERVAL '2 months';
BEGIN
  RETURN QUERY
  WITH student_groups AS (
    SELECT sg.group_id, g.group_name, c.name as s_name, g.monthly_fee
    FROM student_group_enrollments sg
    JOIN groups g ON sg.group_id = g.id
    JOIN courses c ON g.course_id = c.id
    WHERE sg.student_id = p_student_id AND sg.status = 'active'
  ),
  required_months AS (
    SELECT generate_series(v_start_date, DATE_TRUNC('month', NOW()), '1 month')::DATE as m_date
  )
  SELECT 
    sg.group_id,
    sg.group_name,
    sg.s_name,
    rm.m_date,
    COALESCE(sg.monthly_fee, 0)
  FROM student_groups sg
  CROSS JOIN required_months rm
  WHERE NOT EXISTS (
    SELECT 1 FROM invoice_payments ip
    JOIN student_invoices si ON ip.invoice_id = si.id
    WHERE si.student_id = p_student_id
      AND si.month = EXTRACT(MONTH FROM rm.m_date)::INTEGER
      AND si.year = EXTRACT(YEAR FROM rm.m_date)::INTEGER
  )
  ORDER BY rm.m_date DESC;
END;
$$;


ALTER FUNCTION public.get_unpaid_months(p_student_id uuid) OWNER TO postgres;

--
-- Name: get_unpaid_sessions(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unpaid_sessions(p_student_id uuid) RETURNS TABLE(session_id uuid, subject_id uuid, subject_name text, teacher_id uuid, teacher_name text, session_date timestamp with time zone, price numeric, attendance_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    s.id AS session_id,
    sub.id AS subject_id,
    sub.name AS subject_name,
    u.id AS teacher_id,
    u.name AS teacher_name,
    s.start_time AS session_date,
    COALESCE(g.session_price, 0) AS price,
    a.status::text
  FROM attendance a
  JOIN sessions s ON a.session_id = s.id
  JOIN groups g ON s.group_id = g.id
  JOIN courses sub ON g.course_id = sub.id
  LEFT JOIN users u ON g.teacher_id = u.id
  WHERE a.student_id = p_student_id
    AND a.status IN ('present', 'late')
    AND NOT EXISTS (
      SELECT 1 FROM invoice_payments ip
      JOIN student_invoices si ON ip.invoice_id = si.id
      WHERE si.student_id = p_student_id
        AND si.month = EXTRACT(MONTH FROM s.start_time)::INTEGER
        AND si.year = EXTRACT(YEAR FROM s.start_time)::INTEGER
    )
  ORDER BY s.start_time DESC;
END;
$$;


ALTER FUNCTION public.get_unpaid_sessions(p_student_id uuid) OWNER TO postgres;

--
-- Name: get_unread_notifications_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unread_notifications_count() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_center_id UUID;
  v_count INT;
BEGIN
  SELECT cu.center_id INTO v_center_id
  FROM center_users cu
  WHERE cu.user_id = auth.uid()
  LIMIT 1;
  
  SELECT COUNT(*) INTO v_count
  FROM notifications
  WHERE center_id = v_center_id
    AND is_read = false;
    
  RETURN v_count;
END;
$$;


ALTER FUNCTION public.get_unread_notifications_count() OWNER TO postgres;

--
-- Name: get_user_center_id(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_center_id(user_uuid uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    center_uuid UUID;
BEGIN
    -- First try: Check users table (default_center_id)
    SELECT default_center_id INTO center_uuid
    FROM public.users
    WHERE id = user_uuid
    AND default_center_id IS NOT NULL;
    
    IF center_uuid IS NOT NULL THEN
        RETURN center_uuid;
    END IF;
    
    -- Second try: Check last_selected_center_id
    SELECT last_selected_center_id INTO center_uuid
    FROM public.users
    WHERE id = user_uuid
    AND last_selected_center_id IS NOT NULL;
    
    IF center_uuid IS NOT NULL THEN
        RETURN center_uuid;
    END IF;
    
    -- Third try: Check user_centers table
    SELECT center_id INTO center_uuid
    FROM public.user_centers
    WHERE user_id = user_uuid
    AND is_primary = true
    LIMIT 1;
    
    IF center_uuid IS NOT NULL THEN
        RETURN center_uuid;
    END IF;
    
    -- Fourth try: Check if user is admin of a center
    SELECT id INTO center_uuid
    FROM public.centers
    WHERE admin_user_id = user_uuid
    AND deleted_at IS NULL
    LIMIT 1;
    
    RETURN center_uuid;
END;
$$;


ALTER FUNCTION public.get_user_center_id(user_uuid uuid) OWNER TO postgres;

