--
-- Name: get_user_notifications(uuid, integer, integer, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_notifications(p_recipient_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_center_id uuid DEFAULT NULL::uuid, p_unread_only boolean DEFAULT false) RETURNS TABLE(id uuid, title text, body text, category text, priority text, read_status boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        n.id,
        n.title,
        n.body,
        n.category,
        n.priority,
        n.read_status,
        n.created_at
    FROM public.notifications n
    WHERE n.recipient_id = p_recipient_id
    AND (p_center_id IS NULL OR n.center_id = p_center_id)
    AND (p_unread_only = FALSE OR n.read_status = FALSE)
    AND (n.expires_at IS NULL OR n.expires_at > NOW())
    ORDER BY 
        CASE n.priority
            WHEN 'urgent' THEN 1
            WHEN 'high' THEN 2
            WHEN 'normal' THEN 3
            WHEN 'low' THEN 4
            ELSE 5
        END,
        n.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;
EXCEPTION WHEN others THEN
    RAISE NOTICE 'خطأ في الحصول على الإشعارات: %', SQLERRM;
    RETURN;
END;
$$;


ALTER FUNCTION public.get_user_notifications(p_recipient_id uuid, p_limit integer, p_offset integer, p_center_id uuid, p_unread_only boolean) OWNER TO postgres;

--
-- Name: get_weekly_schedule(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_weekly_schedule(p_center_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_result JSON;
BEGIN
  SELECT json_agg(t) INTO v_result
  FROM (
    SELECT 
      s.id,
      s.course_id,
      s.teacher_id,
      s.classroom_id,
      s.day_of_week,
      s.start_time,
      s.end_time,
      s.status,
      s.grade_level,
      c.name as course_name,
      -- Use a subquery or join to get teacher name, assuming teachers checks users or teacher_enrollments
      -- Based on error logs, teachers might be linked differently. 
      -- Let's try simple join for now but careful with column names.
      u.full_name as teacher_name, 
      r.name as room_name
    FROM schedules s
    LEFT JOIN courses c ON s.course_id = c.id
    LEFT JOIN classrooms r ON s.classroom_id = r.id
    -- Teachers join: schedules.teacher_id -> teachers.id (or teacher_enrollments.teacher_id)
    -- Assuming teacher_id is reliable.
    LEFT JOIN teachers t ON s.teacher_id = t.id
    LEFT JOIN users u ON t.user_id = u.id
    WHERE s.center_id = p_center_id
      AND s.deleted_at IS NULL
    ORDER BY s.day_of_week ASC, s.start_time ASC
  ) t;

  RETURN COALESCE(v_result, '[]'::json);
END;
$$;


ALTER FUNCTION public.get_weekly_schedule(p_center_id uuid) OWNER TO postgres;

--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    new_center_id UUID;
    user_full_name TEXT;
    user_phone TEXT;
    user_role TEXT;
BEGIN
    -- استخراج البيانات من metadata
    user_full_name := COALESCE(NEW.raw_user_meta_data->>'full_name', 'مستخدم جديد');
    user_phone := NEW.raw_user_meta_data->>'phone';
    user_role := COALESCE(
        NEW.raw_user_meta_data->>'role',
        NEW.raw_user_meta_data->>'user_type',
        'student'
    );

    -- إذا كان المستخدم center_admin، أنشئ سنتر له
    IF user_role = 'center_admin' THEN
        -- إنشاء السنتر
        INSERT INTO public.centers (
            admin_user_id,
            name
        ) VALUES (
            NEW.id,
            user_full_name || ' - مركز'
        ) RETURNING id INTO new_center_id;

        -- تحديث metadata بـ center_id
        UPDATE auth.users
        SET raw_user_meta_data = raw_user_meta_data || 
            jsonb_build_object(
                'center_id', new_center_id,
                'default_center_id', new_center_id
            )
        WHERE id = NEW.id;

        -- إنشاء السجل في users table
        INSERT INTO public.users (
            id,
            full_name,
            phone,
            role,
            default_center_id,
            last_selected_center_id
        ) VALUES (
            NEW.id,
            user_full_name,
            user_phone,
            user_role,
            new_center_id,
            new_center_id
        );

        -- إنشاء السجل في user_centers
        INSERT INTO public.user_centers (
            user_id,
            center_id,
            is_primary
        ) VALUES (
            NEW.id,
            new_center_id,
            true
        );

    ELSE
        -- للمستخدمين العاديين (students, teachers)
        INSERT INTO public.users (
            id,
            full_name,
            phone,
            role
        ) VALUES (
            NEW.id,
            user_full_name,
            user_phone,
            user_role
        );
    END IF;

    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    -- Log the error but don't fail the trigger
    RAISE WARNING 'Error in handle_new_user: %', SQLERRM;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.handle_new_user() OWNER TO postgres;

--
-- Name: handle_new_user_registration(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_user_registration() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_center_id UUID;
  v_role TEXT;
  v_center_name TEXT;
  v_full_name TEXT;
  v_phone TEXT;
BEGIN
  -- الحصول على البيانات من metadata مع قيم افتراضية آمنة
  v_role := COALESCE(NEW.raw_user_meta_data->>'role', 'student');
  v_full_name := COALESCE(
    NULLIF(TRIM(NEW.raw_user_meta_data->>'full_name'), ''),
    split_part(NEW.email, '@', 1),
    'مستخدم جديد'
  );
  v_phone := NEW.raw_user_meta_data->>'phone';
  
  -- ═══════════════════════════════════════════════════════════════
  -- معالجة center_admin
  -- ═══════════════════════════════════════════════════════════════
  IF v_role = 'center_admin' THEN
    -- البحث عن سنتر موجود
    SELECT id INTO v_center_id
    FROM public.centers
    WHERE admin_user_id = NEW.id
    LIMIT 1;
    
    -- إنشاء سنتر جديد إذا لم يكن موجوداً
    IF v_center_id IS NULL THEN
      v_center_name := COALESCE(
        NULLIF(TRIM(NEW.raw_user_meta_data->>'center_name'), ''),
        v_full_name || ' - مركز'
      );
      
      INSERT INTO public.centers (
        name, 
        admin_user_id, 
        email, 
        phone,
        subscription_plan, 
        is_active, 
        created_at, 
        updated_at
      ) VALUES (
        v_center_name, 
        NEW.id, 
        NEW.email,
        v_phone,
        'basic', 
        true, 
        NOW(), 
        NOW()
      ) RETURNING id INTO v_center_id;
    END IF;
  END IF;
  
  -- ═══════════════════════════════════════════════════════════════
  -- إنشاء/تحديث المستخدم في public.users
  -- ═══════════════════════════════════════════════════════════════
  INSERT INTO public.users (
    id,
    full_name,
    email,
    phone,
    role,
    default_center_id,
    is_active,
    created_at,
    updated_at
  ) VALUES (
    NEW.id,
    v_full_name,
    NEW.email,
    v_phone,
    v_role,
    v_center_id,
    true,
    NOW(),
    NOW()
  )
  ON CONFLICT (id) DO UPDATE SET
    full_name = COALESCE(EXCLUDED.full_name, users.full_name),
    email = COALESCE(EXCLUDED.email, users.email),
    phone = COALESCE(EXCLUDED.phone, users.phone),
    default_center_id = COALESCE(EXCLUDED.default_center_id, users.default_center_id),
    updated_at = NOW();
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.handle_new_user_registration() OWNER TO postgres;

--
-- Name: FUNCTION handle_new_user_registration(); Type: COMMENT; Schema: public; Owner: postgres
--

