--
-- Name: has_permission(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.has_permission(p_center_id uuid, p_permission text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_role_code TEXT;
    v_has_perm BOOLEAN;
BEGIN
    SELECT ar.code INTO v_role_code
    FROM public.user_roles ur
    JOIN public.app_roles ar ON ur.role_id = ar.id
    WHERE ur.user_id = auth.uid()
      AND ur.center_id = p_center_id
      AND ur.is_active = TRUE;
    
    -- Owner has all permissions
    IF v_role_code = 'owner' THEN
        RETURN TRUE;
    END IF;
    
    -- Check specific permission
    SELECT EXISTS (
        SELECT 1
        FROM public.user_roles ur
        JOIN public.role_permissions rp ON rp.role_id = ur.role_id
        WHERE ur.user_id = auth.uid()
          AND ur.center_id = p_center_id
          AND ur.is_active = TRUE
          AND rp.permission_code = p_permission
    ) INTO v_has_perm;
    
    RETURN v_has_perm;
END;
$$;


ALTER FUNCTION public.has_permission(p_center_id uuid, p_permission text) OWNER TO postgres;

--
-- Name: health_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.health_check() RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSON;
BEGIN
    SELECT json_build_object(
        'database_size', pg_size_pretty(pg_database_size(current_database())),
        'total_tables', (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = 'public'),
        'total_indexes', (SELECT COUNT(*) FROM pg_indexes WHERE schemaname = 'public'),
        'total_functions', (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema = 'public'),
        'active_connections', (SELECT COUNT(*) FROM pg_stat_activity WHERE datname = current_database()),
        'cache_hit_ratio', (
            SELECT ROUND((sum(blks_hit) / NULLIF(sum(blks_hit) + sum(blks_read), 0)) * 100, 2)
            FROM pg_stat_database 
            WHERE datname = current_database()
        ),
        'largest_tables', (
            SELECT json_agg(json_build_object(
                'table_name', tablename,
                'size', pg_size_pretty(pg_total_relation_size(schemaname||'.'||tablename))
            ))
            FROM (
                SELECT schemaname, tablename
                FROM pg_tables
                WHERE schemaname = 'public'
                ORDER BY pg_total_relation_size(schemaname||'.'||tablename) DESC
                LIMIT 5
            ) t
        ),
        'slow_queries_count', (
            SELECT COUNT(*) 
            FROM pg_stat_statements 
            WHERE mean_exec_time > 1000
        ),
        'last_vacuum', (
            SELECT MAX(last_vacuum)
            FROM pg_stat_user_tables
        ),
        'timestamp', NOW()
    )
    INTO result;
    
    RETURN result;
END;
$$;


ALTER FUNCTION public.health_check() OWNER TO postgres;

--
-- Name: FUNCTION health_check(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.health_check() IS 'فحص صحة قاعدة البيانات الشامل';


--
-- Name: increment_download_count(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.increment_download_count(p_material_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_exists BOOLEAN;
BEGIN
  -- Check if view already recorded
  SELECT EXISTS (
    SELECT 1 FROM public.material_views 
    WHERE student_user_id = v_user_id AND material_id = p_material_id
  ) INTO v_exists;

  IF NOT v_exists THEN
    -- Insert view record
    INSERT INTO public.material_views (student_user_id, material_id)
    VALUES (v_user_id, p_material_id);

    -- Increment count
    UPDATE public.study_materials
    SET download_count = download_count + 1
    WHERE id = p_material_id;
  END IF;
END;
$$;


ALTER FUNCTION public.increment_download_count(p_material_id uuid) OWNER TO postgres;

--
-- Name: init_center_roles(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.init_center_roles(p_center_id uuid, p_owner_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_owner_role_id UUID;
    v_manager_role_id UUID;
    v_accountant_role_id UUID;
BEGIN
    -- Create Owner role
    INSERT INTO public.app_roles (center_id, code, name_ar, name_en, description, is_system)
    VALUES (p_center_id, 'owner', 'المالك', 'Owner', 'كل الصلاحيات', TRUE)
    ON CONFLICT (center_id, code) DO UPDATE SET name_ar = 'المالك', name_en = 'Owner'
    RETURNING id INTO v_owner_role_id;
    
    -- Create Manager role
    INSERT INTO public.app_roles (center_id, code, name_ar, name_en, description, is_system)
    VALUES (p_center_id, 'manager', 'المدير', 'Manager', 'إدارة كاملة', TRUE)
    ON CONFLICT (center_id, code) DO UPDATE SET name_ar = 'المدير', name_en = 'Manager'
    RETURNING id INTO v_manager_role_id;
    
    -- Create Accountant role
    INSERT INTO public.app_roles (center_id, code, name_ar, name_en, description, is_system)
    VALUES (p_center_id, 'accountant', 'المحاسب', 'Accountant', 'العمليات المالية', TRUE)
    ON CONFLICT (center_id, code) DO UPDATE SET name_ar = 'المحاسب', name_en = 'Accountant'
    RETURNING id INTO v_accountant_role_id;
    
    -- Assign permissions to manager
    INSERT INTO public.role_permissions (role_id, permission_code)
    SELECT v_manager_role_id, code FROM public.permissions
    WHERE code != 'roles.manage'
    ON CONFLICT DO NOTHING;
    
    -- Assign permissions to accountant
    INSERT INTO public.role_permissions (role_id, permission_code)
    SELECT v_accountant_role_id, code FROM public.permissions
    WHERE category IN ('payments', 'reports') OR code = 'students.view'
    ON CONFLICT DO NOTHING;
END;
$$;


ALTER FUNCTION public.init_center_roles(p_center_id uuid, p_owner_id uuid) OWNER TO postgres;

