--
-- Name: join_center_by_code(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.join_center_by_code(input_invitation_code text, input_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_id UUID;
  v_student_id UUID;
  v_center_id UUID;
  v_center_name TEXT;
  v_existing_enrollment RECORD;
  v_new_invitation_code TEXT;
BEGIN
  -- 1. Identify Student & User
  SELECT s.id, s.user_id INTO v_student_id, v_user_id
  FROM public.students s
  WHERE s.id = input_student_id OR s.user_id = input_student_id
  LIMIT 1;
  
  IF v_student_id IS NULL THEN
    v_student_id := input_student_id;
    v_user_id := input_student_id;
  END IF;

  -- 2. Find Center logic
  -- Attempt A: Is the code a valid Center ID?
  BEGIN
    SELECT id, name INTO v_center_id, v_center_name
    FROM public.centers
    WHERE id = input_invitation_code::UUID AND is_active = true
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_center_id := NULL;
  END;

  -- Attempt B: Is the code an existing invitation code from ANY enrollment?
  IF v_center_id IS NULL THEN
    SELECT c.id, c.name INTO v_center_id, v_center_name
    FROM public.student_enrollments se
    JOIN public.centers c ON se.center_id = c.id
    WHERE UPPER(se.invitation_code) = UPPER(TRIM(input_invitation_code))
    AND c.is_active = true
    LIMIT 1;
  END IF;

  -- If still NULL, invalid code
  IF v_center_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'كود الدعوة غير صحيح أو غير موجود'
    );
  END IF;

  -- 3. Check if THIS student is ALREADY enrolled in this center
  -- Using student_user_id as primary check since the unique index is on (student_user_id, center_id)
  SELECT se.id, se.status, se.deleted_at INTO v_existing_enrollment
  FROM public.student_enrollments se
  WHERE (se.student_user_id = v_user_id OR se.student_id = v_student_id)
    AND se.center_id = v_center_id
  LIMIT 1;

  IF v_existing_enrollment IS NOT NULL THEN
     IF v_existing_enrollment.deleted_at IS NOT NULL THEN
        -- Reactivate
        UPDATE public.student_enrollments 
        SET deleted_at = NULL, status = 'accepted'
        WHERE id = v_existing_enrollment.id;
        
        RETURN jsonb_build_object(
          'success', true,
          'message', 'تم إعادة تفعيل انضمامك للسنتر بنجاح!',
          'center_name', v_center_name,
          'center_id', v_center_id
        );
     ELSE
        -- Already active
        RETURN jsonb_build_object(
          'success', true,
          'message', 'أنت بالفعل عضو في هذا السنتر!',
          'center_name', v_center_name,
          'center_id', v_center_id
        );
     END IF;
  END IF;

  -- 4. Generate Unique Invitation Code for New Enrollment
  v_new_invitation_code := UPPER(SUBSTRING(MD5(RANDOM()::TEXT || CLOCK_TIMESTAMP()::TEXT) FROM 1 FOR 8));
  
  -- Ensure uniqueness (simple retry loop)
  WHILE EXISTS (SELECT 1 FROM public.student_enrollments WHERE invitation_code = v_new_invitation_code) LOOP
    v_new_invitation_code := UPPER(SUBSTRING(MD5(RANDOM()::TEXT || CLOCK_TIMESTAMP()::TEXT) FROM 1 FOR 8));
  END LOOP;

  -- 5. Create New Enrollment
  BEGIN
    INSERT INTO public.student_enrollments (
      student_user_id,
      student_id,
      center_id,
      invitation_code,
      status,
      enrolled_at
    ) VALUES (
      v_user_id,
      v_student_id,
      v_center_id,
      v_new_invitation_code, -- Use NEW unique code
      'accepted',
      NOW()
    );
  EXCEPTION WHEN unique_violation THEN
     -- Catch race condition where enrollment was created just now
     RETURN jsonb_build_object(
          'success', true,
          'message', 'أنت بالفعل عضو في هذا السنتر!',
          'center_name', v_center_name,
          'center_id', v_center_id
     );
  END;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', 'تم الانضمام للسنتر بنجاح!',
    'center_name', v_center_name,
    'center_id', v_center_id
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM
  );
END;
$$;


ALTER FUNCTION public.join_center_by_code(input_invitation_code text, input_student_id uuid) OWNER TO postgres;

--
-- Name: link_parent_to_child(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.link_parent_to_child(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_enrollment RECORD;
    v_user_id UUID;
    v_parent_id UUID;
    v_student_name TEXT;
    v_already_linked BOOLEAN;
BEGIN
    v_user_id := auth.uid();
    
    IF v_user_id IS NULL THEN
        RETURN '{"success": false, "error": "يجب تسجيل الدخول أولاً"}'::JSONB;
    END IF;
    
    -- البحث بكود ولي الأمر
    SELECT se.*, s.full_name as sname, c.name as cname
    INTO v_enrollment
    FROM public.student_enrollments se
    LEFT JOIN public.students s ON se.student_id = s.id
    LEFT JOIN public.centers c ON se.center_id = c.id
    WHERE UPPER(se.parent_invitation_code) = UPPER(p_code);
    
    IF v_enrollment IS NULL THEN
        RETURN '{"success": false, "error": "كود الدعوة غير صحيح"}'::JSONB;
    END IF;
    
    v_student_name := COALESCE(v_enrollment.sname, 'الطالب');
    
    -- تحديث role المستخدم
    UPDATE public.users SET role = 'parent', updated_at = NOW()
    WHERE id = v_user_id;
    
    -- إنشاء سجل ولي الأمر
    INSERT INTO public.parents (user_id, full_name, phone)
    SELECT v_user_id, full_name, phone FROM public.users WHERE id = v_user_id
    ON CONFLICT (user_id) DO NOTHING;
    
    SELECT id INTO v_parent_id FROM public.parents WHERE user_id = v_user_id;
    
    -- التحقق هل مرتبط مسبقاً
    SELECT EXISTS(
        SELECT 1 FROM public.student_parents 
        WHERE parent_id = v_parent_id 
        AND student_user_id = COALESCE(v_enrollment.student_user_id, v_enrollment.student_id)
    ) INTO v_already_linked;
    
    IF v_already_linked THEN
        RETURN jsonb_build_object(
            'success', true,
            'already_linked', true,
            'message', 'هذا الطالب مرتبط بحسابك بالفعل',
            'student_name', v_student_name
        );
    END IF;
    
    -- ربط ولي الأمر بالطالب
    INSERT INTO public.student_parents (student_user_id, parent_id, relationship, is_primary)
    VALUES (
        COALESCE(v_enrollment.student_user_id, v_enrollment.student_id),
        v_parent_id,
        'guardian',
        (SELECT COUNT(*) = 0 FROM public.student_parents WHERE parent_id = v_parent_id)
    )
    ON CONFLICT DO NOTHING;
    
    -- تحديث حالة الكود
    UPDATE public.student_enrollments
    SET parent_code_status = 'claimed',
        parent_code_claimed_by = v_user_id,
        parent_code_claimed_at = NOW()
    WHERE id = v_enrollment.id;
    
    RETURN jsonb_build_object(
        'success', true,
        'message', 'تم ربط حسابك بـ ' || v_student_name || ' بنجاح!',
        'student_name', v_student_name,
        'center_id', v_enrollment.center_id,
        'center_name', v_enrollment.cname
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION public.link_parent_to_child(p_code text) OWNER TO postgres;

--
-- Name: log_activity(text, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_activity(p_action text, p_entity_type text, p_entity_id uuid DEFAULT NULL::uuid, p_entity_name text DEFAULT NULL::text, p_details jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_center_id UUID;
    v_user_name TEXT;
    v_log_id UUID;
BEGIN
    -- Get user's center
    SELECT default_center_id INTO v_center_id
    FROM public.users
    WHERE id = auth.uid();
    
    -- Get user's name
    SELECT full_name INTO v_user_name
    FROM public.users
    WHERE id = auth.uid();
    
    INSERT INTO public.activity_logs (
        center_id, user_id, user_name, action, 
        entity_type, entity_id, entity_name, details
    ) VALUES (
        v_center_id, auth.uid(), v_user_name, p_action,
        p_entity_type, p_entity_id, p_entity_name, p_details
    ) RETURNING id INTO v_log_id;
    
    RETURN v_log_id;
END;
$$;


ALTER FUNCTION public.log_activity(p_action text, p_entity_type text, p_entity_id uuid, p_entity_name text, p_details jsonb) OWNER TO postgres;

--
-- Name: log_important_changes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_important_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    center_id_val UUID;
BEGIN
    -- محاولة الحصول على center_id
    BEGIN
        IF TG_OP = 'DELETE' THEN
            center_id_val := OLD.center_id;
        ELSE
            center_id_val := NEW.center_id;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        center_id_val := NULL;
    END;
    
    -- تسجيل التغيير
    IF TG_OP = 'DELETE' THEN
        INSERT INTO audit_log (
            user_id,
            center_id,
            table_name,
            action,
            old_data,
            created_at
        ) VALUES (
            auth.uid(),
            center_id_val,
            TG_TABLE_NAME,
            'DELETE',
            row_to_json(OLD),
            NOW()
        );
        RETURN OLD;
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO audit_log (
            user_id,
            center_id,
            table_name,
            action,
            old_data,
            new_data,
            created_at
        ) VALUES (
            auth.uid(),
            center_id_val,
            TG_TABLE_NAME,
            'UPDATE',
            row_to_json(OLD),
            row_to_json(NEW),
            NOW()
        );
        RETURN NEW;
    ELSIF TG_OP = 'INSERT' THEN
        INSERT INTO audit_log (
            user_id,
            center_id,
            table_name,
            action,
            new_data,
            created_at
        ) VALUES (
            auth.uid(),
            center_id_val,
            TG_TABLE_NAME,
            'INSERT',
            row_to_json(NEW),
            NOW()
        );
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION public.log_important_changes() OWNER TO postgres;

--
-- Name: FUNCTION log_important_changes(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.log_important_changes() IS 'تسجيل التغييرات المهمة في audit_log';


