CREATE FUNCTION public.mark_all_notifications_read() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_center_id UUID;
BEGIN
  SELECT cu.center_id INTO v_center_id
  FROM center_users cu
  WHERE cu.user_id = auth.uid()
  LIMIT 1;
  
  UPDATE notifications
  SET is_read = true
  WHERE center_id = v_center_id
    AND is_read = false;
END;
$$;


