--
-- Name: mark_attendance_by_qr(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_attendance_by_qr(p_session_token text, p_student_id uuid) RETURNS TABLE(success boolean, message text, student_name text, group_name text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_session RECORD;
  v_student_name TEXT;
  v_group_name TEXT;
  v_is_enrolled BOOLEAN;
  v_already_marked BOOLEAN;
BEGIN
  -- Find the session
  SELECT * INTO v_session
  FROM attendance_sessions
  WHERE session_token = p_session_token;
  
  -- Session not found
  IF v_session IS NULL THEN
    RETURN QUERY SELECT false, 'رمز QR غير صالح'::TEXT, NULL::TEXT, NULL::TEXT;
    RETURN;
  END IF;
  
  -- Session expired
  IF v_session.expires_at < NOW() THEN
    RETURN QUERY SELECT false, 'انتهت صلاحية جلسة الحضور'::TEXT, NULL::TEXT, NULL::TEXT;
    RETURN;
  END IF;
  
  -- Session not active
  IF v_session.status != 'active' THEN
    RETURN QUERY SELECT false, 'جلسة الحضور غير نشطة'::TEXT, NULL::TEXT, NULL::TEXT;
    RETURN;
  END IF;
  
  -- Get group name
  SELECT g.group_name INTO v_group_name
  FROM groups g WHERE g.id = v_session.group_id;
  
  -- Get student name
  SELECT s.full_name INTO v_student_name
  FROM students s WHERE s.id = p_student_id;
  
  IF v_student_name IS NULL THEN
    RETURN QUERY SELECT false, 'الطالب غير موجود'::TEXT, NULL::TEXT, NULL::TEXT;
    RETURN;
  END IF;
  
  -- Check if student is enrolled in the group
  SELECT EXISTS(
    SELECT 1 FROM student_group_enrollments gs
    WHERE gs.group_id = v_session.group_id
      AND gs.student_id = p_student_id
  ) INTO v_is_enrolled;
  
  IF NOT v_is_enrolled THEN
    RETURN QUERY SELECT false, 'الطالب غير مسجل في هذه المجموعة'::TEXT, v_student_name, v_group_name;
    RETURN;
  END IF;
  
  -- Check if already marked
  SELECT EXISTS(
    SELECT 1 FROM attendance
    WHERE group_id = v_session.group_id
      AND student_id = p_student_id
      AND date = v_session.session_date
  ) INTO v_already_marked;
  
  IF v_already_marked THEN
    RETURN QUERY SELECT true, 'تم تسجيل الحضور مسبقاً'::TEXT, v_student_name, v_group_name;
    RETURN;
  END IF;
  
  -- Mark attendance
  INSERT INTO attendance (
    center_id, group_id, student_id, date, status, check_in_time
  ) VALUES (
    v_session.center_id, v_session.group_id, p_student_id, 
    v_session.session_date, 'present', NOW()
  );
  
  RETURN QUERY SELECT true, 'تم تسجيل الحضور بنجاح ✅'::TEXT, v_student_name, v_group_name;
END;
$$;


ALTER FUNCTION public.mark_attendance_by_qr(p_session_token text, p_student_id uuid) OWNER TO postgres;

--
-- Name: mark_messages_read(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_messages_read(p_conversation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_is_student BOOLEAN;
BEGIN
    SELECT (student_id = auth.uid()) INTO v_is_student
    FROM public.conversations
    WHERE id = p_conversation_id;

    -- Update unread count
    IF v_is_student THEN
        UPDATE public.conversations
        SET unread_count_student = 0
        WHERE id = p_conversation_id;
    ELSE
        UPDATE public.conversations
        SET unread_count_teacher = 0
        WHERE id = p_conversation_id;
    END IF;

    -- Update messages status (optional, for granular status)
    UPDATE public.messages
    SET is_read = true
    WHERE conversation_id = p_conversation_id
    AND sender_id != auth.uid()
    AND is_read = false;
END;
$$;


ALTER FUNCTION public.mark_messages_read(p_conversation_id uuid) OWNER TO postgres;

--
