    SET 
        read_status = TRUE,
        read_at = NOW(),
        updated_at = NOW()
    WHERE id = p_notification_id;
EXCEPTION WHEN others THEN
    RAISE NOTICE 'خطأ في تحديث الإشعار: %', SQLERRM;
END;
$$;


