--
-- Name: match_book_chunks(public.vector, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.match_book_chunks(query_embedding public.vector, match_center_id uuid, match_subject text, match_count integer DEFAULT 5) RETURNS TABLE(id uuid, content text, page_number integer, book_name text, similarity double precision)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    id,
    content,
    page_number,
    book_name,
    1 - (embedding <=> query_embedding) AS similarity
  FROM book_chunks
  WHERE
    center_id = match_center_id
    AND subject = match_subject
  ORDER BY embedding <=> query_embedding
  LIMIT match_count;
$$;


ALTER FUNCTION public.match_book_chunks(query_embedding public.vector, match_center_id uuid, match_subject text, match_count integer) OWNER TO postgres;

--
-- Name: notify_new_enrollment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_new_enrollment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_student_name TEXT;
  v_group_name TEXT;
BEGIN
  -- Get student name from users table (full_name, not name)
  SELECT u.full_name INTO v_student_name
  FROM students s
  JOIN users u ON s.user_id = u.id
  WHERE s.id = NEW.student_id;
  
  -- If not found, try from students table directly
  IF v_student_name IS NULL THEN
    SELECT full_name INTO v_student_name
    FROM students
    WHERE id = NEW.student_id;
  END IF;
  
  -- Get group name
  SELECT group_name INTO v_group_name
  FROM groups
  WHERE id = NEW.group_id;
  
  -- You can add notification logic here if needed
  -- For now, just return the new row
  
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- If any error, just continue without notification
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.notify_new_enrollment() OWNER TO postgres;

--
-- Name: notify_salary_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_salary_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_teacher_user_id UUID;
    v_teacher_name TEXT;
    v_center_id UUID;
BEGIN
    v_center_id := NEW.center_id;
    
    -- Get Teacher User ID - استخدام full_name بدلاً من name
    SELECT u.id, u.full_name INTO v_teacher_user_id, v_teacher_name
    FROM teachers t
    JOIN users u ON t.user_id = u.id
    WHERE t.id = NEW.teacher_id;

    -- الافتراضي إذا لم يُعثر على الاسم
    v_teacher_name := COALESCE(v_teacher_name, 'معلم');

    -- Case 1: Salary Calculated (Pending) -> Notify Admin
    IF NEW.status = 'pending' AND (OLD.status IS NULL OR OLD.status != 'pending') THEN
        -- Only notify if send_notification function exists
        BEGIN
            PERFORM send_notification(
                (SELECT admin_user_id FROM centers WHERE id = v_center_id),
                '💰 راتب مستحق: ' || v_teacher_name,
                'تم احتساب راتب شهر ' || NEW.month || '/' || NEW.year || ' للمعلم ' || v_teacher_name || '. القيمة: ' || NEW.net_salary,
                'salary_review',
                json_build_object('salary_id', NEW.id)
            );
        EXCEPTION WHEN undefined_function THEN
            -- send_notification doesn't exist, skip
            NULL;
        END;
    END IF;

    -- Case 2: Salary Paid -> Notify Teacher
    IF NEW.status = 'paid' AND (OLD IS NULL OR OLD.status != 'paid') THEN
        IF v_teacher_user_id IS NOT NULL THEN
            BEGIN
                PERFORM send_notification(
                    v_teacher_user_id,
                    '✅ تم تحويل الراتب',
                    'تم صرف راتب شهر ' || NEW.month || '/' || NEW.year || '. شكراً لجهودك معنا!',
                    'salary_details',
                    json_build_object('salary_id', NEW.id)
                );
            EXCEPTION WHEN undefined_function THEN
                NULL;
            END;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.notify_salary_update() OWNER TO postgres;

--
-- Name: on_course_price_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.on_course_price_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_item RECORD;
  v_new_price DECIMAL(10, 2);
  v_affected_count INT := 0;
BEGIN
  -- Only care if price amount changed
  IF OLD.monthly_price = NEW.monthly_price AND OLD.session_price = NEW.session_price THEN
    RETURN NEW;
  END IF;

  RAISE NOTICE '🧠 Reactive Pricing: Price for % changed. Updating pending invoices...', NEW.subject_name;

  -- Iterate over all PENDING invoice items for this subject
  -- We match by course_name = subject_name
  FOR v_item IN 
    SELECT ii.id, ii.invoice_id, ii.course_name, ii.teacher_id, ii.grade_level, ii.amount
    FROM invoice_items ii
    JOIN student_invoices si ON ii.invoice_id = si.id
    WHERE si.status = 'pending' -- Only update unpaid invoices
      AND ii.course_name = NEW.subject_name -- Correct Column Reference
  LOOP
    -- Re-evaluate price for this specific item context
    SELECT monthly_price INTO v_new_price
    FROM get_smart_price(NEW.center_id, v_item.course_name, v_item.teacher_id, v_item.grade_level);

    -- If price logic now returns a different result than what's stored, update it
    IF v_new_price IS DISTINCT FROM v_item.amount AND v_new_price > 0 THEN
      
      UPDATE invoice_items 
      SET amount = v_new_price
      WHERE id = v_item.id;
      
      -- Recalculate invoice total
      PERFORM recalculate_invoice_total(v_item.invoice_id);
      
      v_affected_count := v_affected_count + 1;
    END IF;
  END LOOP;

  RAISE NOTICE '✅ Reactive Pricing: Updated % invoices.', v_affected_count;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.on_course_price_change() OWNER TO postgres;

--
-- Name: on_invoice_payment_received(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.on_invoice_payment_received() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE v_student_name TEXT; v_center_id UUID; v_student_id UUID;
BEGIN
  SELECT si.center_id, si.student_id INTO v_center_id, v_student_id FROM student_invoices si WHERE si.id = NEW.invoice_id;
  SELECT u.full_name INTO v_student_name FROM students s JOIN users u ON s.user_id = u.id WHERE s.id = v_student_id;
  IF v_student_name IS NOT NULL AND v_center_id IS NOT NULL THEN
    PERFORM create_notification(v_center_id, 'payment_received', 'normal', '💵 تم استلام دفعة',
      format('تم استلام %s ج.م من الطالب %s', NEW.amount::text, v_student_name),
      jsonb_build_object('invoice_id', NEW.invoice_id, 'student_id', v_student_id, 'amount', NEW.amount, 'route', '/payments'));
  END IF;
  RETURN NEW;
END;
$$;


