-- Name: open_support_ticket(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.open_support_ticket(p_center_id uuid, p_subject text, p_description text, p_priority text, p_category text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_ticket_id UUID;
BEGIN
  INSERT INTO support_tickets (
    center_id, user_id, subject, description, priority, category, status
  ) VALUES (
    p_center_id, auth.uid(), p_subject, p_description, p_priority, p_category, 'open'
  ) RETURNING id INTO v_ticket_id;
  
  -- Create initial message from description
  INSERT INTO support_messages (
    ticket_id, sender_id, message, is_admin_reply
  ) VALUES (
    v_ticket_id, auth.uid(), p_description, false
  );
  
  RETURN v_ticket_id;
END;
$$;


