-- Name: prevent_course_deletion_with_financials(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prevent_course_deletion_with_financials() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Check for invoices related to this course (via items/groups)
  -- Simplified check: If course has active groups with non-zero sessions or enrollments
  
  -- Check 1: Active Groups
  IF EXISTS (SELECT 1 FROM groups WHERE course_id = OLD.id AND is_active = true) THEN
    RAISE EXCEPTION '⛔ لا يمكن حذف الكورس لأن له مجموعات نشطة. قم بأرشفة المجموعات أولاً.';
  END IF;
  
  -- Check 2: Unpaid Invoices (Optional deep check)
  
  RETURN OLD;
END;
$$;


ALTER FUNCTION public.prevent_course_deletion_with_financials() OWNER TO postgres;

--
-- Name: prevent_student_deletion_with_debt(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prevent_student_deletion_with_debt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_debt DECIMAL;
BEGIN
  SELECT COALESCE(SUM(total_amount - paid_amount), 0) INTO v_debt
  FROM student_invoices
  WHERE student_id = OLD.id AND status != 'paid' AND status != 'void';
  
  IF v_debt > 0 THEN
    RAISE EXCEPTION '⛔ لا يمكن حذف الطالب لأن عليه مديونية (%.2f). يجب تسوية الحساب أولاً.', v_debt;
  END IF;
  
  RETURN OLD;
END;
$$;


ALTER FUNCTION public.prevent_student_deletion_with_debt() OWNER TO postgres;

--
-- Name: purchase_sessions_or_month(uuid, uuid, numeric, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.purchase_sessions_or_month(p_student_id uuid, p_center_id uuid, p_amount numeric, p_payment_method text DEFAULT 'cash'::text, p_notes text DEFAULT NULL::text, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_invoice_id UUID;
  v_current_month INTEGER := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::INTEGER);
  v_current_year INTEGER := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER);
  v_result JSON;
BEGIN
  -- Get or create invoice for this month
  v_result := get_or_create_student_invoice(p_student_id, p_center_id, v_current_month, v_current_year);
  v_invoice_id := (v_result->>'id')::UUID;
  
  -- Add payment to invoice
  INSERT INTO invoice_payments (invoice_id, amount, payment_method, notes, paid_at)
  VALUES (v_invoice_id, p_amount, p_payment_method, COALESCE(p_notes, 'شراء حصص/شهر'), NOW());
  
  -- Update invoice paid amount
  UPDATE student_invoices SET paid_amount = paid_amount + p_amount, updated_at = NOW() WHERE id = v_invoice_id;
  
  RETURN json_build_object('invoice_id', v_invoice_id, 'amount', p_amount, 'status', 'paid');
END;
$$;


ALTER FUNCTION public.purchase_sessions_or_month(p_student_id uuid, p_center_id uuid, p_amount numeric, p_payment_method text, p_notes text, p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: recalculate_invoice_total(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recalculate_invoice_total(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE student_invoices
  SET total_amount = (
    SELECT COALESCE(SUM(amount), 0)
    FROM invoice_items
    WHERE invoice_id = p_invoice_id
  )
  WHERE id = p_invoice_id;
END;
$$;


ALTER FUNCTION public.recalculate_invoice_total(p_invoice_id uuid) OWNER TO postgres;

--
-- Name: recalculate_student_invoice(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recalculate_student_invoice(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_invoice RECORD;
    v_enrollment RECORD;
    v_billing_type TEXT;
    v_center_id UUID;
    v_student_id UUID;
    v_month INT;
    v_year INT;
    v_new_total NUMERIC := 0;
    v_item_amount NUMERIC;
    v_smart_price_data RECORD;
    v_session_count INT;
    v_start_date DATE;
    v_end_date DATE;
BEGIN
    -- Get Invoice Details
    SELECT * INTO v_invoice FROM public.student_invoices WHERE id = p_invoice_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Invoice not found');
    END IF;

    v_center_id := v_invoice.center_id;
    v_student_id := v_invoice.student_id;
    v_month := v_invoice.month;
    v_year := v_invoice.year;

    -- Get Billing Type from centers.billing_config
    SELECT billing_config->>'billing_type' INTO v_billing_type 
    FROM public.centers 
    WHERE id = v_center_id;
    
    v_billing_type := COALESCE(v_billing_type, 'monthly');

    -- Define month range for attendance counting
    v_start_date := make_date(v_year, v_month, 1);
    v_end_date := (v_start_date + interval '1 month') - interval '1 day';

    -- Clear existing items (We regenerate them)
    DELETE FROM public.invoice_items WHERE invoice_id = p_invoice_id;

    -- Iterate active enrollments
    FOR v_enrollment IN 
        SELECT 
            e.course_id, 
            c.name as course_name,
            c.fee as course_fee,
            en.grade_level
        FROM public.student_courses e
        JOIN public.courses c ON e.course_id = c.id
        LEFT JOIN public.student_enrollments en ON en.student_id = e.student_id AND en.center_id = v_center_id
        WHERE e.student_id = v_student_id AND e.status = 'active'
    LOOP
        v_item_amount := 0;

        -- Get Smart Price
        DECLARE
            v_teacher_id UUID;
        BEGIN
            SELECT g.teacher_id INTO v_teacher_id
            FROM public.student_group_enrollments sge
            JOIN public.groups g ON sge.group_id = g.id
            WHERE sge.student_id = v_student_id AND g.course_id = v_enrollment.course_id AND sge.status = 'active'
            LIMIT 1;
            
            -- Call get_smart_price logic
            -- Attempt to call get_smart_price if it exists, otherwise fallback query
            -- Assuming table course_prices exists based on previous code analysis
             SELECT monthly_price, session_price INTO v_smart_price_data
             FROM public.course_prices
             WHERE center_id = v_center_id 
               AND subject_name = v_enrollment.course_name -- Note: match by name or ID? course_prices uses subject_name usually
               AND (teacher_id IS NULL OR teacher_id = v_teacher_id)
               AND (grade_level IS NULL OR grade_level = v_enrollment.grade_level)
             ORDER BY teacher_id NULLS LAST, grade_level NULLS LAST
             LIMIT 1;

            -- If billing type is monthly
            IF v_billing_type = 'monthly' THEN
                v_item_amount := COALESCE(v_smart_price_data.monthly_price, v_enrollment.course_fee);
            ELSIF v_billing_type = 'per_session' THEN
                -- Per Session
                -- Count attendance
                SELECT count(*) INTO v_session_count
                FROM public.attendance a
                JOIN public.schedules s ON a.session_id = s.id
                WHERE a.student_id = v_student_id
                  AND s.course_id = v_enrollment.course_id
                  AND a.date BETWEEN v_start_date AND v_end_date
                  AND a.status IN ('present', 'late'); -- Charge for present/late
                
                v_item_amount := v_session_count * COALESCE(v_smart_price_data.session_price, 0);
            ELSE
                 -- Fallback/Mixed (Default to Monthly for now safety)
                 v_item_amount := COALESCE(v_smart_price_data.monthly_price, v_enrollment.course_fee);
            END IF;

        EXCEPTION WHEN OTHERS THEN
             v_item_amount := v_enrollment.course_fee;
        END;

        -- Insert Invoice Item
        IF v_item_amount > 0 THEN
            INSERT INTO public.invoice_items (invoice_id, course_id, course_name, amount, description)
            VALUES (p_invoice_id, v_enrollment.course_id, v_enrollment.course_name, v_item_amount, 
                CASE WHEN v_billing_type = 'monthly' THEN 'اشتراك شهري' ELSE 'حساب بالحصص' END
            );
            v_new_total := v_new_total + v_item_amount;
        END IF;

    END LOOP;

    -- Update Invoice Total (Strictly sum of items now)
    UPDATE public.student_invoices
    SET total_amount = v_new_total,
        status = CASE 
            WHEN v_new_total <= paid_amount THEN 'paid'
            WHEN paid_amount > 0 AND paid_amount < v_new_total THEN 'partial'
            ELSE 'pending'
        END,
        updated_at = now()
    WHERE id = p_invoice_id;

    RETURN jsonb_build_object(
        'success', true, 
        'new_total', v_new_total,
        'billing_type', v_billing_type
    );
END;
$$;


ALTER FUNCTION public.recalculate_student_invoice(p_invoice_id uuid) OWNER TO postgres;

--
-- Name: record_attendance_with_billing(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_attendance_with_billing(p_student_id uuid, p_group_id uuid, p_attendance_status text DEFAULT 'present'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_enrollment RECORD;
  v_billing_type TEXT;
  v_grace_sessions INTEGER;
  v_max_debt INTEGER;
  v_result JSONB;
  v_can_attend BOOLEAN := TRUE;
  v_warning TEXT := NULL;
BEGIN
  -- جلب بيانات التسجيل
  SELECT * INTO v_enrollment
  FROM student_billing_status
  WHERE student_id = p_student_id AND group_id = p_group_id;
  
  IF v_enrollment IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'الطالب غير مسجل في هذه المجموعة'
    );
  END IF;
  
  v_billing_type := v_enrollment.effective_billing_type;
  v_grace_sessions := v_enrollment.grace_sessions;
  v_max_debt := v_enrollment.max_debt_sessions;
  
  -- التحقق من حالة الدفع
  IF v_billing_type = 'per_session' THEN
    -- نظام الحصص: تحقق من الرصيد
    IF v_enrollment.sessions_remaining <= 0 THEN
      -- لا يوجد رصيد
      IF v_enrollment.sessions_debt >= v_max_debt THEN
        -- تجاوز الحد الأقصى للدين
        v_can_attend := FALSE;
        v_warning := 'تم منع الحضور: تجاوز الحد الأقصى للدين (' || v_max_debt || ' حصص)';
      ELSIF v_enrollment.sessions_debt >= v_grace_sessions THEN
        -- في فترة التحذير
        v_warning := '⚠️ تحذير: الطالب تجاوز مهلة الحصص المجانية. يرجى التواصل مع ولي الأمر';
      ELSE
        -- في فترة المهلة
        v_warning := 'ℹ️ ملاحظة: الطالب يستخدم حصة من المهلة (' || (v_enrollment.sessions_debt + 1) || '/' || v_grace_sessions || ')';
      END IF;
    END IF;
    
  ELSIF v_billing_type = 'monthly' THEN
    -- نظام شهري: تحقق من دفع الشهر
    IF NOT COALESCE(v_enrollment.current_month_paid, FALSE) THEN
      IF v_enrollment.sessions_debt >= v_max_debt THEN
        v_can_attend := FALSE;
        v_warning := 'تم منع الحضور: لم يتم دفع الشهر وتجاوز عدد الحصص المسموحة';
      ELSIF v_enrollment.sessions_debt >= v_grace_sessions THEN
        v_warning := '⚠️ تحذير: الطالب لم يدفع الشهر. يرجى التواصل مع ولي الأمر';
      ELSE
        v_warning := 'ℹ️ ملاحظة: الطالب لم يدفع الشهر بعد';
      END IF;
    END IF;
  END IF;
  
  -- إذا كان الحضور مسموحاً
  IF v_can_attend AND p_attendance_status = 'present' THEN
    -- تحديث عداد الحصص
    UPDATE student_group_enrollments
    SET 
      sessions_attended = sessions_attended + 1,
      sessions_debt = CASE 
        WHEN sessions_purchased - sessions_attended <= 0 THEN sessions_debt + 1
        ELSE sessions_debt
      END,
      updated_at = NOW()
    WHERE student_id = p_student_id AND group_id = p_group_id;
  END IF;
  
  -- بناء النتيجة
  v_result := jsonb_build_object(
    'success', v_can_attend,
    'can_attend', v_can_attend,
    'billing_type', v_billing_type,
    'sessions_remaining', v_enrollment.sessions_remaining,
    'sessions_debt', v_enrollment.sessions_debt,
    'warning', v_warning,
    'current_month_paid', v_enrollment.current_month_paid
  );
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.record_attendance_with_billing(p_student_id uuid, p_group_id uuid, p_attendance_status text) OWNER TO postgres;

--
-- Name: reindex_tables(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reindex_tables(p_table_names text[] DEFAULT NULL::text[]) RETURNS TABLE(table_name text, status text, message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    tbl TEXT;
    tables_to_reindex TEXT[];
BEGIN
    -- إذا لم يتم تحديد جداول، استخدم الجداول الرئيسية
    IF p_table_names IS NULL THEN
        tables_to_reindex := ARRAY[
            'payments', 'invoices', 'student_enrollments', 'teacher_enrollments',
            'attendance', 'grades', 'courses', 'schedules', 'notifications',
            'analytics_events'
        ];
    ELSE
        tables_to_reindex := p_table_names;
    END IF;
    
    FOREACH tbl IN ARRAY tables_to_reindex
    LOOP
        BEGIN
            EXECUTE format('REINDEX TABLE CONCURRENTLY public.%I', tbl);
            RETURN QUERY SELECT tbl, 'success'::TEXT, 'تم إعادة بناء الـ Indexes بنجاح'::TEXT;
        EXCEPTION WHEN OTHERS THEN
            RETURN QUERY SELECT tbl, 'error'::TEXT, SQLERRM;
        END;
    END LOOP;
END;
$$;


ALTER FUNCTION public.reindex_tables(p_table_names text[]) OWNER TO postgres;

--
-- Name: FUNCTION reindex_tables(p_table_names text[]); Type: COMMENT; Schema: public; Owner: postgres
--

