-- Name: report_content(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.report_content(p_target_type text, p_target_id uuid, p_reason text, p_details text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_report_id UUID;
BEGIN
  INSERT INTO community_reports (reporter_id, target_type, target_id, reason, details)
  VALUES (auth.uid(), p_target_type, p_target_id, p_reason, p_details)
  RETURNING id INTO v_report_id;
  
  RETURN v_report_id;
END;
$$;


