--
-- Name: reset_monthly_payments(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reset_monthly_payments(p_center_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  UPDATE student_group_enrollments sge
  SET current_month_paid = FALSE
  FROM groups g
  WHERE sge.group_id = g.id 
    AND g.center_id = p_center_id
    AND sge.status = 'active';
    
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION public.reset_monthly_payments(p_center_id uuid) OWNER TO postgres;

--
-- Name: save_teacher_monthly_salary(uuid, uuid, integer, integer, text, numeric, numeric, numeric, text, jsonb, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_teacher_monthly_salary(p_center_id uuid, p_teacher_id uuid, p_month integer, p_year integer, p_salary_type text, p_base_salary numeric, p_sessions_total numeric, p_percentage_total numeric, p_status text, p_items jsonb, p_payment_method text DEFAULT NULL::text, p_payment_reference text DEFAULT NULL::text, p_payment_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_salary_id UUID;
  v_bonuses_total DECIMAL := 0;
  v_deductions_total DECIMAL := 0;
  v_gross DECIMAL;
  v_net DECIMAL;
  v_payment_date TIMESTAMP WITH TIME ZONE;
BEGIN
  -- 1. Calculate totals from items
  SELECT 
    COALESCE(SUM(CASE WHEN (val->>'type') = 'bonus' THEN (val->>'amount')::DECIMAL ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN (val->>'type') = 'deduction' THEN (val->>'amount')::DECIMAL ELSE 0 END), 0)
  INTO v_bonuses_total, v_deductions_total
  FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb)) val;

  v_gross := COALESCE(p_base_salary, 0) + COALESCE(p_sessions_total, 0) + COALESCE(p_percentage_total, 0) + v_bonuses_total;
  v_net := v_gross - v_deductions_total;
  
  -- Set payment date if status is paid
  IF p_status = 'paid' THEN
    v_payment_date := COALESCE(p_payment_date, NOW());
  ELSE
    v_payment_date := NULL;
  END IF;

  -- 2. Upsert Salary Record
  INSERT INTO teacher_salaries (
    center_id, teacher_id, month, year, salary_type,
    base_salary, sessions_total_amount, percentage_total_amount,
    bonuses_total_amount, deductions_total_amount,
    gross_salary, net_salary, status, 
    payment_date, payment_method, payment_reference,
    updated_at
  ) VALUES (
    p_center_id, p_teacher_id, p_month, p_year, COALESCE(p_salary_type, 'fixed'),
    COALESCE(p_base_salary, 0), COALESCE(p_sessions_total, 0), COALESCE(p_percentage_total, 0),
    v_bonuses_total, v_deductions_total,
    v_gross, v_net, COALESCE(p_status, 'draft'),
    v_payment_date, p_payment_method, p_payment_reference,
    NOW()
  )
  ON CONFLICT (teacher_id, center_id, month, year) 
  DO UPDATE SET
    salary_type = EXCLUDED.salary_type,
    base_salary = EXCLUDED.base_salary,
    sessions_total_amount = EXCLUDED.sessions_total_amount,
    percentage_total_amount = EXCLUDED.percentage_total_amount,
    bonuses_total_amount = EXCLUDED.bonuses_total_amount,
    deductions_total_amount = EXCLUDED.deductions_total_amount,
    gross_salary = EXCLUDED.gross_salary,
    net_salary = EXCLUDED.net_salary,
    status = EXCLUDED.status,
    payment_date = CASE 
      WHEN p_status = 'paid' THEN COALESCE(EXCLUDED.payment_date, teacher_salaries.payment_date, NOW())
      ELSE teacher_salaries.payment_date
    END,
    payment_method = COALESCE(EXCLUDED.payment_method, teacher_salaries.payment_method),
    payment_reference = COALESCE(EXCLUDED.payment_reference, teacher_salaries.payment_reference),
    updated_at = NOW()
  RETURNING id INTO v_salary_id;

  -- 3. Replace Items
  DELETE FROM salary_items WHERE salary_id = v_salary_id;
  
  IF p_items IS NOT NULL AND jsonb_array_length(p_items) > 0 THEN
    INSERT INTO salary_items (salary_id, type, description, amount, rate, count)
    SELECT 
      v_salary_id,
      COALESCE(val->>'type', 'bonus'),
      COALESCE(val->>'description', ''),
      COALESCE((val->>'amount')::DECIMAL, 0),
      COALESCE((val->>'rate')::DECIMAL, 0),
      COALESCE((val->>'count')::INTEGER, 0)
    FROM jsonb_array_elements(p_items) val;
  END IF;

  RETURN v_salary_id;
END;
$$;


ALTER FUNCTION public.save_teacher_monthly_salary(p_center_id uuid, p_teacher_id uuid, p_month integer, p_year integer, p_salary_type text, p_base_salary numeric, p_sessions_total numeric, p_percentage_total numeric, p_status text, p_items jsonb, p_payment_method text, p_payment_reference text, p_payment_date timestamp with time zone) OWNER TO postgres;

--
-- Name: scan_attendance_qr(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scan_attendance_qr(p_qr_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_user_id UUID;
    v_lesson RECORD;
    v_student_id UUID;
BEGIN
    v_user_id := auth.uid();
    
    -- Get lesson by QR code (must be for today)
    -- We can relax 'today' constraint if needed, but usually attendance is same-day
    SELECT l.*, c.name as course_name 
    INTO v_lesson
    FROM lessons l
    JOIN courses c ON l.course_id = c.id
    WHERE l.qr_code = p_qr_code
    -- AND l.date = CURRENT_DATE -- Optional: Enforce date? Let's enforce within +/- 1 day to be safe/flexible
    LIMIT 1;

    IF v_lesson IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'كود غير صحيح');
    END IF;

    -- Get student ID (from users table or students table)
    -- Assuming attendance table uses 'student_id' which matches 'students.id'
    -- We need to find the student_id associated with this auth.users.id
    SELECT id INTO v_student_id FROM students WHERE user_id = v_user_id LIMIT 1;
    
    IF v_student_id IS NULL THEN
        -- Fallback: maybe v_user_id IS the student_id in some legacy rows?
        -- But correct logic is to find student record.
        v_student_id := v_user_id; -- Fallback
    END IF;

    -- Insert attendance record
    INSERT INTO attendance (student_id, lesson_id, center_id, date, status, check_in_time)
    VALUES (
        v_student_id, -- user_id might work if FK allows, but sticking to mapped ID
        v_lesson.id,
        v_lesson.center_id,
        v_lesson.date,
        'present',
        NOW()
    )
    ON CONFLICT (student_id, lesson_id) 
    DO UPDATE SET 
        status = 'present',
        check_in_time = NOW();

    RETURN jsonb_build_object(
        'success', true, 
        'message', 'تم تسجيل الحضور بنجاح',
        'course_name', v_lesson.course_name,
        'date', v_lesson.date
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION public.scan_attendance_qr(p_qr_code text) OWNER TO postgres;

--
-- Name: secure_check_in(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.secure_check_in(p_student_id uuid, p_qr_payload text, p_location jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_session_id uuid;
    v_qr_parts text[];
    v_session_record record;
    v_enrollment_status text;
    v_course_name text;
    v_attendance_id uuid;
    v_is_universal boolean := false;
    
    -- Verification vars
    v_key text;
    v_timestamp bigint;
    v_provided_signature text;
    v_calculated_signature text;
    v_qr_time timestamptz;
BEGIN
    -- A. Parse QR Payload
    v_qr_parts := regexp_split_to_array(p_qr_payload, ':');
    
    IF v_qr_parts[1] = 'UNIVERSAL' THEN
        v_is_universal := true;
        
        -- Start Universal Logic 🛡️
        
        -- v_qr_parts[3] is TIMESTAMP (15s epoch)
        -- v_qr_parts[4] is SIGNATURE
        
        IF array_length(v_qr_parts, 1) < 4 THEN
             RETURN jsonb_build_object('success', false, 'message', 'Invalid QR Format');
        END IF;

        v_timestamp := v_qr_parts[3]::bigint;
        v_provided_signature := v_qr_parts[4];
        
        -- 1. Verify Signature
        SELECT universal_qr_key INTO v_key FROM public.center_settings LIMIT 1;
        v_calculated_signature := md5(v_key || v_timestamp::text);
        
        IF v_provided_signature != v_calculated_signature THEN
             RETURN jsonb_build_object('success', false, 'message', 'Invalid QR Signature (Fake/Forged)');
        END IF;
        
        -- 2. Calculate Real Time from Timestamp
        -- Timestamp is (Epoch / 15)
        v_qr_time := to_timestamp(v_timestamp * 15);
        
        -- 3. Find Session ACTIVE AT THAT TIME
        -- Instead of checking against now(), we check against v_qr_time
        -- This allows for "Offline Check-in" where the scan happened in the past
        SELECT s.*, c.name as course_name 
        INTO v_session_record
        FROM public.attendance_sessions s
        JOIN public.groups g ON g.id = s.group_id
        JOIN public.courses c ON c.id = g.course_id
        JOIN public.student_group_enrollments sge ON sge.group_id = g.id
        WHERE sge.student_id = p_student_id
          AND sge.status = 'active'
          AND (
              s.status = 'open' 
              OR s.status = 'active'
              OR (
                  s.status = 'scheduled' 
                  AND s.opens_at <= v_qr_time 
                  AND (s.closes_at IS NULL OR s.closes_at > v_qr_time)
              )
          )
        ORDER BY s.opens_at DESC
        LIMIT 1;

        IF v_session_record IS NULL THEN
            -- Debug info: help user understand why
            RETURN jsonb_build_object('success', false, 'message', 'لا توجد حصة نشطة في وقت المسح (' || v_qr_time::text || ')');
        END IF;

        v_session_id := v_session_record.id;
        v_course_name := v_session_record.course_name;
        
    ELSE
        -- Specific Session Logic (Legacy) behavior remains checking against now() for security unless we update it too
        -- For now keeping as is for backward compat
        v_session_id := v_qr_parts[1]::uuid;
        SELECT s.*, g.id as group_id, c.name as course_name 
        INTO v_session_record
        FROM public.attendance_sessions s 
        JOIN public.groups g ON g.id = s.group_id 
        JOIN public.courses c ON c.id = g.course_id
        WHERE s.id = v_session_id;

        IF v_session_record IS NULL THEN RETURN jsonb_build_object('success', false, 'message', 'الحصة غير موجودة'); END IF;
        SELECT status INTO v_enrollment_status FROM public.student_group_enrollments WHERE student_id = p_student_id AND group_id = v_session_record.group_id;
        IF v_enrollment_status IS NULL OR v_enrollment_status != 'active' THEN RETURN jsonb_build_object('success', false, 'message', 'Student not enrolled'); END IF;
        
        v_course_name := v_session_record.course_name;
        
        -- Validate Time (Strict processing time check for legacy)
        IF v_session_record.status = 'closed' OR (v_session_record.closes_at IS NOT NULL AND v_session_record.closes_at < now()) THEN RETURN jsonb_build_object('success', false, 'message', 'الحصة مغلقة'); END IF;
        IF v_session_record.status = 'scheduled' AND v_session_record.opens_at > now() THEN RETURN jsonb_build_object('success', false, 'message', 'الحصة لم تبدأ بعد'); END IF;
    END IF;

    -- Common: Check duplicate
    SELECT id INTO v_attendance_id
    FROM public.attendance
    WHERE session_id = v_session_id AND student_id = p_student_id;

    IF v_attendance_id IS NOT NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'تم تسجيل الحضور مسبقاً', 'course_name', v_course_name);
    END IF;

    -- Record Attendance (Backdated if needed?)
    -- Ideally we record check_in_time as the QR time, but created_at as now
    INSERT INTO public.attendance (
        session_id,
        student_id,
        center_id,
        status,
        check_in_time,
        created_at
    ) VALUES (
        v_session_id,
        p_student_id,
        v_session_record.center_id,
        'present',
        COALESCE(v_qr_time, now()), -- Use QR time as check-in time
        now()
    ) RETURNING id INTO v_attendance_id;

    RETURN jsonb_build_object(
        'success', true, 
        'message', 'تم تسجيل الحضور بنجاح',
        'attendance_id', v_attendance_id,
        'course_name', v_course_name
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION public.secure_check_in(p_student_id uuid, p_qr_payload text, p_location jsonb) OWNER TO postgres;

--
-- Name: send_bulk_notification(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.send_bulk_notification(p_center_id uuid, p_recipient_role text, p_title text, p_body text, p_category text DEFAULT 'general'::text, p_priority text DEFAULT 'normal'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    notification_count INTEGER := 0;
    recipient_id UUID;
BEGIN
    -- إرسال للطلاب
    IF p_recipient_role IN ('all', 'students') THEN
        FOR recipient_id IN
            SELECT DISTINCT user_id
            FROM student_enrollments
            WHERE center_id = p_center_id
            AND status = 'accepted'
            AND (deleted_at IS NULL OR deleted_at > NOW())
        LOOP
            INSERT INTO notifications (
                recipient_id,
                center_id,
                title,
                body,
                category,
                priority,
                read_status
            ) VALUES (
                recipient_id,
                p_center_id,
                p_title,
                p_body,
                p_category,
                p_priority,
                FALSE
            );
            notification_count := notification_count + 1;
        END LOOP;
    END IF;
    
    -- إرسال للمعلمين
    IF p_recipient_role IN ('all', 'teachers') THEN
        FOR recipient_id IN
            SELECT DISTINCT user_id
            FROM teacher_enrollments
            WHERE center_id = p_center_id
            AND status = 'active'
            AND (deleted_at IS NULL OR deleted_at > NOW())
        LOOP
            INSERT INTO notifications (
                recipient_id,
                center_id,
                title,
                body,
                category,
                priority,
                read_status
            ) VALUES (
                recipient_id,
                p_center_id,
                p_title,
                p_body,
                p_category,
                p_priority,
                FALSE
            );
            notification_count := notification_count + 1;
        END LOOP;
    END IF;
    
    RETURN notification_count;
END;
$$;


ALTER FUNCTION public.send_bulk_notification(p_center_id uuid, p_recipient_role text, p_title text, p_body text, p_category text, p_priority text) OWNER TO postgres;

