--
-- Name: send_message(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.send_message(p_conversation_id uuid, p_content text, p_type text DEFAULT 'text'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_message_id UUID;
    v_is_student BOOLEAN;
BEGIN
    -- Check if sender is student or teacher in this conversation
    SELECT (student_id = auth.uid()) INTO v_is_student
    FROM public.conversations
    WHERE id = p_conversation_id;

    -- Insert message
    INSERT INTO public.messages (conversation_id, sender_id, content, message_type)
    VALUES (p_conversation_id, auth.uid(), p_content, p_type)
    RETURNING id INTO v_message_id;

    -- Update conversation (last message and unread count)
    UPDATE public.conversations
    SET 
        last_message = CASE WHEN p_type = 'text' THEN p_content ELSE 'Attachment' END,
        last_message_at = NOW(),
        updated_at = NOW(),
        unread_count_student = CASE WHEN NOT v_is_student THEN unread_count_student + 1 ELSE unread_count_student END,
        unread_count_teacher = CASE WHEN v_is_student THEN unread_count_teacher + 1 ELSE unread_count_teacher END
    WHERE id = p_conversation_id;

    RETURN v_message_id;
END;
$$;


ALTER FUNCTION public.send_message(p_conversation_id uuid, p_content text, p_type text) OWNER TO postgres;

