--
-- Name: set_enrollment_date(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_enrollment_date() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'accepted' AND (OLD.status IS NULL OR OLD.status != 'accepted') THEN
    NEW.enrolled_at := now();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.set_enrollment_date() OWNER TO postgres;

--
-- Name: set_invitation_code(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_invitation_code() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.invitation_code IS NULL OR NEW.invitation_code = '' THEN
    NEW.invitation_code := generate_invitation_code();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.set_invitation_code() OWNER TO postgres;

--
-- Name: set_teacher_invitation_code(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_teacher_invitation_code() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    IF NEW.invitation_code IS NULL THEN
        NEW.invitation_code := 'T' || UPPER(SUBSTRING(MD5(RANDOM()::TEXT) FROM 1 FOR 7));
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.set_teacher_invitation_code() OWNER TO postgres;

--
-- Name: simulate_price_impact(uuid, text, double precision, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.simulate_price_impact(p_center_id uuid, p_course_name text, p_new_price double precision, p_teacher_id uuid DEFAULT NULL::uuid, p_grade_level text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_impacted_count INT := 0;
  v_revenue_diff DECIMAL(10, 2) := 0;
  v_old_revenue DECIMAL(10, 2) := 0;
  v_new_revenue DECIMAL(10, 2) := 0;
  v_samples TEXT[];
BEGIN
  -- Calculate impact on PENDING invoices
  SELECT 
    COUNT(*),
    COALESCE(SUM(amount), 0)
  INTO v_impacted_count, v_old_revenue
  FROM invoice_items ii
  JOIN student_invoices si ON ii.invoice_id = si.id
  WHERE si.center_id = p_center_id
    AND si.status = 'pending'
    AND ii.course_name = p_course_name
    -- Apply strict filtering if provided, otherwise apply broad impact
    AND (p_teacher_id IS NULL OR ii.teacher_id = p_teacher_id)
    AND (p_grade_level IS NULL OR ii.grade_level = p_grade_level);

  IF v_impacted_count = 0 THEN
      RETURN jsonb_build_object(
        'impacted_invoices', 0,
        'revenue_difference', 0,
        'sample_students', ARRAY[]::TEXT[]
      );
  END IF;

  v_new_revenue := v_impacted_count * p_new_price;
  v_revenue_diff := v_new_revenue - v_old_revenue;
  
  -- Get samples (Student Names)
  -- Uses a subquery to try and fetch names correctly.
  -- Assuming 'students' table has 'full_name' OR referencing 'users' via 'students.user_id' if needed.
  -- Based on legacy code: students table seems to be used directly for names in some parts, but likely it's a view.
  -- Safest fallback: Use student_invoices -> students -> full_name
  
  SELECT ARRAY_AGG(student_name) INTO v_samples
  FROM (
    SELECT s.full_name as student_name
    FROM invoice_items ii
    JOIN student_invoices si ON ii.invoice_id = si.id
    LEFT JOIN students s ON si.student_id = s.id
    WHERE si.center_id = p_center_id
      AND si.status = 'pending'
      AND ii.course_name = p_course_name
    LIMIT 5
  ) t;

  RETURN jsonb_build_object(
    'impacted_invoices', v_impacted_count,
    'revenue_difference', v_revenue_diff,
    'sample_students', COALESCE(v_samples, ARRAY[]::TEXT[])
  );
END;
$$;


ALTER FUNCTION public.simulate_price_impact(p_center_id uuid, p_course_name text, p_new_price double precision, p_teacher_id uuid, p_grade_level text) OWNER TO postgres;

--
-- Name: simulate_price_impact(uuid, text, uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.simulate_price_impact(p_center_id uuid, p_course_name text, p_teacher_id uuid, p_grade_level text, p_new_price numeric) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_affected_count INT;
  v_current_total DECIMAL := 0;
  v_new_total DECIMAL := 0;
  v_sample_students JSON;
BEGIN
  -- 1. Find matching pending invoice items
  -- We query items that MATCH the context.
  WITH matching_items AS (
    SELECT 
      ii.amount as current_amount,
      s.name as student_name
    FROM invoice_items ii
    JOIN student_invoices si ON ii.invoice_id = si.id
    JOIN students s ON si.student_id = s.id
    WHERE si.center_id = p_center_id
      AND si.status = 'pending'
      AND ii.course_name = p_course_name
      -- Logic matches `get_smart_price`: accurate matching
      AND (p_teacher_id IS NULL OR ii.teacher_id = p_teacher_id)
      AND (p_grade_level IS NULL OR ii.grade_level = p_grade_level)
  )
  SELECT 
    COUNT(*),
    COALESCE(SUM(current_amount), 0),
    COALESCE(SUM(p_new_price), 0),
    COALESCE(json_agg(student_name) FILTER (WHERE row_number <= 3), '[]'::json)
  INTO 
    v_affected_count,
    v_current_total,
    v_new_total,
    v_sample_students
  FROM (
    SELECT *, ROW_NUMBER() OVER () as row_number FROM matching_items
  ) sub;

  RETURN json_build_object(
    'impacted_invoices', v_affected_count,
    'current_revenue', v_current_total,
    'projected_revenue', v_new_total,
    'revenue_difference', (v_new_total - v_current_total),
    'sample_students', v_sample_students
  );
END;
$$;


ALTER FUNCTION public.simulate_price_impact(p_center_id uuid, p_course_name text, p_teacher_id uuid, p_grade_level text, p_new_price numeric) OWNER TO postgres;

--
-- Name: smart_search(text, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.smart_search(p_query text, p_center_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20) RETURNS TABLE(entity_type text, entity_id uuid, entity_name text, similarity real, metadata jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    
    -- البحث في الطلاب
    SELECT 
        'student'::TEXT,
        p.user_id,
        p.full_name,
        similarity(p.full_name, p_query),
        jsonb_build_object('phone', p.phone)
    FROM public.profiles p
    JOIN public.student_enrollments se ON se.user_id = p.user_id
    WHERE p.full_name % p_query
    AND (p_center_id IS NULL OR se.center_id = p_center_id)
    
    UNION ALL
    
    -- البحث في الكورسات
    SELECT 
        'course'::TEXT,
        c.id,
        c.name,
        similarity(c.name, p_query),
        jsonb_build_object('description', c.description)
    FROM public.courses c
    WHERE c.name % p_query
    AND (p_center_id IS NULL OR c.center_id = p_center_id)
    
    UNION ALL
    
    -- البحث في المحتوى التعليمي
    SELECT 
        'content'::TEXT,
        cl.id,
        cl.title,
        similarity(cl.title, p_query),
        jsonb_build_object('type', cl.content_type)
    FROM public.content_library cl
    WHERE cl.title % p_query
    AND (p_center_id IS NULL OR cl.center_id = p_center_id)
    
    ORDER BY similarity DESC
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.smart_search(p_query text, p_center_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION smart_search(p_query text, p_center_id uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.smart_search(p_query text, p_center_id uuid, p_limit integer) IS 'بحث ذكي متعدد الكيانات مع دعم البحث الضبابي';


--
-- Name: start_attendance_session(uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.start_attendance_session(p_center_id uuid, p_group_id uuid, p_duration_minutes integer DEFAULT 90, p_created_by uuid DEFAULT NULL::uuid) RETURNS TABLE(session_id uuid, session_token text, expires_at timestamp without time zone, group_name text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_session_id UUID;
  v_token TEXT;
  v_expires_at TIMESTAMP;
  v_group_name TEXT;
BEGIN
  -- Generate unique token
  v_token := encode(gen_random_bytes(16), 'hex');
  v_expires_at := NOW() + (p_duration_minutes || ' minutes')::interval;
  
  -- Get group name
  SELECT g.group_name INTO v_group_name
  FROM groups g WHERE g.id = p_group_id;
  
  -- Check if session exists for today - update it
  UPDATE attendance_sessions
  SET 
    session_token = v_token,
    started_at = NOW(),
    expires_at = v_expires_at,
    status = 'active',
    updated_at = NOW()
  WHERE group_id = p_group_id
    AND session_date = CURRENT_DATE
  RETURNING id INTO v_session_id;
  
  -- If no existing session, create new one
  IF v_session_id IS NULL THEN
    INSERT INTO attendance_sessions (
      center_id, group_id, session_token, expires_at, created_by
    ) VALUES (
      p_center_id, p_group_id, v_token, v_expires_at, p_created_by
    ) RETURNING id INTO v_session_id;
  END IF;
  
  RETURN QUERY SELECT v_session_id, v_token, v_expires_at, v_group_name;
END;
$$;


ALTER FUNCTION public.start_attendance_session(p_center_id uuid, p_group_id uuid, p_duration_minutes integer, p_created_by uuid) OWNER TO postgres;

--
-- Name: student_login_secure(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.student_login_secure(p_email text, p_password text, p_device_id text, p_device_info jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_student_id UUID;
  v_stored_device_id TEXT;
  v_user_id UUID;
BEGIN
  -- Get the current authenticated user's ID
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Get student record linked to this user
  SELECT id, device_id INTO v_student_id, v_stored_device_id
  FROM public.students
  WHERE user_id = v_user_id;
  
  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Student profile not found';
  END IF;

  -- Logic:
  -- 1. If no device bound (v_stored_device_id IS NULL) -> Bind this device
  -- 2. If device bound matches current (v_stored_device_id == p_device_id) -> Allow
  -- 3. If device bound differs -> Deny
  
  IF v_stored_device_id IS NULL OR v_stored_device_id = '' THEN
    -- First time login or no device bound: Bind this device
    UPDATE public.students 
    SET device_id = p_device_id,
        device_info = p_device_info,
        last_login_at = NOW()
    WHERE id = v_student_id;
    
    RETURN json_build_object(
      'success', true,
      'message', 'Device bound successfully',
      'student_id', v_student_id
    );
    
  ELSIF v_stored_device_id = p_device_id THEN
    -- Same device: Update last login
    UPDATE public.students 
    SET last_login_at = NOW()
    WHERE id = v_student_id;
    
    RETURN json_build_object(
      'success', true,
      'message', 'Login successful',
      'student_id', v_student_id
    );
    
  ELSE
    -- Different device: Block
    RAISE EXCEPTION 'هذا الحساب مرتبط بجهاز آخر. لا يمكن الدخول من هذا الجهاز الجديد.';
  END IF;
END;
$$;


ALTER FUNCTION public.student_login_secure(p_email text, p_password text, p_device_id text, p_device_info jsonb) OWNER TO postgres;

--
-- Name: submit_assignment_rpc(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_assignment_rpc(p_assignment_id uuid, p_file_url text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_submission_id uuid;
    v_center_id uuid;
BEGIN
    -- Verify user is enrolled in the assignment's center
    SELECT se.center_id INTO v_center_id
    FROM public.student_enrollments se
    WHERE se.student_user_id = auth.uid()
    AND se.status = 'accepted'
    AND se.deleted_at IS NULL
    LIMIT 1;

    IF NOT EXISTS (
        SELECT 1 FROM public.assignments a
        WHERE a.id = p_assignment_id
        AND a.center_id = v_center_id
        AND a.deleted_at IS NULL
    ) THEN
        RETURN json_build_object('success', false, 'error', 'غير مسموح بتسليم هذا الواجب');
    END IF;

    -- Insert or update submission
    INSERT INTO public.assignment_submissions 
        (assignment_id, student_user_id, file_url, notes, submitted_at)
    VALUES 
        (p_assignment_id, auth.uid(), p_file_url, p_notes, now())
    ON CONFLICT (assignment_id, student_user_id) 
    DO UPDATE SET 
        file_url = COALESCE(EXCLUDED.file_url, assignment_submissions.file_url),
        notes = COALESCE(EXCLUDED.notes, assignment_submissions.notes),
        submitted_at = now(),
        updated_at = now()
    WHERE assignment_submissions.graded_at IS NULL
    RETURNING id INTO v_submission_id;
    
    IF v_submission_id IS NOT NULL THEN
        RETURN json_build_object('success', true, 'submission_id', v_submission_id);
    ELSE
        RETURN json_build_object('success', false, 'error', 'لا يمكن تعديل التسليم بعد التصحيح');
    END IF;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION public.submit_assignment_rpc(p_assignment_id uuid, p_file_url text, p_notes text) OWNER TO postgres;

--
-- Name: suggest_best_groups_for_student(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.suggest_best_groups_for_student(p_student_id uuid, p_course_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_student_record RECORD;
    v_center_id UUID;
    v_result JSONB := '[]'::jsonb;
    v_course_id UUID;
    v_best_group RECORD;
    v_group_candidate RECORD;
    v_score INT;
    v_highest_score INT;
    v_conflict BOOLEAN;
    v_student_active_days INT[]; -- Array of day_of_week (integers)
    v_course_name TEXT;
    
    -- Helper to map text days to integers if needed, but groups has int day_of_week?
    -- Checked schema: groups has 'day_of_week integer'. schedules has 'day_of_week text'.
    -- We need to standardize. Assuming groups.day_of_week is 1=Mon, 7=Sun or similar.
    
    -- Let's fetch student days from existing enrollments
BEGIN
    -- 1. Get Student Info
    SELECT * INTO v_student_record FROM public.student_enrollments WHERE student_id = p_student_id LIMIT 1;
    IF NOT FOUND THEN
        -- Maybe student is new and not in student_enrollments yet? 
        -- Try to get center from context or first course
        SELECT center_id INTO v_center_id FROM public.courses WHERE id = p_course_ids[1];
    ELSE
        v_center_id := v_student_record.center_id;
    END IF;

    -- 2. Identify "Active Days" (Days student is already coming to center)
    -- We look at existing group enrollments -> groups -> day_of_week
    SELECT array_agg(DISTINCT g.day_of_week) INTO v_student_active_days
    FROM public.student_group_enrollments sge
    JOIN public.groups g ON sge.group_id = g.id
    WHERE sge.student_id = p_student_id AND sge.status = 'active';

    IF v_student_active_days IS NULL THEN
        v_student_active_days := ARRAY[]::INT[];
    END IF;

    -- 3. Iterate over requested courses
    FOREACH v_course_id IN ARRAY p_course_ids
    LOOP
        v_highest_score := -9999;
        v_best_group := NULL;
        
        SELECT name INTO v_course_name FROM public.courses WHERE id = v_course_id;

        -- Iterate over active groups for this course
        FOR v_group_candidate IN 
            SELECT * FROM public.groups 
            WHERE course_id = v_course_id 
              AND is_active = true 
              AND (grade_level IS NULL OR grade_level = v_student_record.grade_level) -- Hard Constraint: Grade
              AND current_students < max_students -- Hard Constraint: Capacity
        LOOP
            v_score := 0;
            v_conflict := FALSE;

            -- A. Conflict Detection (Hard Constraint)
            -- Check if student has another group at the same time
            IF EXISTS (
                SELECT 1 
                FROM public.student_group_enrollments sge
                JOIN public.groups g ON sge.group_id = g.id
                WHERE sge.student_id = p_student_id 
                  AND sge.status = 'active'
                  AND g.day_of_week = v_group_candidate.day_of_week
                  AND (
                      (g.start_time, g.end_time) OVERLAPS (v_group_candidate.start_time, v_group_candidate.end_time)
                  )
            ) THEN
                v_conflict := TRUE;
            END IF;

            IF NOT v_conflict THEN
                -- B. Day Clustering (Optimization)
                -- +50 points if day is already in active days
                IF v_group_candidate.day_of_week = ANY(v_student_active_days) THEN
                    v_score := v_score + 50;
                END IF;

                -- C. Load Balancing (Optimization)
                -- +1 point for every available slot (prefer emptier groups)
                v_score := v_score + (v_group_candidate.max_students - v_group_candidate.current_students);

                -- Track Best Group
                IF v_score > v_highest_score THEN
                    v_highest_score := v_score;
                    v_best_group := v_group_candidate;
                END IF;
            END IF;
        END LOOP;

        -- Record Result
        IF v_best_group IS NOT NULL THEN
            v_result := v_result || jsonb_build_object(
                'course_id', v_course_id,
                'course_name', v_course_name,
                'group_id', v_best_group.id,
                'group_name', v_best_group.group_name,
                'day_of_week', v_best_group.day_of_week,
                'start_time', v_best_group.start_time,
                'status', 'assigned',
                'reason', 'Optimized allocation'
            );
            
            -- Tentatively add this day to active days for subsequent iterations (to cluster new courses together too!)
            IF NOT (v_best_group.day_of_week = ANY(v_student_active_days)) THEN
                v_student_active_days := array_append(v_student_active_days, v_best_group.day_of_week);
            END IF;
        ELSE
            v_result := v_result || jsonb_build_object(
                'course_id', v_course_id,
                'course_name', v_course_name,
                'status', 'failed',
                'reason', 'No suitable group found (Conflict or Full)'
            );
        END IF;

    END LOOP;

    RETURN v_result;
END;
$$;


ALTER FUNCTION public.suggest_best_groups_for_student(p_student_id uuid, p_course_ids uuid[]) OWNER TO postgres;

