--
-- Name: toggle_vote(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.toggle_vote(p_target_type text, p_target_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_exists BOOLEAN;
BEGIN
  SELECT EXISTS(
    SELECT 1 FROM community_votes 
    WHERE user_id = auth.uid() 
    AND target_type = p_target_type 
    AND target_id = p_target_id
  ) INTO v_exists;
  
  IF v_exists THEN
    DELETE FROM community_votes 
    WHERE user_id = auth.uid() 
    AND target_type = p_target_type 
    AND target_id = p_target_id;
    RETURN false; -- تم إلغاء التصويت
  ELSE
    INSERT INTO community_votes (user_id, target_type, target_id)
    VALUES (auth.uid(), p_target_type, p_target_id);
    RETURN true; -- تم التصويت
  END IF;
END;
$$;


ALTER FUNCTION public.toggle_vote(p_target_type text, p_target_id uuid) OWNER TO postgres;

