--
-- Name: update_center_billing_config(uuid, text, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_center_billing_config(p_center_id uuid, p_billing_type text DEFAULT NULL::text, p_monthly_payment_mode text DEFAULT NULL::text, p_sessions_per_cycle integer DEFAULT NULL::integer, p_grace_sessions integer DEFAULT NULL::integer, p_max_debt_sessions integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_old_config JSONB;
  v_new_config JSONB;
  v_old_billing_type TEXT;
  v_students_updated INTEGER := 0;
BEGIN
  -- جلب الإعدادات الحالية
  SELECT billing_config INTO v_old_config
  FROM centers WHERE id = p_center_id;
  
  v_old_billing_type := v_old_config->>'billing_type';
  
  -- بناء الإعدادات الجديدة
  v_new_config := COALESCE(v_old_config, '{}'::jsonb);
  
  IF p_billing_type IS NOT NULL THEN
    v_new_config := jsonb_set(v_new_config, '{billing_type}', to_jsonb(p_billing_type));
  END IF;
  IF p_monthly_payment_mode IS NOT NULL THEN
    v_new_config := jsonb_set(v_new_config, '{monthly_payment_mode}', to_jsonb(p_monthly_payment_mode));
  END IF;
  IF p_sessions_per_cycle IS NOT NULL THEN
    v_new_config := jsonb_set(v_new_config, '{sessions_per_cycle}', to_jsonb(p_sessions_per_cycle));
  END IF;
  IF p_grace_sessions IS NOT NULL THEN
    v_new_config := jsonb_set(v_new_config, '{grace_sessions}', to_jsonb(p_grace_sessions));
  END IF;
  IF p_max_debt_sessions IS NOT NULL THEN
    v_new_config := jsonb_set(v_new_config, '{max_debt_sessions}', to_jsonb(p_max_debt_sessions));
  END IF;
  
  -- تحديث المركز
  UPDATE centers 
  SET billing_config = v_new_config, updated_at = NOW()
  WHERE id = p_center_id;
  
  -- إذا تغير نوع الدفع، حدّث كل الطلاب
  IF p_billing_type IS NOT NULL AND p_billing_type != v_old_billing_type THEN
    UPDATE student_group_enrollments sge
    SET 
      billing_type = 'inherit',
      sessions_debt = 0,
      current_month_paid = FALSE,
      updated_at = NOW()
    FROM groups g
    WHERE sge.group_id = g.id AND g.center_id = p_center_id;
    
    GET DIAGNOSTICS v_students_updated = ROW_COUNT;
  END IF;
  
  RETURN jsonb_build_object(
    'success', true,
    'old_config', v_old_config,
    'new_config', v_new_config,
    'students_updated', v_students_updated
  );
END;
$$;


ALTER FUNCTION public.update_center_billing_config(p_center_id uuid, p_billing_type text, p_monthly_payment_mode text, p_sessions_per_cycle integer, p_grace_sessions integer, p_max_debt_sessions integer) OWNER TO postgres;

--
-- Name: update_group_student_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_group_student_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_group_id UUID;
BEGIN
  -- Determine which group to update
  v_group_id := COALESCE(NEW.group_id, OLD.group_id);
  
  IF v_group_id IS NOT NULL THEN
    UPDATE groups
    SET 
      current_students = (
        SELECT COUNT(*)
        FROM student_group_enrollments
        WHERE group_id = v_group_id
          AND status = 'active'
      ),
      updated_at = NOW()
    WHERE id = v_group_id;
    
    -- Update status to 'full' if max capacity reached
    UPDATE groups
    SET status = CASE 
      WHEN current_students >= max_students THEN 'full'
      WHEN current_students < max_students AND status = 'full' THEN 'active'
      ELSE status
    END
    WHERE id = v_group_id;
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.update_group_student_count() OWNER TO postgres;

--
-- Name: update_invoice_on_payment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_invoice_on_payment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_invoice_id UUID;
  v_total_paid DECIMAL(10, 2);
  v_total_amount DECIMAL(10, 2);
BEGIN
  v_invoice_id := COALESCE(NEW.invoice_id, OLD.invoice_id);
  
  -- Calculate total paid
  SELECT COALESCE(SUM(amount), 0) INTO v_total_paid
  FROM invoice_payments
  WHERE invoice_id = v_invoice_id;
  
  -- Get invoice total
  SELECT total_amount INTO v_total_amount
  FROM student_invoices
  WHERE id = v_invoice_id;
  
  -- Update invoice
  UPDATE student_invoices
  SET 
    paid_amount = v_total_paid,
    status = CASE 
      WHEN v_total_paid >= v_total_amount THEN 'paid'
      WHEN v_total_paid > 0 THEN 'partial'
      ELSE 'pending'
    END,
    paid_date = CASE 
      WHEN v_total_paid >= v_total_amount THEN NOW()
      ELSE NULL
    END,
    updated_at = NOW()
  WHERE id = v_invoice_id;
  
  -- Also update student_enrollments payment_status
  UPDATE student_enrollments se
  SET payment_status = CASE 
    WHEN v_total_paid >= v_total_amount THEN 'paid'
    WHEN v_total_paid > 0 THEN 'partial'
    ELSE 'pending'
  END
  FROM student_invoices si
  WHERE si.id = v_invoice_id
    AND se.student_id = si.student_id
    AND se.center_id = si.center_id;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.update_invoice_on_payment() OWNER TO postgres;

--
-- Name: update_invoice_remaining_amount(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_invoice_remaining_amount() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.remaining_amount := COALESCE(NEW.total_amount, 0) - COALESCE(NEW.paid_amount, 0);
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.update_invoice_remaining_amount() OWNER TO postgres;

--
-- Name: update_invoices_on_subject_fee_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_invoices_on_subject_fee_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.monthly_fee <> OLD.monthly_fee THEN
    PERFORM recalculate_student_invoice(inv.id)
    FROM student_invoices inv
    JOIN student_enrollments se ON se.student_id = inv.student_id
    WHERE se.subject_id = NEW.id
      AND inv.status = 'pending'
      AND inv.center_id = NEW.center_id;
  END IF;
  RETURN NULL;
END;
$$;


