--
-- Name: update_pending_invoices_on_price_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_pending_invoices_on_price_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_subject_id UUID;
  v_group_id UUID;
  v_grade_level TEXT;
  v_affected_count INT := 0;
BEGIN
  -- تحديد نطاق التغيير (Subject/Group/Grade)
  v_subject_id := NEW.subject_id;
  v_group_id := NEW.group_id; -- يمكن أن يكون NULL
  v_grade_level := NEW.grade_level; -- يمكن أن يكون NULL
  
  -- إذا كان التغيير على مستوى مجموعة محددة
  IF v_group_id IS NOT NULL THEN
    -- نحدث فواتير طلاب هذه المجموعة فقط
    PERFORM recalculate_student_invoice(inv.id)
    FROM student_invoices inv
    JOIN student_group_enrollments sge ON sge.student_id = inv.student_id
    WHERE sge.group_id = v_group_id
      AND sge.is_active = true
      AND inv.status = 'pending' -- فقط المعلقة
      AND inv.center_id = NEW.center_id;
      
  -- إذا كان التغيير على مستوى مرحلة (grade_level)
  ELSIF v_grade_level IS NOT NULL THEN
    PERFORM recalculate_student_invoice(inv.id)
    FROM student_invoices inv
    JOIN students s ON s.id = inv.student_id
    JOIN student_enrollments se ON se.student_id = s.id
    WHERE s.grade_level = v_grade_level
      AND se.subject_id = v_subject_id
      AND inv.status = 'pending'
      AND inv.center_id = NEW.center_id;
      
  -- إذا كان تغيير عام للمادة (Default Price)
  ELSE
    PERFORM recalculate_student_invoice(inv.id)
    FROM student_invoices inv
    JOIN student_enrollments se ON se.student_id = inv.student_id
    WHERE se.subject_id = v_subject_id
      AND inv.status = 'pending'
      AND inv.center_id = NEW.center_id;
  END IF;

  RETURN NULL; -- After trigger, return ignored
END;
$$;


ALTER FUNCTION public.update_pending_invoices_on_price_change() OWNER TO postgres;

