--
-- Name: update_salary_totals(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_salary_totals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_salary_id UUID;
  v_sessions_total DECIMAL(10, 2);
  v_bonuses_total DECIMAL(10, 2);
  v_deductions_total DECIMAL(10, 2);
  v_base_salary DECIMAL(10, 2);
BEGIN
  v_salary_id := COALESCE(NEW.salary_id, OLD.salary_id);
  
  -- Get base salary
  SELECT base_salary INTO v_base_salary
  FROM teacher_salaries
  WHERE id = v_salary_id;
  
  -- Calculate sessions total
  SELECT COALESCE(SUM(amount), 0) INTO v_sessions_total
  FROM salary_items
  WHERE salary_id = v_salary_id
    AND item_type = 'session';
  
  -- Calculate bonuses total
  SELECT COALESCE(SUM(amount), 0) INTO v_bonuses_total
  FROM salary_items
  WHERE salary_id = v_salary_id
    AND item_type = 'bonus';
  
  -- Calculate deductions total
  SELECT COALESCE(SUM(amount), 0) INTO v_deductions_total
  FROM salary_items
  WHERE salary_id = v_salary_id
    AND item_type = 'deduction';
  
  -- Update salary record
  UPDATE teacher_salaries
  SET 
    sessions_amount = v_sessions_total,
    total_bonuses = v_bonuses_total,
    total_deductions = v_deductions_total,
    gross_salary = COALESCE(v_base_salary, 0) + v_sessions_total + v_bonuses_total,
    net_salary = COALESCE(v_base_salary, 0) + v_sessions_total + v_bonuses_total - v_deductions_total,
    updated_at = NOW()
  WHERE id = v_salary_id;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.update_salary_totals() OWNER TO postgres;

--
-- Name: update_student_profile(text, text, text, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_student_profile(p_full_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_parent_phone text DEFAULT NULL::text, p_birth_date date DEFAULT NULL::date) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_user_id UUID;
BEGIN
    v_user_id := auth.uid();
    
    -- Update users table
    IF p_full_name IS NOT NULL OR p_phone IS NOT NULL THEN
        UPDATE users
        SET 
            full_name = COALESCE(p_full_name, full_name),
            phone = COALESCE(p_phone, phone),
            updated_at = NOW()
        WHERE id = v_user_id;
    END IF;

    -- Update students table
    IF p_address IS NOT NULL OR p_parent_phone IS NOT NULL OR p_birth_date IS NOT NULL THEN
        INSERT INTO students (user_id, address, parent_phone, birth_date)
        VALUES (v_user_id, p_address, p_parent_phone, p_birth_date)
        ON CONFLICT (user_id) DO UPDATE
        SET
            address = COALESCE(p_address, students.address),
            parent_phone = COALESCE(p_parent_phone, students.parent_phone),
            birth_date = COALESCE(p_birth_date, students.birth_date);
    END IF;

    RETURN TRUE;
END;
$$;


ALTER FUNCTION public.update_student_profile(p_full_name text, p_phone text, p_address text, p_parent_phone text, p_birth_date date) OWNER TO postgres;

