--
-- Name: upsert_course_price(uuid, text, numeric, uuid, text, numeric, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upsert_course_price(p_center_id uuid, p_subject_name text, p_session_price numeric, p_teacher_id uuid DEFAULT NULL::uuid, p_grade_level text DEFAULT NULL::text, p_monthly_price numeric DEFAULT NULL::numeric, p_sessions_per_month integer DEFAULT 8, p_notes text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_id uuid;
begin
  -- Check if a price exists for this combination
  select id into v_id
  from course_prices
  where center_id = p_center_id
    and subject_name = p_subject_name
    and (teacher_id = p_teacher_id or (teacher_id is null and p_teacher_id is null))
    and (grade_level = p_grade_level or (grade_level is null and p_grade_level is null));

  if v_id is not null then
    -- Update existing
    update course_prices
    set
      session_price = p_session_price,
      monthly_price = p_monthly_price,
      sessions_per_month = p_sessions_per_month,
      notes = p_notes,
      updated_at = now()
    where id = v_id;
    
    return v_id::text;
  else
    -- Insert new
    insert into course_prices (
      center_id,
      subject_name,
      session_price,
      teacher_id,
      grade_level,
      monthly_price,
      sessions_per_month,
      notes,
      is_active
    ) values (
      p_center_id,
      p_subject_name,
      p_session_price,
      p_teacher_id,
      p_grade_level,
      p_monthly_price,
      p_sessions_per_month,
      p_notes,
      true
    )
    returning id into v_id;
    
    return v_id::text;
  end if;
end;
$$;


ALTER FUNCTION public.upsert_course_price(p_center_id uuid, p_subject_name text, p_session_price numeric, p_teacher_id uuid, p_grade_level text, p_monthly_price numeric, p_sessions_per_month integer, p_notes text) OWNER TO postgres;

--
-- Name: use_ai_credits(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.use_ai_credits(p_teacher_id uuid, p_credits_needed integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_available INTEGER;
    v_free INTEGER;
    v_total INTEGER;
BEGIN
    -- جلب الرصيد الحالي
    SELECT 
        COALESCE(free_credits, 0),
        COALESCE(total_credits, 0) - COALESCE(used_credits, 0)
    INTO v_free, v_total
    FROM public.ai_credits
    WHERE teacher_id = p_teacher_id;
    
    -- إذا لم يوجد سجل، أنشئ واحد
    IF NOT FOUND THEN
        INSERT INTO public.ai_credits (teacher_id, free_credits)
        VALUES (p_teacher_id, 50);
        v_free := 50;
        v_total := 0;
    END IF;
    
    v_available := v_free + v_total;
    
    -- تحقق من الرصيد
    IF v_available < p_credits_needed THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'insufficient_credits',
            'available', v_available,
            'needed', p_credits_needed
        );
    END IF;
    
    -- خصم من المجاني أولاً، ثم المدفوع
    IF v_free >= p_credits_needed THEN
        UPDATE public.ai_credits
        SET free_credits = free_credits - p_credits_needed,
            updated_at = now()
        WHERE teacher_id = p_teacher_id;
    ELSE
        UPDATE public.ai_credits
        SET free_credits = 0,
            used_credits = used_credits + (p_credits_needed - v_free),
            updated_at = now()
        WHERE teacher_id = p_teacher_id;
    END IF;
    
    RETURN jsonb_build_object(
        'success', true,
        'credits_used', p_credits_needed,
        'remaining', v_available - p_credits_needed
    );
END;
$$;


ALTER FUNCTION public.use_ai_credits(p_teacher_id uuid, p_credits_needed integer) OWNER TO postgres;

