    plan_name character varying(100) NOT NULL,
    description text,
    amount numeric(10,2) NOT NULL,
    currency character varying(3) DEFAULT 'EGP'::character varying,
    billing_cycle character varying(20) NOT NULL,
    start_date date NOT NULL,
    end_date date,
    status character varying(20) DEFAULT 'active'::character varying NOT NULL,
    auto_renew boolean DEFAULT true,
    next_billing_date date,
    last_billing_date date,
    payment_method character varying(50),
    included_courses jsonb,
    discount_percentage numeric(5,2) DEFAULT 0,
    notes text,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    cancellation_reason text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT check_subscription_dates CHECK (((end_date IS NULL) OR (end_date >= start_date))),
    CONSTRAINT subscriptions_billing_cycle_check CHECK (((billing_cycle)::text = ANY ((ARRAY['monthly'::character varying, 'quarterly'::character varying, 'semi-annual'::character varying, 'annual'::character varying])::text[]))),
    CONSTRAINT subscriptions_status_check CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'paused'::character varying, 'cancelled'::character varying, 'expired'::character varying])::text[])))
);


ALTER TABLE public.subscriptions OWNER TO postgres;

--
-- Name: active_subscriptions_stats; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.active_subscriptions_stats AS
 SELECT center_id,
    count(*) AS active_subscriptions,
    sum(amount) AS monthly_recurring_revenue,
    avg(amount) AS average_subscription_value
   FROM public.subscriptions
  WHERE ((status)::text = 'active'::text)
  GROUP BY center_id;


ALTER VIEW public.active_subscriptions_stats OWNER TO postgres;

