--
-- Name: course_prices_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.course_prices_view AS
 SELECT cp.id,
    cp.center_id,
    cp.subject_name,
    cp.teacher_id,
    COALESCE(u.full_name, 'أي مدرس'::text) AS teacher_name,
    COALESCE(cp.grade_level, 'كل المراحل'::character varying) AS grade_level,
    cp.session_price,
    COALESCE(cp.monthly_price, (cp.session_price * (cp.sessions_per_month)::numeric)) AS monthly_price,
    cp.sessions_per_month,
    cp.notes,
    cp.is_active,
    cp.valid_from,
    cp.valid_until,
        CASE
            WHEN ((cp.teacher_id IS NOT NULL) AND (cp.grade_level IS NOT NULL)) THEN 1
            WHEN ((cp.teacher_id IS NOT NULL) OR (cp.grade_level IS NOT NULL)) THEN 2
            ELSE 3
        END AS priority_level
   FROM ((public.course_prices cp
     LEFT JOIN public.teachers t ON ((cp.teacher_id = t.id)))
     LEFT JOIN public.users u ON ((t.user_id = u.id)))
  ORDER BY cp.subject_name,
        CASE
            WHEN ((cp.teacher_id IS NOT NULL) AND (cp.grade_level IS NOT NULL)) THEN 1
            WHEN ((cp.teacher_id IS NOT NULL) OR (cp.grade_level IS NOT NULL)) THEN 2
            ELSE 3
        END;


ALTER VIEW public.course_prices_view OWNER TO postgres;

