--

CREATE TABLE public.groups (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    center_id uuid NOT NULL,
    course_id uuid NOT NULL,
    teacher_id uuid,
    group_name text NOT NULL,
    group_code text,
    grade_level text,
    description text,
    max_students integer DEFAULT 30 NOT NULL,
    current_students integer DEFAULT 0 NOT NULL,
    day_of_week integer,
    start_time time without time zone,
    end_time time without time zone,
    monthly_fee numeric(10,2),
    status text DEFAULT 'active'::text,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    deleted_at timestamp without time zone,
    session_price numeric(10,2) DEFAULT 0,
    billing_override jsonb,
    price_override jsonb,
    CONSTRAINT groups_current_students_check CHECK ((current_students >= 0)),
    CONSTRAINT groups_day_of_week_check CHECK (((day_of_week >= 0) AND (day_of_week <= 6))),
    CONSTRAINT groups_max_students_check CHECK ((max_students > 0)),
    CONSTRAINT groups_status_check CHECK ((status = ANY (ARRAY['active'::text, 'full'::text, 'suspended'::text, 'archived'::text]))),
    CONSTRAINT valid_schedule_time CHECK ((((day_of_week IS NULL) AND (start_time IS NULL) AND (end_time IS NULL)) OR ((day_of_week IS NOT NULL) AND (start_time IS NOT NULL) AND (end_time IS NOT NULL) AND (end_time > start_time))))
);


