--
-- Name: student_billing_status; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.student_billing_status AS
 SELECT sge.id AS enrollment_id,
    sge.student_id,
    sge.group_id,
    g.group_name,
    g.monthly_fee,
        CASE
            WHEN ((sge.billing_type)::text <> 'inherit'::text) THEN (sge.billing_type)::text
            WHEN ((g.billing_override ->> 'billing_type'::text) IS NOT NULL) THEN (g.billing_override ->> 'billing_type'::text)
            ELSE COALESCE((c.billing_config ->> 'billing_type'::text), 'monthly'::text)
        END AS effective_billing_type,
    sge.sessions_purchased,
    sge.sessions_attended,
    sge.sessions_debt,
    ((sge.sessions_purchased - sge.sessions_attended) + sge.sessions_debt) AS sessions_remaining,
    sge.current_month_paid,
    sge.paid_until,
    COALESCE(((c.billing_config ->> 'grace_sessions'::text))::integer, 2) AS grace_sessions,
    COALESCE(((c.billing_config ->> 'max_debt_sessions'::text))::integer, 4) AS max_debt_sessions,
        CASE
            WHEN (sge.sessions_debt >= COALESCE(((c.billing_config ->> 'max_debt_sessions'::text))::integer, 4)) THEN 'blocked'::text
            WHEN (sge.sessions_debt >= COALESCE(((c.billing_config ->> 'grace_sessions'::text))::integer, 2)) THEN 'warning'::text
            WHEN (sge.sessions_debt > 0) THEN 'grace'::text
            ELSE 'ok'::text
        END AS payment_status
   FROM ((public.student_group_enrollments sge
     JOIN public.groups g ON ((g.id = sge.group_id)))
     JOIN public.centers c ON ((c.id = g.center_id)))
  WHERE (sge.status = 'active'::text);


ALTER VIEW public.student_billing_status OWNER TO postgres;

