--
-- Name: student_centers_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.student_centers_summary AS
 SELECT student_user_id,
    count(DISTINCT center_id) AS centers_count,
    count(DISTINCT
        CASE
            WHEN (status = 'accepted'::text) THEN center_id
            ELSE NULL::uuid
        END) AS active_centers
   FROM public.student_enrollments se
  WHERE (deleted_at IS NULL)
  GROUP BY student_user_id;


ALTER VIEW public.student_centers_summary OWNER TO postgres;

