--
-- Name: students_with_center; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.students_with_center AS
 SELECT u.id AS student_user_id,
    u.full_name,
    u.email,
    u.phone,
    u.avatar_url,
    u.created_at,
    se.center_id,
    se.student_id,
    se.status AS enrollment_status,
    se.enrolled_at,
    se.grade_level,
    se.payment_status,
    se.notes,
    COALESCE(counts.enrolled_courses_count, (0)::bigint) AS enrolled_courses_count
   FROM ((public.users u
     JOIN public.student_enrollments se ON ((u.id = se.student_user_id)))
     LEFT JOIN ( SELECT s.user_id AS student_user_id,
            count(DISTINCT g.course_id) AS enrolled_courses_count
           FROM (public.students s
             JOIN public.grades g ON ((s.id = g.student_id)))
          WHERE (g.course_id IS NOT NULL)
          GROUP BY s.user_id) counts ON ((counts.student_user_id = u.id)))
  WHERE ((se.deleted_at IS NULL) AND (u.deleted_at IS NULL) AND (u.role = 'student'::text) AND (se.status = 'accepted'::text));


ALTER VIEW public.students_with_center OWNER TO postgres;

