--
-- Name: teacher_stats; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.teacher_stats AS
 SELECT t.id AS teacher_id,
    t.user_id,
    count(DISTINCT tc.course_id) AS course_count,
    count(DISTINCT s.id) AS student_count
   FROM (((public.teachers t
     LEFT JOIN public.teacher_courses tc ON ((tc.teacher_id = t.id)))
     LEFT JOIN public.courses c ON (((c.id = tc.course_id) AND (c.deleted_at IS NULL))))
     LEFT JOIN public.student_enrollments s ON (((s.center_id = c.center_id) AND (s.deleted_at IS NULL))))
  GROUP BY t.id, t.user_id
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.teacher_stats OWNER TO postgres;

--
-- Name: teachers_with_center; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.teachers_with_center WITH (security_invoker='on') AS
 SELECT u.id AS teacher_user_id,
    u.full_name,
    u.email,
    u.phone,
    u.avatar_url,
    u.created_at,
    te.center_id,
    te.employment_status,
    te.hired_at AS hire_date,
    te.salary,
    te.specialization,
    count(DISTINCT tc.course_id) AS courses_count
   FROM ((public.users u
     JOIN public.teacher_enrollments te ON ((u.id = te.teacher_user_id)))
     LEFT JOIN public.teacher_courses tc ON (((tc.teacher_id = te.teacher_id) AND (tc.center_id = te.center_id))))
  WHERE ((te.deleted_at IS NULL) AND (u.deleted_at IS NULL) AND (u.role = 'teacher'::text))
  GROUP BY u.id, u.full_name, u.email, u.phone, u.avatar_url, u.created_at, te.center_id, te.employment_status, te.hired_at, te.salary, te.specialization;


ALTER VIEW public.teachers_with_center OWNER TO postgres;

